import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useLocation } from 'react-router-dom'
import { Brain, AlertTriangle, Lightbulb, MessageSquare, X } from 'lucide-react'
import { cn } from '@/utils/cn'
import { AICopilotEngine } from '@/engines/AICopilotEngine'
import { FinanceCopilotEngine } from '@/engines/FinanceCopilotEngine'
import { useCopilotSidebar } from '@/hooks/useCopilotSidebar'
import type { CopilotMessage, CopilotSidebarProps } from './CopilotTypes'
import { getContextForPath, generateAlerts, nextId } from './CopilotTypes'
import { ChatTab } from './CopilotChatTab'
import { AlertsTab } from './CopilotAlertsTab'
import { InsightsTab } from './CopilotInsightsTab'

export function CopilotSidebar({ gl, budget, className }: CopilotSidebarProps) {
  const { isOpen, activeTab, toggle, close, setActiveTab } = useCopilotSidebar()
  const location = useLocation()
  const scrollRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const [messages, setMessages] = useState<CopilotMessage[]>([])
  const [inputValue, setInputValue] = useState('')
  const [isProcessing, setIsProcessing] = useState(false)
  const [formulaResult, setFormulaResult] = useState<ReturnType<
    typeof AICopilotEngine.suggestFormula
  > | null>(null)

  const pageContext = useMemo(() => getContextForPath(location.pathname), [location.pathname])

  const alerts = useMemo(
    () => generateAlerts(gl, budget, pageContext.alertThreshold),
    [gl, budget, pageContext.alertThreshold]
  )

  const highAlertCount = useMemo(() => alerts.filter((a) => a.severity === 'high').length, [alerts])

  useEffect(() => {
    if (messages.length === 0) {
      setMessages([
        {
          id: 'welcome',
          role: 'assistant',
          content: `I'm your financial copilot. I can help with formulas, variance analysis, and data insights. You're on the **${pageContext.label}** page — try one of the suggestions below.`,
          timestamp: new Date(),
        },
      ])
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight
    }
  }, [messages])

  useEffect(() => {
    if (isOpen && inputRef.current) {
      const timer = setTimeout(() => inputRef.current?.focus(), 200)
      return () => clearTimeout(timer)
    }
  }, [isOpen])

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) close()
      if ((e.metaKey || e.ctrlKey) && e.key === 'j') {
        e.preventDefault()
        toggle()
      }
    }
    document.addEventListener('keydown', handler)
    return () => document.removeEventListener('keydown', handler)
  }, [isOpen, close, toggle])

  const sendMessage = useCallback(
    (text: string) => {
      if (!text.trim() || isProcessing) return

      const userMsg: CopilotMessage = {
        id: nextId('user'),
        role: 'user',
        content: text.trim(),
        timestamp: new Date(),
      }
      setMessages((prev) => [...prev, userMsg])
      setInputValue('')
      setIsProcessing(true)

      const formulaSuggestion = AICopilotEngine.suggestFormula(text)
      if (formulaSuggestion.confidence > 0) {
        setFormulaResult(formulaSuggestion)
      }

      setTimeout(() => {
        try {
          const answer = FinanceCopilotEngine.answer(text, { gl, budget })
          const assistantMsg: CopilotMessage = {
            id: nextId('assistant'),
            role: 'assistant',
            content: answer.answer,
            timestamp: new Date(),
            confidence: answer.confidence,
            sources: answer.sources,
            chartType: answer.chartType,
            formula: formulaSuggestion.confidence > 0 ? formulaSuggestion.formula : undefined,
          }
          setMessages((prev) => [...prev, assistantMsg])
        } catch {
          setMessages((prev) => [
            ...prev,
            {
              id: nextId('error'),
              role: 'assistant',
              content:
                'I could not process that. Try rephrasing or use one of the suggested prompts.',
              timestamp: new Date(),
            },
          ])
        } finally {
          setIsProcessing(false)
        }
      }, 200)
    },
    [gl, budget, isProcessing]
  )

  const handleSuggestionClick = useCallback(
    (suggestion: string) => {
      setInputValue(suggestion)
      sendMessage(suggestion)
    },
    [sendMessage]
  )

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault()
        sendMessage(inputValue)
      }
    },
    [inputValue, sendMessage]
  )

  const tabs = [
    { id: 'chat' as const, label: 'Chat', icon: MessageSquare },
    { id: 'alerts' as const, label: 'Alerts', icon: AlertTriangle, badge: highAlertCount },
    { id: 'suggestions' as const, label: 'Insights', icon: Lightbulb },
  ]

  return (
    <>
      {!isOpen && (
        <button
          onClick={toggle}
          className={cn(
            'fixed right-4 bottom-4 z-50 flex h-12 w-12 items-center justify-center rounded-full shadow-lg transition-all hover:scale-105',
            'bg-[var(--accent-primary)] text-white',
            className
          )}
          aria-label="Open AI Copilot (Ctrl+J)"
          title="AI Copilot (Ctrl+J)"
        >
          <Brain className="h-5 w-5" />
          {highAlertCount > 0 && (
            <span className="absolute -right-1 -top-1 flex h-5 w-5 items-center justify-center rounded-full bg-red-500 text-[10px] font-bold text-white">
              {highAlertCount}
            </span>
          )}
        </button>
      )}

      {isOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/40 md:hidden"
          onClick={close}
          aria-hidden="true"
        />
      )}

      <aside
        className={cn(
          'fixed right-0 top-0 z-50 flex h-full flex-col border-l shadow-2xl transition-transform duration-300',
          isOpen ? 'translate-x-0' : 'translate-x-full',
          'w-full sm:w-[380px] md:w-[400px]',
          className
        )}
        style={{
          background: 'var(--bg-surface)',
          borderColor: 'var(--border-subtle)',
        }}
        role="complementary"
        aria-label="AI Financial Copilot"
      >
        <div
          className="flex h-14 items-center justify-between border-b px-4"
          style={{ borderColor: 'var(--border-subtle)' }}
        >
          <div className="flex items-center gap-2.5">
            <div
              className="flex h-7 w-7 items-center justify-center rounded-lg"
              style={{ background: 'var(--accent-primary)', opacity: 0.9 }}
            >
              <Brain className="h-4 w-4 text-white" />
            </div>
            <div>
              <h2 className="text-sm font-semibold" style={{ color: 'var(--text-primary)' }}>
                AI Copilot
              </h2>
              <p className="text-[10px]" style={{ color: 'var(--text-muted)' }}>
                {pageContext.label} context
              </p>
            </div>
          </div>
          <div className="flex items-center gap-1">
            <kbd
              className="hidden rounded border px-1.5 py-0.5 text-[10px] font-medium md:inline-block"
              style={{
                borderColor: 'var(--border-subtle)',
                color: 'var(--text-muted)',
              }}
            >
              ⌘J
            </kbd>
            <button
              onClick={close}
              className="rounded-md p-1.5 transition-colors hover:bg-[var(--bg-elevated)]"
              style={{ color: 'var(--text-muted)' }}
              aria-label="Close copilot"
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </div>

        <div
          className="flex border-b px-2"
          style={{ borderColor: 'var(--border-subtle)' }}
          role="tablist"
        >
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={cn(
                'relative flex items-center gap-1.5 px-3 py-2.5 text-xs font-medium transition-colors',
                activeTab === tab.id
                  ? 'text-[var(--accent-primary)]'
                  : 'text-[var(--text-muted)] hover:text-[var(--text-secondary)]'
              )}
              role="tab"
              aria-selected={activeTab === tab.id}
            >
              <tab.icon className="w-3.5 h-3.5" />
              {tab.label}
              {tab.badge && tab.badge > 0 && (
                <span className="ml-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-red-500 px-1 text-[10px] font-bold text-white">
                  {tab.badge}
                </span>
              )}
              {activeTab === tab.id && (
                <div
                  className="absolute bottom-0 left-2 right-2 h-0.5 rounded-full"
                  style={{ background: 'var(--accent-primary)' }}
                />
              )}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-hidden">
          {activeTab === 'chat' && (
            <ChatTab
              messages={messages}
              inputValue={inputValue}
              isProcessing={isProcessing}
              pageContext={pageContext}
              formulaResult={formulaResult}
              scrollRef={scrollRef}
              inputRef={inputRef}
              onInputChange={setInputValue}
              onKeyDown={handleKeyDown}
              onSend={sendMessage}
              onSuggestionClick={handleSuggestionClick}
            />
          )}

          {activeTab === 'alerts' && (
            <AlertsTab alerts={alerts} gl={gl} budget={budget} highAlertCount={highAlertCount} />
          )}

          {activeTab === 'suggestions' && (
            <InsightsTab
              formulaResult={formulaResult}
              onFormulaResultChange={setFormulaResult}
              onSwitchToChat={() => setActiveTab('chat')}
            />
          )}
        </div>
      </aside>
    </>
  )
}

interface GaugeChartProps {
  value: number
  min?: number
  max?: number
  target?: number
  label?: string
  formatValue?: (v: number) => string
  size?: number
  ariaLabel?: string
  onClick?: () => void
}

export function GaugeChart({
  value,
  min = 0,
  max = 100,
  target,
  label,
  formatValue = (v) => `${v}%`,
  size = 160,
  ariaLabel = 'Gauge chart',
  onClick,
}: GaugeChartProps) {
  const radius = size / 2 - 10
  const cx = size / 2
  const cy = size / 2

  const startAngle = -135
  const endAngle = 135
  const range = endAngle - startAngle

  const valueAngle = startAngle + ((value - min) / (max - min)) * range
  const targetAngle =
    target !== undefined ? startAngle + ((target - min) / (max - min)) * range : undefined

  const toXY = (angle: number, r: number) => ({
    x: cx + r * Math.cos((angle * Math.PI) / 180),
    y: cy + r * Math.sin((angle * Math.PI) / 180),
  })

  const arcPath = (startA: number, endA: number, r: number) => {
    const start = toXY(startA, r)
    const end = toXY(endA, r)
    const largeArc = endA - startA > 180 ? 1 : 0
    return `M ${start.x} ${start.y} A ${r} ${r} 0 ${largeArc} 1 ${end.x} ${end.y}`
  }

  const getColor = () => {
    if (target === undefined) return '#3B82F6'
    const ratio = value / target
    if (ratio >= 1) return '#16A34A'
    if (ratio >= 0.8) return '#F59E0B'
    return '#DC2626'
  }

  const needleEnd = toXY(valueAngle, radius - 15)

  return (
    <div
      role="img"
      aria-label={`${ariaLabel}: ${formatValue(value)}`}
      data-testid="gauge-chart"
      className="flex flex-col items-center"
      onClick={onClick}
      onKeyDown={onClick ? (e) => { if (e.key === 'Enter' || e.key === ' ') onClick() } : undefined}
      style={{ cursor: onClick ? 'pointer' : 'default' }}
    >
      <svg width={size} height={size * 0.7} viewBox={`0 0 ${size} ${size * 0.7}`}>
        {/* Background arc */}
        <path
          d={arcPath(startAngle, endAngle, radius)}
          fill="none"
          stroke="#E5E7EB"
          strokeWidth={12}
          strokeLinecap="round"
        />

        {/* Value arc */}
        <path
          d={arcPath(startAngle, valueAngle, radius)}
          fill="none"
          stroke={getColor()}
          strokeWidth={12}
          strokeLinecap="round"
        />

        {/* Target marker */}
        {targetAngle !== undefined && (
          <circle {...toXY(targetAngle, radius)} r={4} fill="#111" stroke="#fff" strokeWidth={2} />
        )}

        {/* Needle */}
        <line
          x1={cx}
          y1={cy}
          x2={needleEnd.x}
          y2={needleEnd.y}
          stroke={getColor()}
          strokeWidth={2}
          strokeLinecap="round"
        />
        <circle cx={cx} cy={cy} r={4} fill={getColor()} />

        {/* Value text */}
        <text
          x={cx}
          y={cy + 20}
          textAnchor="middle"
          fontSize={20}
          fontWeight="bold"
          fill="currentColor"
        >
          {formatValue(value)}
        </text>
      </svg>
      {label && <div className="text-sm text-muted-foreground mt-1">{label}</div>}
    </div>
  )
}

import { LineChart, Line, ResponsiveContainer } from 'recharts'

interface SparklineChartProps {
  data: number[]
  color?: string
  height?: number
  width?: number
  ariaLabel?: string
  onClick?: () => void
}

export function SparklineChart({
  data,
  color = '#3B82F6',
  height = 40,
  width = 120,
  ariaLabel = 'Sparkline chart',
  onClick,
}: SparklineChartProps) {
  const chartData = data.map((value, index) => ({ index, value }))

  return (
    <div
      role="img"
      aria-label={ariaLabel}
      data-testid="sparkline-chart"
      onClick={onClick}
      onKeyDown={onClick ? (e) => { if (e.key === 'Enter' || e.key === ' ') onClick() } : undefined}
      className="dark:opacity-90"
      style={{ width, height, display: 'inline-block', cursor: onClick ? 'pointer' : 'default' }}
    >
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={chartData}>
          <Line type="monotone" dataKey="value" stroke={color} strokeWidth={1.5} dot={false} />
        </LineChart>
      </ResponsiveContainer>
    </div>
  )
}

import { useMemo } from 'react'
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Cell,
  ReferenceLine,
} from 'recharts'

export interface WaterfallDataPoint {
  name: string
  value: number
  fill?: string
}

interface WaterfallChartProps {
  data: WaterfallDataPoint[]
  height?: number
  formatValue?: (v: number) => string
  ariaLabel?: string
  onClick?: (dataPoint: WaterfallDataPoint, index: number) => void
}

interface ProcessedPoint extends WaterfallDataPoint {
  invisible: number
  visible: number
  fill: string
}

export function WaterfallChart({
  data,
  height = 400,
  formatValue = (v) => `$${v.toLocaleString()}`,
  ariaLabel = 'Waterfall chart',
  onClick,
}: WaterfallChartProps) {
  const processed: ProcessedPoint[] = useMemo(() => {
    let running = 0
    return data.map((d) => {
      const start = running
      running += d.value
      return {
        ...d,
        invisible: d.value >= 0 ? start : running,
        visible: Math.abs(d.value),
        fill: d.fill ?? (d.value >= 0 ? 'var(--positive)' : 'var(--negative)'),
      }
    })
  }, [data])

  const total = useMemo(() => data.reduce((s, d) => s + d.value, 0), [data])

  return (
    <div role="img" aria-label={ariaLabel} data-testid="waterfall-chart">
      <ResponsiveContainer width="100%" height={height}>
        <BarChart data={processed} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="var(--border-subtle, #334155)" />
          <XAxis dataKey="name" tick={{ fontSize: 12, fill: 'var(--text-secondary, #94a3b8)' }} />
          <YAxis
            tickFormatter={formatValue}
            tick={{ fontSize: 12, fill: 'var(--text-secondary, #94a3b8)' }}
          />
          <Tooltip
            formatter={
              ((value: number, _name: string, props: { payload: ProcessedPoint }) => [
                formatValue(props.payload.value),
                props.payload.name,
              ]) as unknown as React.ComponentProps<typeof Tooltip>['formatter']
            }
          />
          <ReferenceLine y={0} stroke="var(--text-muted, #666)" />
          <Bar dataKey="invisible" stackId="waterfall" fill="transparent" />
          <Bar
            dataKey="visible"
            stackId="waterfall"
            onClick={onClick ? (_entry, index) => onClick(data[index], index) : undefined}
            style={{ cursor: onClick ? 'pointer' : 'default' }}
          >
            {processed.map((entry, index) => (
              <Cell key={index} fill={entry.fill} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
      <div className="text-center text-sm text-muted-foreground mt-1">
        Total: {formatValue(total)}
      </div>
    </div>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import type { GridApi } from 'ag-grid-community'
import { cn } from '@/utils/cn'
import { Search, Replace, ChevronDown, ChevronUp, X, CaseSensitive, Regex } from 'lucide-react'

interface FindReplaceDialogProps {
  gridApi: GridApi | null
  isOpen: boolean
  onClose: () => void
}

interface MatchResult {
  rowIndex: number
  colId: string
  value: string
}

export function FindReplaceDialog({ gridApi, isOpen, onClose }: FindReplaceDialogProps) {
  const [findText, setFindText] = useState('')
  const [replaceText, setReplaceText] = useState('')
  const [matchCase, setMatchCase] = useState(false)
  const [useRegex, setUseRegex] = useState(false)
  const [searchInFormulas, setSearchInFormulas] = useState(false)
  const [matches, setMatches] = useState<MatchResult[]>([])
  const [currentMatchIdx, setCurrentMatchIdx] = useState(-1)
  const [replaceAllFeedback, setReplaceAllFeedback] = useState<string | null>(null)
  const findInputRef = useRef<HTMLInputElement>(null)

  // Focus input on open
  useEffect(() => {
    if (isOpen && findInputRef.current) {
      findInputRef.current.focus()
      findInputRef.current.select()
    }
  }, [isOpen])

  // Escape to close
  useEffect(() => {
    if (!isOpen) return
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    document.addEventListener('keydown', handler)
    return () => document.removeEventListener('keydown', handler)
  }, [isOpen, onClose])

  // Search for matches
  const handleFind = useCallback(() => {
    if (!gridApi || !findText) {
      setMatches([])
      setCurrentMatchIdx(-1)
      return
    }

    const results: MatchResult[] = []

    gridApi.forEachNode((node) => {
      if (!node.data) return
      const cols = gridApi.getColumns() ?? []
      for (const col of cols) {
        const colId = col.getColId()
        const rawValue = node.data[colId]
        if (rawValue == null) continue

        let cellStr: string
        if (searchInFormulas && typeof rawValue === 'string' && rawValue.startsWith('=')) {
          cellStr = rawValue
        } else {
          cellStr = String(rawValue)
        }

        const compareStr = matchCase ? cellStr : cellStr.toLowerCase()

        let isMatch = false
        if (useRegex) {
          try {
            const flags = matchCase ? 'g' : 'gi'
            const regex = new RegExp(findText, flags)
            isMatch = regex.test(cellStr)
          } catch {
            // Invalid regex — fall back to literal
            isMatch = compareStr.includes(matchCase ? findText : findText.toLowerCase())
          }
        } else {
          isMatch = compareStr.includes(matchCase ? findText : findText.toLowerCase())
        }

        if (isMatch) {
          results.push({
            rowIndex: node.rowIndex!,
            colId,
            value: cellStr,
          })
        }
      }
    })

    // eslint-disable-next-line react-hooks/set-state-in-effect
    setMatches(results)
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setCurrentMatchIdx(results.length > 0 ? 0 : -1)

    // Navigate to first match
    if (results.length > 0) {
      navigateToMatch(results[0])
    }
  }, [gridApi, findText, matchCase, useRegex, searchInFormulas])

  const navigateToMatch = useCallback(
    (match: MatchResult) => {
      if (!gridApi) return
      gridApi.setFocusedCell(match.rowIndex, match.colId)
      gridApi.ensureIndexVisible(match.rowIndex, 'middle')
    },
    [gridApi]
  )

  const goToNext = useCallback(() => {
    if (matches.length === 0) return
    const next = (currentMatchIdx + 1) % matches.length
    setCurrentMatchIdx(next)
    navigateToMatch(matches[next])
  }, [matches, currentMatchIdx, navigateToMatch])

  const goToPrev = useCallback(() => {
    if (matches.length === 0) return
    const prev = (currentMatchIdx - 1 + matches.length) % matches.length
    setCurrentMatchIdx(prev)
    navigateToMatch(matches[prev])
  }, [matches, currentMatchIdx, navigateToMatch])

  // Replace current match
  const handleReplace = useCallback(() => {
    if (!gridApi || currentMatchIdx < 0 || !matches[currentMatchIdx]) return
    const match = matches[currentMatchIdx]
    const node = gridApi.getDisplayedRowAtIndex(match.rowIndex)
    if (node?.data) {
      const oldValue = String(node.data[match.colId] ?? '')
      let newValue: string
      if (useRegex) {
        try {
          const flags = matchCase ? 'g' : 'gi'
          const regex = new RegExp(findText, flags)
          newValue = oldValue.replace(regex, replaceText)
        } catch {
          newValue = oldValue.split(findText).join(replaceText)
        }
      } else {
        const idx = matchCase
          ? oldValue.indexOf(findText)
          : oldValue.toLowerCase().indexOf(findText)
        if (idx >= 0) {
          newValue =
            oldValue.substring(0, idx) + replaceText + oldValue.substring(idx + findText.length)
        } else {
          newValue = oldValue
        }
      }
      node.setDataValue(match.colId, newValue)
    }
    // Move to next match
    goToNext()
    // Re-search to update match positions
    handleFind()
  }, [
    gridApi,
    currentMatchIdx,
    matches,
    findText,
    replaceText,
    matchCase,
    useRegex,
    goToNext,
    handleFind,
  ])

  // Replace all matches
  const handleReplaceAll = useCallback(() => {
    if (!gridApi || !findText) return
    let count = 0

    gridApi.forEachNode((node) => {
      if (!node.data) return
      const cols = gridApi.getColumns() ?? []
      for (const col of cols) {
        const colId = col.getColId()
        const rawValue = node.data[colId]
        if (rawValue == null) continue

        const cellStr = String(rawValue)
        const compareStr = matchCase ? cellStr : cellStr.toLowerCase()

        let isMatch = false
        if (useRegex) {
          try {
            const flags = matchCase ? 'g' : 'gi'
            const regex = new RegExp(findText, flags)
            isMatch = regex.test(cellStr)
          } catch {
            isMatch = compareStr.includes(matchCase ? findText : findText.toLowerCase())
          }
        } else {
          isMatch = compareStr.includes(matchCase ? findText : findText.toLowerCase())
        }

        if (isMatch) {
          let newValue: string
          if (useRegex) {
            try {
              const flags = matchCase ? 'g' : 'gi'
              const regex = new RegExp(findText, flags)
              newValue = cellStr.replace(regex, replaceText)
            } catch {
              newValue = cellStr.split(findText).join(replaceText)
            }
          } else {
            if (matchCase) {
              newValue = cellStr.split(findText).join(replaceText)
            } else {
              const regex = new RegExp(findText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi')
              newValue = cellStr.replace(regex, replaceText)
            }
          }
          node.setDataValue(colId, newValue)
          count++
        }
      }
    })

    setReplaceAllFeedback(`Replaced ${count} occurrence${count !== 1 ? 's' : ''}`)
    setTimeout(() => setReplaceAllFeedback(null), 3000)
    handleFind()
  }, [gridApi, findText, replaceText, matchCase, useRegex, handleFind])

  // Enter to find next
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault()
        if (e.shiftKey) {
          goToPrev()
        } else if (currentMatchIdx >= 0 && matches.length > 0) {
          goToNext()
        } else {
          handleFind()
        }
      }
    },
    [goToNext, goToPrev, handleFind, currentMatchIdx, matches.length]
  )

  if (!isOpen) return null

  return (
    <div
      className="fixed top-4 right-4 z-50 w-[420px] bg-[var(--bg-surface)] border border-[var(--border-subtle)] rounded-lg shadow-xl"
      role="dialog"
      aria-label="Find and Replace"
      onKeyDown={handleKeyDown}
    >
      {/* Header */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-[var(--border-subtle)]">
        <span className="text-sm font-semibold text-[var(--text-primary)]">Find and Replace</span>
        <button
          onClick={onClose}
          className="p-1 rounded hover:bg-[var(--bg-muted)] transition-colors"
          aria-label="Close"
        >
          <X className="w-4 h-4" />
        </button>
      </div>

      {/* Find row */}
      <div className="px-3 pt-3 pb-1">
        <div className="flex items-center gap-2">
          <Search className="w-4 h-4 text-[var(--text-tertiary)] flex-shrink-0" />
          <input
            ref={findInputRef}
            type="text"
            value={findText}
            onChange={(e) => setFindText(e.target.value)}
            placeholder="Find..."
            className="flex-1 px-2 py-1.5 text-sm border border-[var(--border-subtle)] rounded bg-[var(--bg-muted)] focus:outline-none focus:ring-2 focus:ring-blue-500/30"
            aria-label="Find text"
          />
          <div className="flex items-center gap-1">
            <button
              onClick={() => setMatchCase(!matchCase)}
              className={cn(
                'p-1.5 rounded transition-colors',
                matchCase
                  ? 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300'
                  : 'hover:bg-[var(--bg-muted)] text-[var(--text-tertiary)]'
              )}
              aria-label="Match case"
              title="Match Case"
            >
              <CaseSensitive className="w-4 h-4" />
            </button>
            <button
              onClick={() => setUseRegex(!useRegex)}
              className={cn(
                'p-1.5 rounded transition-colors',
                useRegex
                  ? 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300'
                  : 'hover:bg-[var(--bg-muted)] text-[var(--text-tertiary)]'
              )}
              aria-label="Use regex"
              title="Regular Expression"
            >
              <Regex className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* Replace row */}
      <div className="px-3 pb-2">
        <div className="flex items-center gap-2">
          <Replace className="w-4 h-4 text-[var(--text-tertiary)] flex-shrink-0" />
          <input
            type="text"
            value={replaceText}
            onChange={(e) => setReplaceText(e.target.value)}
            placeholder="Replace..."
            className="flex-1 px-2 py-1.5 text-sm border border-[var(--border-subtle)] rounded bg-[var(--bg-muted)] focus:outline-none focus:ring-2 focus:ring-blue-500/30"
            aria-label="Replace text"
          />
          <label className="flex items-center gap-1.5 text-xs text-[var(--text-tertiary)] cursor-pointer select-none">
            <input
              type="checkbox"
              checked={searchInFormulas}
              onChange={(e) => setSearchInFormulas(e.target.checked)}
              className="rounded"
            />
            Formulas
          </label>
        </div>
      </div>

      {/* Actions row */}
      <div className="flex items-center justify-between px-3 py-2 border-t border-[var(--border-subtle)] bg-[var(--bg-muted)] rounded-b-lg">
        <div className="flex items-center gap-1">
          <button
            onClick={goToPrev}
            disabled={matches.length === 0}
            className="p-1.5 rounded hover:bg-[var(--bg-surface)] disabled:opacity-30 transition-colors"
            aria-label="Previous match"
            title="Previous (Shift+Enter)"
          >
            <ChevronUp className="w-4 h-4" />
          </button>
          <button
            onClick={goToNext}
            disabled={matches.length === 0}
            className="p-1.5 rounded hover:bg-[var(--bg-surface)] disabled:opacity-30 transition-colors"
            aria-label="Next match"
            title="Next (Enter)"
          >
            <ChevronDown className="w-4 h-4" />
          </button>
          <span className="ml-2 text-xs text-[var(--text-tertiary)]" aria-live="polite">
            {matches.length > 0
              ? `${currentMatchIdx + 1} of ${matches.length}`
              : findText
                ? 'No results'
                : ''}
          </span>
        </div>
        <div className="flex items-center gap-1.5">
          {replaceAllFeedback && (
            <span className="text-xs fin-positive mr-2" role="status">
              {replaceAllFeedback}
            </span>
          )}
          <button
            onClick={handleReplace}
            disabled={currentMatchIdx < 0}
            className="px-2.5 py-1 text-xs font-medium rounded border border-[var(--border-subtle)] hover:bg-[var(--bg-surface)] disabled:opacity-30 transition-colors"
          >
            Replace
          </button>
          <button
            onClick={handleReplaceAll}
            disabled={matches.length === 0}
            className="px-2.5 py-1 text-xs font-medium rounded bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-30 transition-colors"
          >
            Replace All
          </button>
        </div>
      </div>
    </div>
  )
}

import { useEffect } from 'react'
import { Select } from '@/components/ui/Select'
import { CheckCircle2, AlertCircle } from 'lucide-react'
import { cn } from '@/utils/cn'

export interface GLColumnMapperProps {
  csvColumns: string[]
  mappings: Record<string, string>
  onMap: (field: string, csvCol: string) => void
  onAutoMap?: (newMappings: Record<string, string>) => void
}

const targetFields = [
  { key: 'accountCode', label: 'Account Code', required: true },
  { key: 'postDate', label: 'Posting Date', required: true },
  { key: 'debit', label: 'Debit', required: false },
  { key: 'credit', label: 'Credit', required: false },
  { key: 'entityId', label: 'Entity ID', required: false },
  { key: 'departmentId', label: 'Department ID', required: false },
  { key: 'description', label: 'Description', required: false },
]

function autoDetect(csvColumn: string): string | null {
  const lower = csvColumn.toLowerCase().trim()
  const fieldMap: Record<string, string> = {
    account: 'accountCode',
    code: 'accountCode',
    'account code': 'accountCode',
    acct: 'accountCode',
    date: 'postDate',
    'post date': 'postDate',
    'posting date': 'postDate',
    period: 'postDate',
    debit: 'debit',
    dr: 'debit',
    'amount dr': 'debit',
    credit: 'credit',
    cr: 'credit',
    'amount cr': 'credit',
    entity: 'entityId',
    company: 'entityId',
    'entity code': 'entityId',
    org: 'entityId',
    department: 'departmentId',
    dept: 'departmentId',
    'cost center': 'departmentId',
    cc: 'departmentId',
    description: 'description',
    desc: 'description',
    memo: 'description',
    narrative: 'description',
  }
  return fieldMap[lower] || null
}

export function GLColumnMapper({ csvColumns, mappings, onMap, onAutoMap }: GLColumnMapperProps) {
  useEffect(() => {
    if (onAutoMap && Object.keys(mappings).length === 0 && csvColumns.length > 0) {
      const newMappings: Record<string, string> = {}
      csvColumns.forEach((col) => {
        const field = autoDetect(col)
        if (field && !Object.values(newMappings).includes(col)) {
          newMappings[field] = col
        }
      })
      if (Object.keys(newMappings).length > 0) {
        onAutoMap(newMappings)
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- only run on mount when no mappings exist
  }, [csvColumns, onAutoMap])

  const options = [
    { value: '', label: '-- Skip Column --' },
    ...csvColumns.map((c) => ({ value: c, label: c })),
  ]

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {targetFields.map((f) => {
          const isMapped = !!mappings[f.key]
          return (
            <div
              key={f.key}
              className={cn(
                'p-4 rounded-lg border transition-colors',
                isMapped
                  ? 'bg-green-50/10 border-green-500/30'
                  : f.required
                    ? 'bg-red-50/10 border-red-500/30'
                    : 'bg-slate-900 border-slate-800'
              )}
            >
              <div className="flex items-center justify-between mb-2">
                <div className="flex items-center space-x-2">
                  <span className="text-sm font-bold text-slate-200">{f.label}</span>
                  {f.required && <span className="text-red-500 text-xs">*Required</span>}
                </div>
                {isMapped ? (
                  <CheckCircle2 className="h-4 w-4 text-green-500" />
                ) : (
                  f.required && <AlertCircle className="h-4 w-4 text-red-500" />
                )}
              </div>
              <Select
                value={mappings[f.key] || ''}
                onChange={(val) => onMap(f.key, val)}
                options={options}
                className="w-full"
              />
            </div>
          )
        })}
      </div>

      {csvColumns.length === 0 && (
        <div className="text-center py-8 bg-slate-900 rounded-lg border border-dashed border-slate-800">
          <p className="text-slate-400 text-sm">
            No columns detected. Please upload a valid CSV file.
          </p>
        </div>
      )}
    </div>
  )
}

