import { useCallback, useMemo, useState } from 'react';
import { Card } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import {
  ReportBookEngine,
  REPORT_TEMPLATE_PRESETS,
  type ReportBook,
  type ReportBookEntry,
  type Entity,
  type GenerationProgress,
} from '@/engines/ReportBookEngine';

// ---------------------------------------------------------------------------
// Mock data — replace with store selectors in production
// ---------------------------------------------------------------------------

const MOCK_ENTITIES: Entity[] = [
  { id: 'ent-1', name: 'Acme Corp (US)', currency: 'USD', parentId: null },
  { id: 'ent-2', name: 'Acme Europe (UK)', currency: 'GBP', parentId: 'ent-1' },
  { id: 'ent-3', name: 'Acme Asia (JP)', currency: 'JPY', parentId: 'ent-1' },
];

const PRESET_LIST = Object.values(REPORT_TEMPLATE_PRESETS);

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

interface PresetCardProps {
  preset: (typeof PRESET_LIST)[number];
  onAdd: (presetId: string, name: string) => void;
}

function PresetCard({ preset, onAdd }: PresetCardProps) {
  return (
    <button
      type="button"
      onClick={() => onAdd(preset.id, preset.name)}
      className="text-left w-full rounded-lg border border-slate-700 bg-slate-800/50 p-3 hover:border-blue-500 hover:bg-slate-800 transition-colors"
    >
      <p className="text-sm font-medium text-white">{preset.name}</p>
      <p className="text-xs text-slate-400 mt-1 line-clamp-2">{preset.description}</p>
    </button>
  );
}

interface EntryRowProps {
  entry: ReportBookEntry;
  entities: Entity[];
  onUpdate: (id: string, updates: Partial<ReportBookEntry>) => void;
  onRemove: (id: string) => void;
  onMoveUp: (id: string) => void;
  onMoveDown: (id: string) => void;
}

function EntryRow({ entry, entities, onUpdate, onRemove, onMoveUp, onMoveDown }: EntryRowProps) {
  return (
    <div className="flex items-start gap-3 rounded-lg border border-slate-700 bg-slate-800/30 p-3">
      {/* Drag handle / order controls */}
      <div className="flex flex-col gap-1 pt-1">
        <button
          type="button"
          onClick={() => onMoveUp(entry.id)}
          className="text-slate-500 hover:text-white text-xs"
          aria-label="Move up"
        >
          &#9650;
        </button>
        <span className="text-xs text-slate-500 text-center">{entry.order + 1}</span>
        <button
          type="button"
          onClick={() => onMoveDown(entry.id)}
          className="text-slate-500 hover:text-white text-xs"
          aria-label="Move down"
        >
          &#9660;
        </button>
      </div>

      {/* Report name + template */}
      <div className="flex-1 min-w-0 space-y-2">
        <input
          type="text"
          value={entry.reportName}
          onChange={(e) => onUpdate(entry.id, { reportName: e.target.value })}
          className="w-full bg-transparent border-b border-slate-600 text-white text-sm font-medium focus:border-blue-500 outline-none pb-1"
          placeholder="Report name"
        />
        <p className="text-xs text-slate-500">Template: {entry.templateId}</p>

        {/* Entity multi-select */}
        <div className="flex flex-wrap gap-1">
          {entities.map((entity) => (
            <button
              key={entity.id}
              type="button"
              onClick={() => {
                const next = entry.entityIds.includes(entity.id)
                  ? entry.entityIds.filter((id) => id !== entity.id)
                  : [...entry.entityIds, entity.id];
                onUpdate(entry.id, { entityIds: next });
              }}
              className={`text-xs px-2 py-0.5 rounded-full border transition-colors ${
                entry.entityIds.includes(entity.id)
                  ? 'bg-blue-600 border-blue-500 text-white'
                  : 'border-slate-600 text-slate-400 hover:border-slate-500'
              }`}
            >
              {entity.name}
            </button>
          ))}
        </div>

        {/* Variables */}
        {Object.keys(entry.variables).length > 0 && (
          <div className="flex flex-wrap gap-2">
            {Object.entries(entry.variables).map(([key, val]) => (
              <span key={key} className="text-xs text-slate-500">
                {`{${key}}`}:
                <input
                  type="text"
                  value={val}
                  onChange={(e) =>
                    onUpdate(entry.id, {
                      variables: { ...entry.variables, [key]: e.target.value },
                    })
                  }
                  className="ml-1 bg-transparent border-b border-slate-700 text-slate-300 w-20 text-xs focus:border-blue-500 outline-none"
                />
              </span>
            ))}
          </div>
        )}
      </div>

      {/* Actions */}
      <div className="flex items-center gap-2">
        <label className="flex items-center gap-1 text-xs text-slate-400">
          <input
            type="checkbox"
            checked={entry.enabled}
            onChange={(e) => onUpdate(entry.id, { enabled: e.target.checked })}
            className="rounded"
          />
          On
        </label>
        <button
          type="button"
          onClick={() => onRemove(entry.id)}
          className="text-red-400 hover:text-red-300 text-xs"
          aria-label="Remove entry"
        >
          &#10005;
        </button>
      </div>
    </div>
  );
}

interface ProgressBarProps {
  progress: GenerationProgress;
}

function ProgressBar({ progress }: ProgressBarProps) {
  const pct = progress.total > 0 ? Math.round((progress.completed / progress.total) * 100) : 0;

  return (
    <div className="space-y-2">
      <div className="flex justify-between text-xs text-slate-400">
        <span>
          {progress.currentReport && `${progress.currentReport} — ${progress.currentEntity}`}
        </span>
        <span>
          {progress.completed}/{progress.total} ({pct}%)
        </span>
      </div>
      <div className="h-2 rounded-full bg-slate-700 overflow-hidden">
        <div
          className={`h-full rounded-full transition-all duration-300 ${
            progress.status === 'error' ? 'bg-red-500' : 'bg-blue-500'
          }`}
          style={{ width: `${pct}%` }}
        />
      </div>
      {progress.errors.length > 0 && (
        <ul className="text-xs text-red-400 space-y-0.5">
          {progress.errors.map((err, i) => (
            <li key={i}>{err}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------

export function ReportBookBuilder() {
  const [engine] = useState(() => new ReportBookEngine());
  const [book, setBook] = useState<ReportBook>(() =>
    engine.createBook('Board Pack', 'Monthly board pack with all entities'),
  );
  const [progress, setProgress] = useState<GenerationProgress | null>(null);
  const [previewEntry, setPreviewEntry] = useState<ReportBookEntry | null>(null);

  const availableVars = useMemo(() => engine.getAvailableVariables(), [engine]);

  // --- Entry operations ---

  const handleAddPreset = useCallback(
    (presetId: string, name: string) => {
      const preset = PRESET_LIST.find((p) => p.id === presetId);
      const defaultVars: Record<string, string> = {};
      if (preset) {
        for (const v of Object.entries(preset.defaultVariables)) {
          defaultVars[v[0]] = v[1];
        }
      }

      engine.addEntry(book.id, {
        reportName: name,
        templateId: presetId,
        entityIds: MOCK_ENTITIES.map((e) => e.id),
        variables: defaultVars,
        enabled: true,
      });
      setBook({ ...engine.getBook(book.id)! });
    },
    [book.id, engine],
  );

  const handleUpdateEntry = useCallback(
    (entryId: string, updates: Partial<ReportBookEntry>) => {
      engine.updateEntry(book.id, entryId, updates);
      setBook({ ...engine.getBook(book.id)! });
    },
    [book.id, engine],
  );

  const handleRemoveEntry = useCallback(
    (entryId: string) => {
      if (!window.confirm('Remove this report entry?')) return;
      engine.removeEntry(book.id, entryId);
      setBook({ ...engine.getBook(book.id)! });
    },
    [book.id, engine],
  );

  const handleMoveUp = useCallback(
    (entryId: string) => {
      const idx = book.entries.findIndex((e) => e.id === entryId);
      if (idx <= 0) return;
      const ids = book.entries.map((e) => e.id);
      [ids[idx - 1], ids[idx]] = [ids[idx], ids[idx - 1]];
      engine.reorderEntries(book.id, ids);
      setBook({ ...engine.getBook(book.id)! });
    },
    [book.id, book.entries, engine],
  );

  const handleMoveDown = useCallback(
    (entryId: string) => {
      const idx = book.entries.findIndex((e) => e.id === entryId);
      if (idx === -1 || idx >= book.entries.length - 1) return;
      const ids = book.entries.map((e) => e.id);
      [ids[idx], ids[idx + 1]] = [ids[idx + 1], ids[idx]];
      engine.reorderEntries(book.id, ids);
      setBook({ ...engine.getBook(book.id)! });
    },
    [book.id, book.entries, engine],
  );

  // --- Generation ---

  const handleGenerate = useCallback(async () => {
    setProgress({
      total: 0,
      completed: 0,
      currentEntity: '',
      currentReport: '',
      status: 'pending',
      errors: [],
    });

    try {
      const results = await engine.generateReports(book.id, MOCK_ENTITIES, setProgress);
      // Results available for export
    } catch {
      // errors are captured in progress
    }
  }, [book.id, engine]);

  // --- Preview ---

  const previewData = useMemo(() => {
    if (!previewEntry) return null;
    const entity = MOCK_ENTITIES.find((e) => previewEntry.entityIds.includes(e.id));
    if (!entity) return null;

    // Mock preview — in production, call the registered generator
    return {
      headers: ['Line Item', 'Actual', 'Budget', 'Variance'],
      rows: [
        [previewEntry.reportName, '', '', ''],
        ['Revenue', '1,250,000', '1,200,000', '50,000'],
        ['COGS', '750,000', '720,000', '(30,000)'],
        ['Gross Profit', '500,000', '480,000', '20,000'],
      ],
    };
  }, [previewEntry]);

  // --- Render ---

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
      {/* LEFT: Template catalog */}
      <div className="lg:col-span-3 space-y-4">
        <h3 className="text-sm font-semibold text-white">Report Templates</h3>
        <div className="space-y-2">
          {PRESET_LIST.map((preset) => (
            <PresetCard key={preset.id} preset={preset} onAdd={handleAddPreset} />
          ))}
        </div>

        <div className="pt-4 border-t border-slate-700">
          <h4 className="text-xs font-medium text-slate-400 mb-2">Available Variables</h4>
          <div className="space-y-1">
            {availableVars.map((v) => (
              <div key={v.key} className="text-xs text-slate-500">
                <code className="text-blue-400">{`{${v.key}}`}</code> — {v.description}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* CENTER: Book entries */}
      <div className="lg:col-span-5 space-y-4">
        <div className="flex items-center justify-between">
          <div>
            <input
              type="text"
              value={book.name}
              onChange={(e) => {
                book.name = e.target.value;
                setBook({ ...book });
              }}
              className="text-lg font-bold text-white bg-transparent border-none outline-none"
            />
            <p className="text-xs text-slate-400">
              {book.entries.length} report(s) &middot;{' '}
              {book.entries.reduce((s, e) => s + e.entityIds.length, 0)} generation(s)
            </p>
          </div>
          <Button
            onClick={handleGenerate}
            disabled={book.entries.length === 0 || progress?.status === 'running'}
          >
            {progress?.status === 'running' ? 'Generating...' : 'Generate All'}
          </Button>
        </div>

        {progress && <ProgressBar progress={progress} />}

        <div className="space-y-2">
          {book.entries.length === 0 ? (
            <div className="text-center py-12 text-slate-500 text-sm">
              Add reports from the template catalog on the left.
            </div>
          ) : (
            book.entries.map((entry) => (
              <div
                key={entry.id}
                onClick={() => setPreviewEntry(entry)}
                onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') setPreviewEntry(entry) }}
                className={`cursor-pointer rounded-lg transition-all ${
                  previewEntry?.id === entry.id ? 'ring-1 ring-blue-500' : ''
                }`}
              >
                <EntryRow
                  entry={entry}
                  entities={MOCK_ENTITIES}
                  onUpdate={handleUpdateEntry}
                  onRemove={handleRemoveEntry}
                  onMoveUp={handleMoveUp}
                  onMoveDown={handleMoveDown}
                />
              </div>
            ))
          )}
        </div>
      </div>

      {/* RIGHT: Preview */}
      <div className="lg:col-span-4 space-y-4">
        <h3 className="text-sm font-semibold text-white">Preview</h3>
        {previewData ? (
          <Card className="p-4 bg-white dark:bg-gray-800 dark:bg-gray-800 text-slate-900 overflow-auto max-h-[600px]">
            <h4 className="font-bold text-sm mb-3">{previewEntry?.reportName}</h4>
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b-2 border-slate-300">
                  {previewData.headers.map((h, i) => (
                    <th key={i} className={`py-1 px-2 ${i > 0 ? 'text-right' : 'text-left'}`}>
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {previewData.rows.map((row, ri) => (
                  <tr key={ri} className="border-b border-slate-100">
                    {row.map((cell, ci) => (
                      <td
                        key={ci}
                        className={`py-1 px-2 ${ci > 0 ? 'text-right font-mono' : ''} ${
                          ri === 0 ? 'font-semibold' : ''
                        }`}
                      >
                        {String(cell)}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </Card>
        ) : (
          <div className="text-center py-12 text-slate-500 text-sm">
            Click a report entry to preview.
          </div>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { GripVertical, Plus, Trash2, Layers, Columns, Rows } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { cn } from '@/utils/cn';
import { ROW_TYPES } from './reportBuilder.constants';
import type { ReportLayout, RowType, ReportColumn, ReportRow, ReportCell } from '@/engines/ReportBuilderEngine';

function getRowColor(type: RowType): string {
  switch (type) {
    case 'total': return 'bg-green-500/20 text-green-400';
    case 'subtotal': return 'bg-blue-500/20 text-blue-400';
    case 'header': return 'bg-purple-500/20 text-purple-400';
    case 'blank': return 'bg-slate-600 text-slate-400';
    default: return 'bg-slate-700 text-slate-300';
  }
}

function getColColor(col: ReportColumn): string {
  if (col.type === 'label') return 'bg-purple-500/20 text-purple-400';
  if (col.period === 'actual') return 'bg-green-500/20 text-green-400';
  if (col.period === 'budget') return 'bg-blue-500/20 text-blue-400';
  if (col.period === 'variance') return 'bg-amber-500/20 text-amber-400';
  return 'bg-slate-600 text-slate-400';
}

function getRowLabel(row: ReportRow, columns: ReportColumn[]): string {
  const labelCell = row.cells.find((_: ReportCell, ci: number) => columns[ci]?.type === 'label');
  return (labelCell?.content as { content?: { text?: string } })?.content?.text ?? row.type;
}

export interface ReportLayoutEditorProps {
  layout: ReportLayout;
  selectedRowIndex: number | null;
  selectedColIndex: number | null;
  onSelectRow: (index: number | null) => void;
  onSelectCol: (index: number | null) => void;
  onAddRow: (type: RowType) => void;
  onRemoveRow: (rowId: string) => void;
  onAddColumn: () => void;
  onRemoveColumn: (colId: string) => void;
  onUpdateRowLabel: (rowIndex: number, text: string) => void;
  onUpdateRowType: (rowIndex: number, type: RowType) => void;
  onUpdateColumnHeader: (colIndex: number, header: string) => void;
  onUpdateColumnWidth: (colId: string, width: number) => void;
  onDrop: (e: React.DragEvent, target: 'rows' | 'columns') => void;
}

export function ReportLayoutEditor({
  layout,
  selectedRowIndex,
  selectedColIndex,
  onSelectRow,
  onSelectCol,
  onAddRow,
  onRemoveRow,
  onAddColumn,
  onRemoveColumn,
  onUpdateRowLabel,
  onUpdateRowType,
  onUpdateColumnHeader,
  onUpdateColumnWidth,
  onDrop,
}: ReportLayoutEditorProps) {
  const selectedRow = selectedRowIndex !== null ? layout.rows[selectedRowIndex] : null;
  const selectedCol = selectedColIndex !== null ? layout.columns[selectedColIndex] : null;

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      <div
        className="flex-1 overflow-y-auto"
        onDragOver={(e) => e.preventDefault()}
        onDrop={(e) => onDrop(e, 'rows')}
      >
        <div className="p-4 space-y-1">
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-xs font-semibold text-slate-400 uppercase flex items-center gap-1.5">
              <Rows className="h-3.5 w-3.5" />
              Rows ({layout.rows.length})
            </h3>
            <Button size="sm" variant="ghost" onClick={() => onAddRow('data')}>
              <Plus className="h-3.5 w-3.5 mr-1" />
              Add Row
            </Button>
          </div>

          {layout.rows.length === 0 ? (
            <div className="text-center py-8 text-slate-500 text-sm border-2 border-dashed border-slate-700 rounded-lg">
              Drag row types here or click Add Row
            </div>
          ) : (
            layout.rows.map((row, ri) => (
              <div
                key={row.id}
                className={cn(
                  'flex items-center gap-2 px-3 py-1.5 rounded border text-sm transition-colors cursor-pointer',
                  selectedRowIndex === ri
                    ? 'border-blue-500 bg-blue-500/10'
                    : 'border-slate-700 bg-slate-800/30 hover:border-slate-600'
                )}
                onClick={() => onSelectRow(ri)}
                onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') onSelectRow(ri) }}
              >
                <GripVertical className="h-3.5 w-3.5 text-slate-500 flex-shrink-0" />
                <span className={cn('text-xs font-mono px-1.5 py-0.5 rounded flex-shrink-0', getRowColor(row.type))}>
                  {row.type.charAt(0).toUpperCase()}
                </span>
                <span className="text-slate-300 truncate flex-1">
                  {getRowLabel(row, layout.columns)}
                </span>
                {row.grouping && (
                  <Layers className="h-3 w-3 text-slate-500 flex-shrink-0" />
                )}
                <button
                  className="text-slate-500 hover:text-red-400 flex-shrink-0"
                  onClick={(e) => { e.stopPropagation(); onRemoveRow(row.id); }}
                  aria-label={`Remove row ${ri + 1}`}
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              </div>
            ))
          )}
        </div>

        <div
          className="px-4 pb-4"
          onDragOver={(e) => e.preventDefault()}
          onDrop={(e) => onDrop(e, 'columns')}
        >
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-xs font-semibold text-slate-400 uppercase flex items-center gap-1.5">
              <Columns className="h-3.5 w-3.5" />
              Columns ({layout.columns.length})
            </h3>
            <Button size="sm" variant="ghost" onClick={onAddColumn}>
              <Plus className="h-3.5 w-3.5 mr-1" />
              Add Column
            </Button>
          </div>

          {layout.columns.length === 0 ? (
            <div className="text-center py-6 text-slate-500 text-sm border-2 border-dashed border-slate-700 rounded-lg">
              Drag column types here or click Add Column
            </div>
          ) : (
            <div className="flex flex-wrap gap-1">
              {layout.columns.map((col, ci) => (
                <div
                  key={col.id}
                  className={cn(
                    'flex items-center gap-1.5 px-2.5 py-1 rounded border text-xs transition-colors cursor-pointer',
                    selectedColIndex === ci
                      ? 'border-blue-500 bg-blue-500/10'
                      : 'border-slate-700 bg-slate-800/30 hover:border-slate-600'
                  )}
                  onClick={() => onSelectCol(ci)}
                  onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') onSelectCol(ci) }}
                >
                  <span className={cn('font-mono px-1 py-0.5 rounded', getColColor(col))}>
                    {col.type === 'label' ? 'L' : col.period?.charAt(0).toUpperCase() ?? 'C'}
                  </span>
                  <span className="text-slate-300">{col.header}</span>
                  <button
                    className="text-slate-500 hover:text-red-400 ml-1"
                    onClick={(e) => { e.stopPropagation(); onRemoveColumn(col.id); }}
                    aria-label={`Remove column ${col.header}`}
                  >
                    <Trash2 className="h-3 w-3" />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {(selectedRow || selectedCol) && (
        <div className="border-t border-slate-800 p-4 bg-slate-900/30">
          {selectedRow && selectedRowIndex !== null && (
            <div className="space-y-2">
              <p className="text-xs font-medium text-slate-400">
                Row {selectedRowIndex + 1} — {selectedRow.type}
              </p>
              <div className="flex gap-2">
                <input
                  type="text"
                  value={getRowLabel(selectedRow, layout.columns)}
                  onChange={(e) => onUpdateRowLabel(selectedRowIndex, e.target.value)}
                  placeholder="Row label..."
                  className="flex-1 bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm text-white"
                />
                <select
                  value={selectedRow.type}
                  onChange={(e) => onUpdateRowType(selectedRowIndex, e.target.value as RowType)}
                  className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm text-white"
                >
                  {ROW_TYPES.map((rt) => (
                    <option key={rt.type} value={rt.type}>{rt.label}</option>
                  ))}
                </select>
              </div>
            </div>
          )}
          {selectedCol && selectedColIndex !== null && (
            <div className="space-y-2">
              <p className="text-xs font-medium text-slate-400">
                Column {selectedColIndex + 1} — {selectedCol.type}
              </p>
              <div className="flex gap-2">
                <input
                  type="text"
                  value={selectedCol.header}
                  onChange={(e) => onUpdateColumnHeader(selectedColIndex, e.target.value)}
                  placeholder="Column header..."
                  className="flex-1 bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm text-white"
                />
                <input
                  type="number"
                  value={selectedCol.width}
                  onChange={(e) => onUpdateColumnWidth(selectedCol.id, parseInt(e.target.value, 10) || 100)}
                  className="w-20 bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm text-white"
                  min={40}
                  aria-label="Column width"
                />
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

