import { useCallback, useState } from 'react';
import type { ExportTemplate, TemplateSection, TemplateStyle, TemplateType } from '@/engines/ExportTemplateEngine';

interface TemplateDesignerProps {
  template?: ExportTemplate;
  onSave: (template: ExportTemplate) => void;
  onCancel: () => void;
}

const SECTION_TYPES: Array<{ value: TemplateSection['type']; label: string }> = [
  { value: 'cover', label: 'Cover Page' },
  { value: 'kpi_summary', label: 'KPI Summary' },
  { value: 'table', label: 'Data Table' },
  { value: 'text', label: 'Text Block' },
  { value: 'page_break', label: 'Page Break' },
];

const TEMPLATE_TYPES: Array<{ value: TemplateType; label: string }> = [
  { value: 'board_pack', label: 'Board Pack' },
  { value: 'pl_statement', label: 'P&L Statement' },
  { value: 'balance_sheet', label: 'Balance Sheet' },
  { value: 'cash_flow', label: 'Cash Flow' },
  { value: 'budget_vs_actual', label: 'Budget vs Actual' },
  { value: 'kpi_summary', label: 'KPI Summary' },
];

let nextId = 1;

export function TemplateDesigner({ template, onSave, onCancel }: TemplateDesignerProps) {
  const [name, setName] = useState(template?.name ?? 'New Template');
  const [description, setDescription] = useState(template?.description ?? '');
  const [type, setType] = useState<TemplateType>(template?.type ?? 'board_pack');
  const [sections, setSections] = useState<TemplateSection[]>(template?.sections ?? []);
  const [style, setStyle] = useState<TemplateStyle>(template?.style ?? {
    primaryColor: '#1E3A5F',
    secondaryColor: '#4A90D9',
    fontFamily: 'helvetica',
    headerFontSize: 10,
    bodyFontSize: 8,
    companyName: 'FinPlan Pro',
  });
  const [selectedSection, setSelectedSection] = useState<string | null>(null);

  const addSection = useCallback((sectionType: TemplateSection['type']) => {
    const id = `section-${Date.now()}-${nextId++}`;
    const newSection: TemplateSection = {
      id,
      type: sectionType,
      title: sectionType === 'cover' ? 'Cover Page' : sectionType === 'page_break' ? '' : `New ${sectionType.replace(/_/g, ' ')}`,
      order: sections.length,
      config: sectionType === 'cover' ? { title: name, subtitle: '', confidential: true }
        : sectionType === 'kpi_summary' ? { kpis: [] }
        : sectionType === 'table' ? { headers: [], rows: [] }
        : sectionType === 'text' ? { content: '' }
        : {},
    };
    setSections((prev) => [...prev, newSection]);
    setSelectedSection(id);
  }, [sections.length, name]);

  const removeSection = useCallback((id: string) => {
    setSections((prev) => prev.filter((s) => s.id !== id));
    if (selectedSection === id) setSelectedSection(null);
  }, [selectedSection]);

  const moveSection = useCallback((id: string, direction: 'up' | 'down') => {
    setSections((prev) => {
      const idx = prev.findIndex((s) => s.id === id);
      if (idx < 0) return prev;
      const target = direction === 'up' ? idx - 1 : idx + 1;
      if (target < 0 || target >= prev.length) return prev;
      const next = [...prev];
      [next[idx], next[target]] = [next[target], next[idx]];
      return next.map((s, i) => ({ ...s, order: i }));
    });
  }, []);

  const updateSectionTitle = useCallback((id: string, title: string) => {
    setSections((prev) => prev.map((s) => (s.id === id ? { ...s, title } : s)));
  }, []);

  const handleSave = useCallback(() => {
    const now = new Date().toISOString();
    onSave({
      id: template?.id ?? `tpl-custom-${Date.now()}`,
      name,
      type,
      description,
      sections: sections.map((s, i) => ({ ...s, order: i })),
      style,
      variables: [
        { key: 'entity', label: 'Entity', defaultValue: 'Company Name' },
        { key: 'period', label: 'Period', defaultValue: 'FY 2026' },
        { key: 'currency', label: 'Currency', defaultValue: 'USD' },
        { key: 'date', label: 'Date', defaultValue: new Date().toLocaleDateString() },
        { key: 'preparedBy', label: 'Prepared By', defaultValue: 'Finance Team' },
      ],
      createdAt: template?.createdAt ?? now,
      updatedAt: now,
    });
  }, [name, type, description, sections, style, template, onSave]);

  const active = sections.find((s) => s.id === selectedSection);

  return (
    <div className="flex h-full">
      {/* Left: Section list */}
      <div className="w-64 border-r border-[var(--border-subtle)] dark:border-gray-700 p-4 overflow-y-auto">
        <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-3">Sections</h3>
        <div className="space-y-1 mb-4">
          {sections.map((section) => (
            <div
              key={section.id}
              className={`flex items-center gap-2 px-2 py-1.5 rounded cursor-pointer text-sm ${
                selectedSection === section.id
                  ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300'
                  : 'hover:bg-[var(--bg-hover)] dark:hover:bg-gray-800 text-[var(--text-secondary)] dark:text-gray-400 dark:text-gray-500'
              }`}
              onClick={() => setSelectedSection(section.id)}
              onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') setSelectedSection(section.id) }}
            >
              <span className="flex-1 truncate">{section.title || section.type}</span>
              <button
                className="text-gray-400 dark:text-gray-500 hover:text-[var(--text-secondary)] dark:hover:text-gray-300"
                onClick={(e) => { e.stopPropagation(); moveSection(section.id, 'up'); }}
              >
                ↑
              </button>
              <button
                className="text-gray-400 dark:text-gray-500 hover:text-[var(--text-secondary)] dark:hover:text-gray-300"
                onClick={(e) => { e.stopPropagation(); moveSection(section.id, 'down'); }}
              >
                ↓
              </button>
              <button
                className="text-red-400 hover:fin-negative"
                onClick={(e) => { e.stopPropagation(); removeSection(section.id); }}
              >
                ×
              </button>
            </div>
          ))}
        </div>

        <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-2">Add Section</h3>
        <div className="space-y-1">
          {SECTION_TYPES.map((st) => (
            <button
              key={st.value}
              className="w-full text-left px-2 py-1.5 text-sm rounded bg-gray-50 dark:bg-gray-900 dark:bg-gray-800 hover:bg-[var(--bg-hover)] dark:hover:bg-gray-700 text-[var(--text-secondary)] dark:text-gray-400 dark:text-gray-500"
              onClick={() => addSection(st.value)}
            >
              + {st.label}
            </button>
          ))}
        </div>
      </div>

      {/* Center: Section editor */}
      <div className="flex-1 p-6 overflow-y-auto">
        <div className="max-w-2xl space-y-4">
          <div>
            <label htmlFor="tpl-name" className="block text-sm font-medium text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-1">Template Name</label>
            <input
              id="tpl-name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full px-3 py-2 border border-[var(--border-default)] dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 dark:bg-gray-800 text-[var(--text-primary)] dark:text-gray-100"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="tpl-type" className="block text-sm font-medium text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-1">Type</label>
              <select
                id="tpl-type"
                value={type}
                onChange={(e) => setType(e.target.value as TemplateType)}
                className="w-full px-3 py-2 border border-[var(--border-default)] dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 dark:bg-gray-800 text-[var(--text-primary)] dark:text-gray-100"
              >
                {TEMPLATE_TYPES.map((t) => (
                  <option key={t.value} value={t.value}>{t.label}</option>
                ))}
              </select>
            </div>
            <div>
              <label htmlFor="tpl-company" className="block text-sm font-medium text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-1">Company Name</label>
              <input
                id="tpl-company"
                type="text"
                value={style.companyName}
                onChange={(e) => setStyle((s) => ({ ...s, companyName: e.target.value }))}
                className="w-full px-3 py-2 border border-[var(--border-default)] dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 dark:bg-gray-800 text-[var(--text-primary)] dark:text-gray-100"
              />
            </div>
          </div>

          <div>
            <label htmlFor="tpl-desc" className="block text-sm font-medium text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-1">Description</label>
            <textarea
              id="tpl-desc"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={2}
              className="w-full px-3 py-2 border border-[var(--border-default)] dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 dark:bg-gray-800 text-[var(--text-primary)] dark:text-gray-100"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="tpl-primary-color" className="block text-sm font-medium text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-1">Primary Color</label>
              <input
                id="tpl-primary-color"
                type="color"
                value={style.primaryColor}
                onChange={(e) => setStyle((s) => ({ ...s, primaryColor: e.target.value }))}
                className="w-full h-10 border border-[var(--border-default)] dark:border-gray-600 rounded-md"
              />
            </div>
            <div>
              <label htmlFor="tpl-secondary-color" className="block text-sm font-medium text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-1">Secondary Color</label>
              <input
                id="tpl-secondary-color"
                type="color"
                value={style.secondaryColor}
                onChange={(e) => setStyle((s) => ({ ...s, secondaryColor: e.target.value }))}
                className="w-full h-10 border border-[var(--border-default)] dark:border-gray-600 rounded-md"
              />
            </div>
          </div>

          {/* Active section editor */}
          {active && (
            <div className="border border-[var(--border-subtle)] dark:border-gray-700 rounded-lg p-4 mt-4">
              <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 dark:text-gray-300 mb-3">
                Edit: {active.type.replace(/_/g, ' ')}
              </h4>
              <div>
                <label htmlFor="tpl-section-title" className="block text-xs font-medium text-[var(--text-muted)] dark:text-gray-400 dark:text-gray-500 mb-1">Section Title</label>
                <input
                  id="tpl-section-title"
                  type="text"
                  value={active.title}
                  onChange={(e) => updateSectionTitle(active.id, e.target.value)}
                  className="w-full px-3 py-2 border border-[var(--border-default)] dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 dark:bg-gray-800 text-[var(--text-primary)] dark:text-gray-100 text-sm"
                />
              </div>
              {active.type === 'table' && (
                <p className="mt-2 text-xs text-[var(--text-muted)]">
                  Configure table headers and rows in the template JSON or use the report builder for dynamic data binding.
                </p>
              )}
              {active.type === 'kpi_summary' && (
                <p className="mt-2 text-xs text-[var(--text-muted)]">
                  KPI cards are auto-populated from the data context. Customize labels in the template JSON.
                </p>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Right: Actions */}
      <div className="w-48 border-l border-[var(--border-subtle)] dark:border-gray-700 p-4 flex flex-col gap-2">
        <button
          onClick={handleSave}
          className="w-full px-3 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 text-sm font-medium"
        >
          Save Template
        </button>
        <button
          onClick={onCancel}
          className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 dark:text-gray-300 rounded-md hover:bg-gray-200 dark:hover:bg-gray-700 text-sm"
        >
          Cancel
        </button>
        <div className="mt-4 text-xs text-[var(--text-muted)] dark:text-gray-400 dark:text-gray-500">
          <p className="font-medium mb-1">Variables:</p>
          <p>{'{entity}'} — Company name</p>
          <p>{'{period}'} — Reporting period</p>
          <p>{'{currency}'} — Currency code</p>
          <p>{'{date}'} — Current date</p>
          <p>{'{preparedBy}'} — Author name</p>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useCallback } from 'react'
import { Plus, Trash2, ArrowRight, Play, Settings2 } from 'lucide-react'
import { cn } from '@/utils/cn'
import type { AllocationMethod, AllocationRule, AllocationResult } from '@/engines/AllocationEngine'
import { AllocationEngine } from '@/engines/AllocationEngine'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface AllocationSource {
  id: string
  label: string
  amount: number
}

export interface AllocationDriver {
  id: string
  label: string
  values: Record<string, number>
}

export interface AllocationRuleBuilderProps {
  sources: AllocationSource[]
  drivers: AllocationDriver[]
  targetOptions: Array<{ id: string; label: string }>
  onPreview?: (result: AllocationResult) => void
  onSave?: (rule: AllocationRule) => void
  className?: string
}

interface TargetRow {
  id: string
  dimensionMember: string
  percentage: number
  driverWeight: number
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const METHOD_OPTIONS: Array<{ value: AllocationMethod; label: string; description: string }> = [
  { value: 'direct', label: 'Direct', description: 'Allocate by fixed percentages' },
  {
    value: 'driver',
    label: 'Driver-Based',
    description: 'Allocate by driver values (headcount, revenue, etc.)',
  },
  {
    value: 'step-down',
    label: 'Step-Down',
    description: 'Sequential service department allocation',
  },
  {
    value: 'reciprocal',
    label: 'Reciprocal',
    description: 'Simultaneous service department allocation',
  },
]

const PRESET_DRIVERS = [
  { id: 'headcount', label: 'Headcount' },
  { id: 'revenue', label: 'Revenue' },
  { id: 'square_footage', label: 'Square Footage' },
  { id: 'machine_hours', label: 'Machine Hours' },
  { id: 'custom', label: 'Custom' },
]

function generateId(): string {
  return `rule-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export const AllocationRuleBuilder: React.FC<AllocationRuleBuilderProps> = ({
  sources,
  drivers,
  targetOptions,
  onPreview,
  onSave,
  className,
}) => {
  const [ruleName, setRuleName] = useState('')
  const [selectedSource, setSelectedSource] = useState('')
  const [method, setMethod] = useState<AllocationMethod>('direct')
  const [selectedDriver, setSelectedDriver] = useState('')
  const [targets, setTargets] = useState<TargetRow[]>([])
  const [isRecurring, setIsRecurring] = useState(false)
  const [period, setPeriod] = useState(new Date().toISOString().slice(0, 7))
  const [error, setError] = useState<string | null>(null)

  // --- Target management ---

  const addTarget = useCallback(() => {
    const usedMembers = new Set(targets.map((t) => t.dimensionMember))
    const available = targetOptions.find((o) => !usedMembers.has(o.id))
    if (!available) return

    setTargets((prev) => [
      ...prev,
      {
        id: `target-${Date.now()}`,
        dimensionMember: available.id,
        percentage: 0,
        driverWeight: 1,
      },
    ])
  }, [targets, targetOptions])

  const removeTarget = useCallback((id: string) => {
    setTargets((prev) => prev.filter((t) => t.id !== id))
  }, [])

  const updateTarget = useCallback((id: string, field: keyof TargetRow, value: string | number) => {
    setTargets((prev) => prev.map((t) => (t.id === id ? { ...t, [field]: value } : t)))
  }, [])

  // --- Preview / Save ---

  const buildRule = useCallback(
    (): AllocationRule => ({
      id: generateId(),
      name: ruleName || 'Untitled Allocation',
      sourceAccount: selectedSource,
      method,
      targets: targets.map((t) => ({
        dimensionMember: t.dimensionMember,
        percentage: t.percentage,
        driverWeight: t.driverWeight,
      })),
      driverDimension: method === 'driver' ? selectedDriver : undefined,
      period,
      isRecurring,
    }),
    [ruleName, selectedSource, method, targets, selectedDriver, period, isRecurring]
  )

  const handlePreview = useCallback(() => {
    setError(null)
    try {
      const rule = buildRule()
      const sourceAmount = sources.find((s) => s.id === selectedSource)?.amount ?? 0
      const driverValues = drivers.find((d) => d.id === selectedDriver)?.values ?? {}
      const result =
        method === 'driver'
          ? AllocationEngine.allocateByDriver(rule, sourceAmount, driverValues)
          : AllocationEngine.allocateDirect(rule, sourceAmount)
      onPreview?.(result)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Allocation failed')
    }
  }, [buildRule, sources, selectedSource, drivers, selectedDriver, method, onPreview])

  const handleSave = useCallback(() => {
    setError(null)
    try {
      const rule = buildRule()
      if (method === 'direct') AllocationEngine.validateDirectRule(rule)
      onSave?.(rule)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Validation failed')
    }
  }, [buildRule, method, onSave])

  // --- Percentage total for direct method ---

  const percentageTotal = targets.reduce((sum, t) => sum + t.percentage, 0)
  const percentageValid = method !== 'direct' || Math.abs(percentageTotal - 100) < 0.01

  // --- Render ---

  return (
    <div
      className={cn(
        'flex flex-col gap-4 p-4 bg-[var(--bg-surface)] rounded-lg border border-[var(--border-subtle)]',
        className
      )}
    >
      {/* Header */}
      <div className="flex items-center gap-2">
        <Settings2 className="h-5 w-5 text-blue-500" />
        <h3 className="text-sm font-semibold text-[var(--text-primary)]">
          Allocation Rule Builder
        </h3>
      </div>

      {/* Rule Name */}
      <label className="flex flex-col gap-1">
        <span className="text-xs font-medium text-slate-400">Rule Name</span>
        <input
          type="text"
          value={ruleName}
          onChange={(e) => setRuleName(e.target.value)}
          placeholder="e.g., Allocate IT Costs by Headcount"
          className="h-9 rounded-md border border-[var(--border-subtle)] bg-[var(--bg-elevated)] px-3 text-sm text-[var(--text-primary)] outline-none focus:ring-2 focus:ring-blue-500"
        />
      </label>

      {/* Source Selection */}
      <label className="flex flex-col gap-1">
        <span className="text-xs font-medium text-slate-400">Source</span>
        <select
          value={selectedSource}
          onChange={(e) => setSelectedSource(e.target.value)}
          className="h-9 rounded-md border border-[var(--border-subtle)] bg-[var(--bg-elevated)] px-3 text-sm text-[var(--text-primary)] outline-none focus:ring-2 focus:ring-blue-500"
        >
          <option value="">Select source...</option>
          {sources.map((s) => (
            <option key={s.id} value={s.id}>
              {s.label} (${s.amount.toLocaleString()})
            </option>
          ))}
        </select>
      </label>

      {/* Method Selection */}
      <label className="flex flex-col gap-1">
        <span className="text-xs font-medium text-slate-400">Method</span>
        <div className="grid grid-cols-2 gap-2">
          {METHOD_OPTIONS.map((opt) => (
            <button
              key={opt.value}
              type="button"
              onClick={() => setMethod(opt.value)}
              className={cn(
                'flex flex-col items-start gap-0.5 rounded-md border p-2.5 text-left transition-colors',
                method === opt.value
                  ? 'border-blue-500 bg-blue-500/10 text-blue-400'
                  : 'border-[var(--border-subtle)] hover:border-gray-400 text-[var(--text-secondary)]'
              )}
            >
              <span className="text-xs font-medium">{opt.label}</span>
              <span className="text-[10px] opacity-70">{opt.description}</span>
            </button>
          ))}
        </div>
      </label>

      {/* Driver Selection (driver method only) */}
      {method === 'driver' && (
        <label className="flex flex-col gap-1">
          <span className="text-xs font-medium text-slate-400">Driver</span>
          <select
            value={selectedDriver}
            onChange={(e) => setSelectedDriver(e.target.value)}
            className="h-9 rounded-md border border-[var(--border-subtle)] bg-[var(--bg-elevated)] px-3 text-sm text-[var(--text-primary)] outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">Select driver...</option>
            {PRESET_DRIVERS.map((d) => (
              <option key={d.id} value={d.id}>
                {d.label}
              </option>
            ))}
            {drivers.map((d) => (
              <option key={d.id} value={d.id}>
                {d.label}
              </option>
            ))}
          </select>
        </label>
      )}

      {/* Targets */}
      <div className="flex flex-col gap-2">
        <div className="flex items-center justify-between">
          <span className="text-xs font-medium text-slate-400">Targets</span>
          <button
            type="button"
            onClick={addTarget}
            disabled={targets.length >= targetOptions.length}
            className="flex items-center gap-1 rounded-md bg-blue-600 px-2 py-1 text-xs font-medium text-white transition-colors hover:bg-blue-700 disabled:opacity-50"
          >
            <Plus className="h-3 w-3" />
            Add Target
          </button>
        </div>

        {targets.length === 0 && (
          <p className="text-xs text-slate-500 italic">
            No targets added yet. Click "Add Target" to begin.
          </p>
        )}

        {targets.map((target) => (
          <div
            key={target.id}
            className="flex items-center gap-2 rounded-md border border-[var(--border-subtle)] bg-[var(--bg-elevated)] p-2"
          >
            <ArrowRight className="h-4 w-4 text-slate-500 shrink-0" />

            {/* Target member select */}
            <select
              value={target.dimensionMember}
              onChange={(e) => updateTarget(target.id, 'dimensionMember', e.target.value)}
              className="flex-1 h-8 rounded border border-[var(--border-subtle)] bg-[var(--bg-surface)] px-2 text-xs text-[var(--text-primary)] outline-none"
            >
              {targetOptions.map((opt) => (
                <option key={opt.id} value={opt.id}>
                  {opt.label}
                </option>
              ))}
            </select>

            {/* Percentage (direct method) */}
            {method === 'direct' && (
              <div className="flex items-center gap-1">
                <input
                  type="number"
                  min={0}
                  max={100}
                  step={0.01}
                  value={target.percentage}
                  onChange={(e) =>
                    updateTarget(target.id, 'percentage', parseFloat(e.target.value) || 0)
                  }
                  className="w-20 h-8 rounded border border-[var(--border-subtle)] bg-[var(--bg-surface)] px-2 text-xs text-[var(--text-primary)] text-right outline-none"
                />
                <span className="text-xs text-slate-500">%</span>
              </div>
            )}

            {/* Driver weight (driver method) */}
            {method === 'driver' && (
              <div className="flex items-center gap-1">
                <span className="text-[10px] text-slate-500">Weight</span>
                <input
                  type="number"
                  min={0}
                  step={0.1}
                  value={target.driverWeight}
                  onChange={(e) =>
                    updateTarget(target.id, 'driverWeight', parseFloat(e.target.value) || 0)
                  }
                  className="w-16 h-8 rounded border border-[var(--border-subtle)] bg-[var(--bg-surface)] px-2 text-xs text-[var(--text-primary)] text-right outline-none"
                />
              </div>
            )}

            {/* Remove button */}
            <button
              type="button"
              onClick={() => removeTarget(target.id)}
              className="p-1 rounded text-slate-500 hover:text-red-500 hover:bg-red-500/10 transition-colors"
            >
              <Trash2 className="h-3.5 w-3.5" />
            </button>
          </div>
        ))}

        {/* Percentage total indicator (direct method) */}
        {method === 'direct' && targets.length > 0 && (
          <div
            className={cn(
              'text-xs font-medium',
              percentageValid ? 'text-green-500' : 'text-red-500'
            )}
          >
            Total: {percentageTotal.toFixed(2)}% {percentageValid ? '✓' : '(must equal 100%)'}
          </div>
        )}
      </div>

      {/* Period & Recurring */}
      <div className="flex items-center gap-4">
        <label className="flex flex-col gap-1 flex-1">
          <span className="text-xs font-medium text-slate-400">Period</span>
          <input
            type="month"
            value={period}
            onChange={(e) => setPeriod(e.target.value)}
            className="h-9 rounded-md border border-[var(--border-subtle)] bg-[var(--bg-elevated)] px-3 text-sm text-[var(--text-primary)] outline-none focus:ring-2 focus:ring-blue-500"
          />
        </label>
        <label className="flex items-center gap-2 mt-5">
          <input
            type="checkbox"
            checked={isRecurring}
            onChange={(e) => setIsRecurring(e.target.checked)}
            className="h-4 w-4 rounded border-[var(--border-default)]"
          />
          <span className="text-xs text-[var(--text-secondary)]">Recurring</span>
        </label>
      </div>

      {/* Error display */}
      {error && (
        <div className="rounded-md bg-red-500/10 border border-red-500/30 px-3 py-2 text-xs text-red-400">
          {error}
        </div>
      )}

      {/* Actions */}
      <div className="flex items-center gap-2 pt-2 border-t border-[var(--border-subtle)]">
        <button
          type="button"
          onClick={handlePreview}
          disabled={!selectedSource || targets.length === 0}
          className="flex items-center gap-1.5 rounded-md bg-blue-600 px-4 py-2 text-xs font-medium text-white transition-colors hover:bg-blue-700 disabled:opacity-50"
        >
          <Play className="h-3.5 w-3.5" />
          Preview
        </button>
        <button
          type="button"
          onClick={handleSave}
          disabled={!selectedSource || targets.length === 0 || !ruleName}
          className="rounded-md border border-[var(--border-subtle)] px-4 py-2 text-xs font-medium text-[var(--text-secondary)] transition-colors hover:border-gray-400 disabled:opacity-50"
        >
          Save Rule
        </button>
      </div>
    </div>
  )
}

import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts'

interface ComboBar {
  key: string
  color?: string
  name: string
}
interface ComboLine {
  key: string
  color?: string
  name: string
}

interface ComboChartProps {
  data: Record<string, unknown>[]
  bars?: ComboBar[]
  lines?: ComboLine[]
  xAxisKey?: string
  xKey?: string
  yKeys?: Array<{ key: string; color: string; name: string }>
  height?: number
  title?: string
  className?: string
  loading?: boolean
  error?: string
  onClick?: (data: Record<string, unknown>) => void
}

export function ComboChart({
  data,
  bars: barsProp,
  lines: linesProp,
  xAxisKey,
  xKey,
  yKeys,
  height = 300,
  title,
  className,
  loading = false,
  error,
  onClick,
}: ComboChartProps) {
  const effectiveXKey = xAxisKey ?? xKey ?? ''
  const bars =
    barsProp ?? (yKeys ? yKeys.map((y) => ({ key: y.key, color: y.color, name: y.name })) : [])
  const lines = linesProp ?? []
  if (loading) {
    return (
      <div className={className}>
        <div className="flex items-center justify-center h-48">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500" />
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className={className}>
        <div className="flex items-center justify-center h-48 text-red-500 text-sm">{error}</div>
      </div>
    )
  }
  if (!data || data.length === 0)
    return <div className="flex items-center justify-center h-48 text-slate-400">No data</div>

  return (
    <div className={className}>
      {title && (
        <h3 className="text-sm font-semibold mb-3" style={{ color: 'var(--text-primary)' }}>
          {title}
        </h3>
      )}
      <ResponsiveContainer width="100%" height={height}>
        <ComposedChart
          data={data}
          margin={{ top: 5, right: 20, left: 10, bottom: 5 }}
          onClick={
            onClick
              ? (e) => {
                  const p = e as unknown as { activePayload?: Array<{ payload?: unknown }> }
                  p?.activePayload?.[0]?.payload &&
                    onClick(p.activePayload[0].payload as Record<string, unknown>)
                }
              : undefined
          }
        >
          <CartesianGrid strokeDasharray="3 3" stroke="var(--border-subtle)" vertical={false} />
          <XAxis dataKey={effectiveXKey} tick={{ fontSize: 11, fill: 'var(--text-muted)' }} />
          <YAxis tick={{ fontSize: 11, fill: 'var(--text-muted)' }} />
          <Tooltip
            contentStyle={{
              borderRadius: '8px',
              border: '1px solid var(--border-default)',
              background: 'var(--bg-surface)',
              fontSize: '12px',
            }}
          />
          <Legend wrapperStyle={{ fontSize: '12px' }} />
          {bars.map((b) => (
            <Bar
              key={b.key}
              dataKey={b.key}
              name={b.name}
              fill={b.color || '#3B82F6'}
              radius={[2, 2, 0, 0]}
              maxBarSize={24}
            />
          ))}
          {lines.map((l) => (
            <Line
              key={l.key}
              dataKey={l.key}
              name={l.name}
              stroke={l.color || '#10B981'}
              strokeWidth={2}
              dot={{ r: 3 }}
            />
          ))}
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  )
}

import React, { useState, useEffect, useRef, useMemo } from 'react'
import { Search, ArrowRight } from 'lucide-react'
import { FormulaAutoCompleteEngine } from '@/engines/FormulaAutoCompleteEngine'
export interface CommandItem {
  id: string
  label: string
  description?: string
  category: string
  shortcut?: string
  onSelect: () => void
}
interface CommandPaletteProps {
  items: CommandItem[]
  isOpen: boolean
  onClose: () => void
  placeholder?: string
}
export function CommandPalette({
  items,
  isOpen,
  onClose,
  placeholder = 'Search commands...',
}: CommandPaletteProps) {
  const [query, setQuery] = useState('')
  const [selectedIndex, setSelectedIndex] = useState(0)
  const inputRef = useRef<HTMLInputElement>(null)
  const listRef = useRef<HTMLDivElement>(null)
  const filteredItems = useMemo(() => {
    if (!query.trim()) return items
    const lowerQuery = query.toLowerCase()
    // If query starts with "=", show formula suggestions
    if (query.startsWith('=')) {
      const formulaQuery = query.slice(1).trim()
      const suggestions = FormulaAutoCompleteEngine.suggest(formulaQuery)
      return suggestions.map((s, i) => ({
        id: `formula-${s.text}-${i}`,
        label: s.text,
        description: s.description,
        category: 'Formulas',
        onSelect: () => {},
      }))
    }
    return items.filter(
      (item) =>
        item.label.toLowerCase().includes(lowerQuery) ||
        item.description?.toLowerCase().includes(lowerQuery) ||
        item.category.toLowerCase().includes(lowerQuery)
    )
  }, [items, query])
  const groupedItems = useMemo(() => {
    const groups = new Map<string, CommandItem[]>()
    for (const item of filteredItems) {
      const list = groups.get(item.category) ?? []
      list.push(item)
      groups.set(item.category, list)
    }
    return groups
  }, [filteredItems])
  useEffect(() => {
    if (isOpen) {
      setQuery('')
      setSelectedIndex(0)
      setTimeout(() => inputRef.current?.focus(), 50)
    }
  }, [isOpen])
  // Reset selectedIndex when query changes — render-phase derivation, no effect needed
  const [prevQuery, setPrevQuery] = useState(query)
  if (query !== prevQuery) {
    setPrevQuery(query)
    setSelectedIndex(0)
  }
  const handleKeyDown = (e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setSelectedIndex((prev) => Math.min(prev + 1, filteredItems.length - 1))
        break
      case 'ArrowUp':
        e.preventDefault()
        setSelectedIndex((prev) => Math.max(prev - 1, 0))
        break
      case 'Enter':
        e.preventDefault()
        if (filteredItems[selectedIndex]) {
          filteredItems[selectedIndex].onSelect()
          onClose()
        }
        break
      case 'Escape':
        e.preventDefault()
        onClose()
        break
    }
  }
  useEffect(() => {
    const selectedEl = listRef.current?.querySelector(`[data-index="${selectedIndex}"]`)
    selectedEl?.scrollIntoView({ block: 'nearest' })
  }, [selectedIndex])
  if (!isOpen) return null
  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center pt-[20vh] bg-black/50 backdrop-blur-sm"
      onClick={onClose}
      onKeyDown={(e) => { if (e.key === 'Escape') onClose() }}
      role="dialog"
      aria-modal="true"
      aria-label="Command palette"
    >
      <div
        className="w-full max-w-lg rounded-lg shadow-2xl border overflow-hidden animate-scale-in bg-[var(--bg-surface)] border-[var(--border-default)]"
        onClick={(e) => e.stopPropagation()}
        onKeyDown={(e) => e.stopPropagation()}
      >
        {/* Search Input */}
        <div className="flex items-center gap-3 p-4 border-b border-[var(--border-subtle)]">
          <Search className="w-5 h-5 text-[var(--text-secondary)]" />
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            role="combobox"
            aria-expanded="true"
            aria-controls="command-list"
            aria-activedescendant={
              filteredItems[selectedIndex] ? `cmd-${filteredItems[selectedIndex].id}` : undefined
            }
            aria-label="Search commands"
            className="flex-1 bg-transparent outline-none text-sm text-[var(--text-primary)]"
          />
          <kbd className="px-2 py-0.5 text-xs rounded border text-[var(--text-secondary)] border-[var(--border-subtle)]">
            ESC
          </kbd>
        </div>
        {/* Item List */}
        <div
          ref={listRef}
          id="command-list"
          role="listbox"
          aria-label="Commands"
          className="max-h-80 overflow-y-auto p-2"
        >
          {filteredItems.length === 0 ? (
            <div className="text-center py-8 text-[var(--text-secondary)]">
              <p className="text-sm">No commands found</p>
            </div>
          ) : (
            Array.from(groupedItems.entries()).map(([category, categoryItems]) => (
              <div key={category} className="mb-2">
                <div className="px-3 py-1 text-xs font-semibold uppercase tracking-wider text-[var(--text-secondary)]">
                  {category}
                </div>
                {categoryItems.map((item) => {
                  const globalIndex = filteredItems.findIndex((f) => f.id === item.id)
                  return (
                    <button
                      key={item.id}
                      id={`cmd-${item.id}`}
                      data-index={globalIndex}
                      role="option"
                      aria-selected={globalIndex === selectedIndex}
                      className={`w-full flex items-center gap-3 px-3 py-2 rounded text-sm transition-colors cursor-pointer text-[var(--text-primary)] ${
                        globalIndex === selectedIndex ? 'bg-[var(--bg-hover)]' : ''
                      }`}
                      onClick={() => {
                        item.onSelect()
                        onClose()
                      }}
                      onMouseEnter={() => setSelectedIndex(globalIndex)}
                    >
                      <span className="flex-1 text-left">{item.label}</span>
                      {item.shortcut && (
                        <kbd className="px-2 py-0.5 text-xs rounded border text-[var(--text-secondary)] border-[var(--border-subtle)]">
                          {item.shortcut}
                        </kbd>
                      )}
                      <ArrowRight className="w-3 h-3 opacity-60 text-[var(--text-secondary)]" />
                    </button>
                  )
                })}
              </div>
            ))
          )}
        </div>
        {/* Footer */}
        <div className="flex items-center justify-between px-4 py-2 border-t text-xs border-[var(--border-subtle)] text-[var(--text-secondary)]">
          <span>{filteredItems.length} results</span>
          <div className="flex items-center gap-4">
            <span className="flex items-center gap-1">
              <kbd className="px-1 py-0.5 rounded border border-[var(--border-subtle)]">↑↓</kbd>
              Navigate
            </span>
            <span className="flex items-center gap-1">
              <kbd className="px-1 py-0.5 rounded border border-[var(--border-subtle)]">↵</kbd>
              Select
            </span>
            <span className="flex items-center gap-1">
              <kbd className="px-1 py-0.5 rounded border border-[var(--border-subtle)]">Esc</kbd>
              Close
            </span>
          </div>
        </div>
      </div>
    </div>
  )
}

import React, { useState, useMemo, useRef } from 'react'
import { ChevronUp, ChevronDown, AlertCircle, Search } from 'lucide-react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { cn } from '@/utils/cn'

import { Skeleton } from './Skeleton'

export interface Column {
  key: string
  header: string
  sortable?: boolean
  filterable?: boolean
  render?: (value: unknown, row: Record<string, unknown>) => React.ReactNode
  width?: string
  align?: 'left' | 'right' | 'center'
  frozen?: boolean
}

export interface DataTableProps {
  columns: Column[]
  data: unknown[]
  sortable?: boolean
  filterable?: boolean
  onRowClick?: (row: Record<string, unknown>) => void
  onReorder?: (fromIndex: number, toIndex: number) => void
  pageSize?: number
  emptyMessage?: string
  loading?: boolean
  error?: string
  className?: string
}

const VIRTUAL_THRESHOLD = 100
const ROW_HEIGHT = 40

export const DataTable: React.FC<DataTableProps> = ({
  columns,
  data: rawData,
  sortable: globalSortable = true,
  filterable: globalFilterable = false,
  onRowClick,
  pageSize = 50,
  emptyMessage = 'No data available',
  loading = false,
  error,
  className,
}) => {
  const data = rawData as Record<string, unknown>[]
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' } | null>(
    null
  )
  const [filters, setFilters] = useState<Record<string, string>>({})
  const [currentPage, setCurrentPage] = useState(1)
  const scrollRef = useRef<HTMLDivElement>(null)

  // Handle sorting
  const sortedData = useMemo(() => {
    const items = [...data]
    if (sortConfig !== null) {
      items.sort((a, b) => {
        const aValue = String(a[sortConfig.key] ?? '')
        const bValue = String(b[sortConfig.key] ?? '')

        if (aValue < bValue) {
          return sortConfig.direction === 'asc' ? -1 : 1
        }
        if (aValue > bValue) {
          return sortConfig.direction === 'asc' ? 1 : -1
        }
        return 0
      })
    }
    return items
  }, [data, sortConfig])

  // Handle filtering
  const filteredData = useMemo(() => {
    return sortedData.filter((item) => {
      return Object.entries(filters).every(([key, value]) => {
        if (!value) return true
        const itemValue = item[key]
        return String(itemValue).toLowerCase().includes(value.toLowerCase())
      })
    })
  }, [sortedData, filters])

  // Virtual scrolling for large datasets
  const useVirtual = filteredData.length > VIRTUAL_THRESHOLD

  const virtualizer = useVirtual
    ? useVirtualizer({
        count: filteredData.length,
        getScrollElement: () => scrollRef.current,
        estimateSize: () => ROW_HEIGHT,
        overscan: 10,
      })
    : null

  // Handle pagination (simple internal) — disabled when virtual scrolling
  const paginatedData = useMemo(() => {
    if (useVirtual) return filteredData
    const startIndex = (currentPage - 1) * pageSize
    return filteredData.slice(startIndex, startIndex + pageSize)
  }, [filteredData, currentPage, pageSize, useVirtual])

  const requestSort = (key: string) => {
    let direction: 'asc' | 'desc' = 'asc'
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc'
    }
    setSortConfig({ key, direction })
  }

  const handleFilterChange = (key: string, value: string) => {
    setFilters((prev) => ({ ...prev, [key]: value }))
    setCurrentPage(1) // Reset to first page when filtering
  }

  if (error) {
    return (
      <div
        className={cn(
          'flex flex-col items-center justify-center p-8 rounded-lg border border-red-100 bg-red-50 fin-negative dark:border-red-900 dark:bg-red-950',
          className
        )}
      >
        <AlertCircle className="h-10 w-10 mb-2" />
        <h3 className="font-semibold text-lg">Error loading data</h3>
        <p className="text-sm opacity-90">{error}</p>
        <button
          onClick={() => window.location.reload()}
          className="mt-4 px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors text-sm font-medium"
        >
          Retry
        </button>
      </div>
    )
  }

  // Render a single row (shared between virtual and paginated modes)
  const renderRow = (row: Record<string, unknown>, rowIdx: number) => (
    <tr
      key={String(row.id ?? rowIdx)}
      className={cn(
        'transition-colors hover:bg-gray-50 dark:bg-gray-900/50 dark:hover:bg-gray-700/50 group',
        onRowClick && 'cursor-pointer'
      )}
      onClick={() => onRowClick?.(row)}
    >
      {columns.map((column) => (
        <td
          key={column.key}
          className={cn(
            'px-4 py-3 text-[var(--text-primary)] whitespace-nowrap',
            column.align === 'right' && 'text-right',
            column.align === 'center' && 'text-center'
          )}
        >
          {column.render ? column.render(row[column.key], row) : String(row[column.key] ?? '')}
        </td>
      ))}
    </tr>
  )

  // Virtual scrolling body
  const renderVirtualBody = () => {
    if (!virtualizer) return null
    const virtualItems = virtualizer.getVirtualItems()
    const totalSize = virtualizer.getTotalSize()
    const paddingTop = virtualItems.length > 0 ? virtualItems[0].start : 0
    const paddingBottom =
      virtualItems.length > 0 ? totalSize - virtualItems[virtualItems.length - 1].end : 0

    return (
      <tbody className="divide-y divide-[var(--border-subtle)]">
        {paddingTop > 0 && (
          <tr>
            <td colSpan={columns.length} style={{ height: paddingTop }} />
          </tr>
        )}
        {virtualItems.map((virtualRow) => {
          const row = filteredData[virtualRow.index]
          return (
            <tr
              key={String(row.id ?? virtualRow.index)}
              className={cn(
                'transition-colors hover:bg-gray-50 dark:bg-gray-900/50 dark:hover:bg-gray-700/50 group',
                onRowClick && 'cursor-pointer'
              )}
              onClick={() => onRowClick?.(row)}
              data-index={virtualRow.index}
            >
              {columns.map((column) => (
                <td
                  key={column.key}
                  className={cn(
                    'px-4 py-3 text-[var(--text-primary)] whitespace-nowrap',
                    column.align === 'right' && 'text-right',
                    column.align === 'center' && 'text-center'
                  )}
                >
                  {column.render
                    ? column.render(row[column.key], row)
                    : String(row[column.key] ?? '')}
                </td>
              ))}
            </tr>
          )
        })}
        {paddingBottom > 0 && (
          <tr>
            <td colSpan={columns.length} style={{ height: paddingBottom }} />
          </tr>
        )}
      </tbody>
    )
  }

  // Paginated body (original behavior)
  const renderPaginatedBody = () => (
    <tbody className="divide-y divide-[var(--border-subtle)]">
      {loading ? (
        Array.from({ length: 5 }).map((_, idx) => (
          <tr key={idx}>
            {columns.map((col) => (
              <td key={col.key} className="px-4 py-4">
                <Skeleton className="h-4 w-full" />
              </td>
            ))}
          </tr>
        ))
      ) : filteredData.length === 0 ? (
        <tr>
          <td
            colSpan={columns.length}
            className="px-4 py-12 text-center text-[var(--text-secondary)]"
          >
            <div className="flex flex-col items-center">
              <Search className="h-10 w-10 mb-2 opacity-20" />
              <p>{emptyMessage}</p>
            </div>
          </td>
        </tr>
      ) : (
        paginatedData.map((row, rowIdx) => renderRow(row, rowIdx))
      )}
    </tbody>
  )

  return (
    <div className={cn('w-full flex flex-col', className)}>
      <div
        ref={useVirtual ? scrollRef : undefined}
        className={cn(
          'overflow-x-auto rounded-lg border border-[var(--border-subtle)] shadow-sm',
          useVirtual && 'max-h-[600px] overflow-y-auto'
        )}
      >
        <table className="w-full text-sm text-left border-collapse bg-[var(--bg-surface)]">
          <thead className="bg-gray-50 dark:bg-gray-900/80 dark:bg-gray-800/80 border-b border-[var(--border-subtle)] sticky top-0 z-10">
            <tr>
              {columns.map((column) => {
                const isSortable = globalSortable && column.sortable !== false
                const isSorted = sortConfig?.key === column.key

                return (
                  <th
                    key={column.key}
                    style={{ width: column.width }}
                    className={cn(
                      'px-4 py-3 font-semibold text-[var(--text-secondary)] transition-colors',
                      isSortable &&
                        'cursor-pointer hover:bg-[var(--bg-hover)] dark:hover:bg-gray-700 select-none'
                    )}
                    onClick={() => isSortable && requestSort(column.key)}
                  >
                    <div
                      className={cn(
                        'flex items-center space-x-1',
                        column.align === 'right' && 'justify-end',
                        column.align === 'center' && 'justify-center'
                      )}
                    >
                      <span>{column.header}</span>
                      {isSortable && (
                        <div className="flex flex-col">
                          <ChevronUp
                            className={cn(
                              'h-3 w-3 -mb-1',
                              isSorted && sortConfig?.direction === 'asc'
                                ? 'text-blue-600'
                                : 'text-gray-300'
                            )}
                          />
                          <ChevronDown
                            className={cn(
                              'h-3 w-3',
                              isSorted && sortConfig?.direction === 'desc'
                                ? 'text-blue-600'
                                : 'text-gray-300'
                            )}
                          />
                        </div>
                      )}
                    </div>
                    {globalFilterable && column.filterable !== false && (
                      <div
                        className="mt-2"
                        onClick={(e) => e.stopPropagation()}
                        onKeyDown={(e) => e.stopPropagation()}
                        role="presentation"
                      >
                        <div className="relative">
                          <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3 w-3 text-gray-400 dark:text-gray-500" />
                          <input
                            type="text"
                            className="w-full pl-7 pr-2 py-1 bg-white dark:bg-gray-800 dark:bg-gray-800 border border-[var(--border-subtle)] rounded text-xs outline-none focus:ring-1 focus:ring-blue-500 font-normal dark:text-white"
                            placeholder="Filter..."
                            value={filters[column.key] || ''}
                            onChange={(e) => handleFilterChange(column.key, e.target.value)}
                          />
                        </div>
                      </div>
                    )}
                  </th>
                )
              })}
            </tr>
          </thead>
          {useVirtual ? renderVirtualBody() : renderPaginatedBody()}
        </table>
      </div>

      {useVirtual && !loading && (
        <div className="mt-2 text-xs text-[var(--text-secondary)] text-center">
          Showing all {filteredData.length.toLocaleString()} rows (virtual scrolling)
        </div>
      )}

      {!loading && !useVirtual && filteredData.length > pageSize && (
        <div className="mt-4 flex items-center justify-between text-xs text-[var(--text-secondary)]">
          <span>
            Showing {Math.min(filteredData.length, (currentPage - 1) * pageSize + 1)} to{' '}
            {Math.min(filteredData.length, currentPage * pageSize)} of {filteredData.length} entries
          </span>
          <div className="flex items-center space-x-1">
            <button
              disabled={currentPage === 1}
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
              className="px-2 py-1 rounded border border-[var(--border-subtle)] hover:bg-gray-50 dark:bg-gray-900 dark:hover:bg-gray-700 disabled:opacity-50 transition-colors"
            >
              Previous
            </button>
            <span className="px-3 font-medium text-[var(--text-primary)]">
              Page {currentPage} of {Math.ceil(filteredData.length / pageSize)}
            </span>
            <button
              disabled={currentPage >= Math.ceil(filteredData.length / pageSize)}
              onClick={() => setCurrentPage((p) => p + 1)}
              className="px-2 py-1 rounded border border-[var(--border-subtle)] hover:bg-gray-50 dark:bg-gray-900 dark:hover:bg-gray-700 disabled:opacity-50 transition-colors"
            >
              Next
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

import React, { useState, useCallback, useRef, useEffect } from 'react'
import { cn } from '@/utils/cn'

export type FillMode = 'copy' | 'series' | 'linear' | 'growth'

export interface DragFillProps {
  /** Starting value(s) for the fill */
  values: (number | string)[]
  /** Called when fill completes with generated values */
  onFill: (values: (number | string)[], count: number) => void
  /** Number of cells to fill */
  fillCount?: number
  /** Direction of fill */
  direction?: 'down' | 'right'
  /** Visual position of the handle */
  className?: string
}

interface FillSuggestion {
  mode: FillMode
  label: string
  values: (number | string)[]
}

function detectFillPattern(values: (number | string)[]): FillMode {
  if (values.length < 2) return 'copy'

  const nums = values.filter((v): v is number => typeof v === 'number')
  if (nums.length < 2) return 'copy'

  // Check for arithmetic series (constant difference)
  const diffs: number[] = []
  for (let i = 1; i < nums.length; i++) {
    diffs.push(nums[i] - nums[i - 1])
  }
  const allSameDiff = diffs.every((d) => Math.abs(d - diffs[0]) < 0.0001)
  if (allSameDiff && diffs[0] !== 0) return 'linear'

  // Check for geometric series (constant ratio)
  const ratios: number[] = []
  for (let i = 1; i < nums.length; i++) {
    if (nums[i - 1] !== 0) {
      ratios.push(nums[i] / nums[i - 1])
    }
  }
  const allSameRatio = ratios.length > 0 && ratios.every((r) => Math.abs(r - ratios[0]) < 0.0001)
  if (allSameRatio && ratios[0] !== 1) return 'growth'

  return 'copy'
}

function generateFillValues(
  values: (number | string)[],
  mode: FillMode,
  count: number
): (number | string)[] {
  const result: (number | string)[] = []

  if (mode === 'copy') {
    for (let i = 0; i < count; i++) {
      result.push(values[i % values.length])
    }
  } else if (mode === 'linear' && values.length >= 2) {
    const nums = values.filter((v): v is number => typeof v === 'number')
    if (nums.length >= 2) {
      const diff = nums[nums.length - 1] - nums[nums.length - 2]
      const lastNum = nums[nums.length - 1]
      for (let i = 0; i < count; i++) {
        result.push(lastNum + diff * (i + 1))
      }
    }
  } else if (mode === 'growth' && values.length >= 2) {
    const nums = values.filter((v): v is number => typeof v === 'number')
    if (nums.length >= 2 && nums[nums.length - 2] !== 0) {
      const ratio = nums[nums.length - 1] / nums[nums.length - 2]
      const lastNum = nums[nums.length - 1]
      for (let i = 0; i < count; i++) {
        result.push(lastNum * Math.pow(ratio, i + 1))
      }
    }
  } else {
    // Fallback to copy
    for (let i = 0; i < count; i++) {
      result.push(values[i % values.length])
    }
  }

  return result
}

export function DragFill({
  values,
  onFill,
  fillCount = 10,
  direction = 'down',
  className,
}: DragFillProps) {
  const [isDragging, setIsDragging] = useState(false)
  const [showMenu, setShowMenu] = useState(false)
  const handleRef = useRef<HTMLDivElement>(null)

  const pattern = detectFillPattern(values)

  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      e.preventDefault()
      setIsDragging(true)

      // Quick drag = auto-fill with detected pattern
      const startX = e.clientX
      const startY = e.clientY

      const handleMouseMove = (moveE: MouseEvent) => {
        const distance =
          direction === 'down' ? Math.abs(moveE.clientY - startY) : Math.abs(moveE.clientX - startX)

        if (distance > 20) {
          // Threshold reached, auto-fill
          const generated = generateFillValues(values, pattern, fillCount)
          onFill(generated, fillCount)
          cleanup()
        }
      }

      const handleMouseUp = () => {
        // Short click = show mode menu
        setShowMenu(true)
        cleanup()
      }

      const cleanup = () => {
        setIsDragging(false)
        document.removeEventListener('mousemove', handleMouseMove)
        document.removeEventListener('mouseup', handleMouseUp)
      }

      document.addEventListener('mousemove', handleMouseMove)
      document.addEventListener('mouseup', handleMouseUp)
    },
    [values, fillCount, direction, pattern, onFill]
  )

  const handleModeSelect = useCallback(
    (mode: FillMode) => {
      const generated = generateFillValues(values, mode, fillCount)
      onFill(generated, fillCount)
      setShowMenu(false)
    },
    [values, fillCount, onFill]
  )

  // Close menu on outside click
  useEffect(() => {
    if (!showMenu) return
    const handleClick = () => setShowMenu(false)
    window.addEventListener('click', handleClick)
    return () => window.removeEventListener('click', handleClick)
  }, [showMenu])

  return (
    <div className={cn('relative inline-block', className)}>
      {/* Drag handle */}
      <div
        ref={handleRef}
        className={cn(
          'absolute w-3 h-3 bg-blue-600 border-2 border-white rounded-sm cursor-crosshair shadow-md z-10',
          'hover:bg-blue-500 hover:scale-125 transition-all',
          isDragging && 'bg-blue-500 scale-125',
          direction === 'down' ? '-bottom-1.5 right-0' : '-right-1.5 bottom-0'
        )}
        onMouseDown={handleMouseDown}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault()
            setShowMenu((prev) => !prev)
          }
        }}
        role="button"
        aria-label="Drag to fill cells"
        aria-haspopup="menu"
        tabIndex={0}
      />

      {/* Fill mode menu */}
      {showMenu && (
        <div
          className="absolute z-50 bg-white dark:bg-gray-800 border border-[var(--border-subtle)] rounded-lg shadow-xl py-1.5 min-w-[160px] top-full right-0 mt-1"
          onClick={(e) => e.stopPropagation()}
          onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') e.stopPropagation() }}
        >
          <div className="px-3 py-1 text-[10px] font-semibold text-gray-400 dark:text-gray-500 uppercase tracking-wider">
            Fill Options
          </div>
          <button
            className="w-full px-3 py-1.5 text-left text-xs hover:bg-[var(--bg-hover)] flex items-center gap-2"
            onClick={() => handleModeSelect('copy')}
          >
            <span className="w-4 h-4 rounded bg-gray-200 flex items-center justify-center text-[9px] font-mono">
              C
            </span>
            Copy Cells
          </button>
          {pattern === 'linear' && (
            <button
              className="w-full px-3 py-1.5 text-left text-xs hover:bg-[var(--bg-hover)] flex items-center gap-2"
              onClick={() => handleModeSelect('linear')}
            >
              <span className="w-4 h-4 rounded bg-blue-100 flex items-center justify-center text-[9px] font-mono text-blue-600">
                L
              </span>
              Linear Trend
            </button>
          )}
          {pattern === 'growth' && (
            <button
              className="w-full px-3 py-1.5 text-left text-xs hover:bg-[var(--bg-hover)] flex items-center gap-2"
              onClick={() => handleModeSelect('growth')}
            >
              <span className="w-4 h-4 rounded bg-green-100 flex items-center justify-center text-[9px] font-mono fin-positive">
                G
              </span>
              Growth Trend
            </button>
          )}
          <button
            className="w-full px-3 py-1.5 text-left text-xs hover:bg-[var(--bg-hover)] flex items-center gap-2"
            onClick={() => handleModeSelect('series')}
          >
            <span className="w-4 h-4 rounded bg-amber-100 flex items-center justify-center text-[9px] font-mono text-amber-600">
              S
            </span>
            Fill Series
          </button>
        </div>
      )}
    </div>
  )
}

import React from 'react'
import { cn } from '@/utils/cn'
import { formatCurrency, formatPercent, formatNumber } from '@/utils/formatters'
import { Badge } from './Badge'

export interface FinancialTableRow {
  id?: string
  isSubtotal?: boolean
  type?: string
  accountType?: string
  badgeVariant?: string
  [key: string]: unknown
}

export interface FinancialTableColumn {
  key: string
  header: string
  type: 'string' | 'currency' | 'percent' | 'number' | 'badge'
  align?: 'left' | 'right'
  width?: string
  color?: (value: unknown) => string
  render?: (value: unknown, row: FinancialTableRow) => React.ReactNode
}

export interface FinancialTableProps {
  columns: FinancialTableColumn[]
  rows: FinancialTableRow[]
  showSubtotals?: boolean
  showVariance?: boolean
  className?: string
  /** Maximum rows before switching to virtualized rendering (default: 500) */
  virtualizeThreshold?: number
}

function getCellValue(value: unknown, type: FinancialTableColumn['type']): string | number {
  if (value === null || value === undefined) return '---'
  if (typeof value !== 'number' && ['currency', 'percent', 'number'].includes(type))
    return value as string | number

  switch (type) {
    case 'currency':
      return formatCurrency(value as number)
    case 'percent':
      return formatPercent(value as number)
    case 'number':
      return formatNumber(value as number)
    default:
      return String(value)
  }
}

function getVarianceClass(
  value: unknown,
  type: string,
  row: Record<string, unknown>,
  showVariance: boolean
): string {
  if (!showVariance || typeof value !== 'number') return ''

  const isPositive = value >= 0
  const isRevenue = row.accountType === 'Revenue'

  if (type === 'percent' || type === 'currency') {
    if (isRevenue) {
      return isPositive ? 'fin-positive' : 'fin-negative'
    } else {
      return isPositive ? 'fin-negative' : 'fin-positive'
    }
  }

  return 'fin-neutral'
}

const FinancialTableRowComponent = React.memo(function FinancialTableRowComponent({
  row,
  columns,
  showSubtotals,
  showVariance,
}: {
  row: FinancialTableRow
  columns: FinancialTableColumn[]
  showSubtotals: boolean
  showVariance: boolean
}) {
  const isSubtotal = showSubtotals && (row.isSubtotal || row.type === 'subtotal')

  return (
    <tr
      className={cn(
        'transition-colors hover:bg-[var(--bg-muted)]/50',
        isSubtotal && 'bg-[var(--bg-muted)]/30 font-bold border-t-2'
      )}
    >
      {columns.map((col) => {
        const value = row[col.key]
        const alignment =
          col.align || (['currency', 'percent', 'number'].includes(col.type) ? 'right' : 'left')

        return (
          <td
            key={col.key}
            className={cn(
              'px-4 py-3 whitespace-nowrap',
              alignment === 'right' && 'text-right',
              getVarianceClass(value, col.type, row, showVariance),
              col.color?.(value)
            )}
          >
            {col.render ? (
              col.render(value, row)
            ) : col.type === 'badge' ? (
              <Badge
                variant={
                  (row.badgeVariant || 'default') as
                    | 'default'
                    | 'secondary'
                    | 'destructive'
                    | 'outline'
                }
              >
                {String(value ?? '')}
              </Badge>
            ) : (
              getCellValue(value, col.type)
            )}
          </td>
        )
      })}
    </tr>
  )
})

export const FinancialTable = React.memo(function FinancialTable({
  columns,
  rows,
  showSubtotals = true,
  showVariance = true,
  className,
  virtualizeThreshold = 500,
}: FinancialTableProps) {
  const needsVirtualization = rows.length > virtualizeThreshold

  // For very large datasets, render only visible rows using a simple windowed approach
  const [scrollTop, setScrollTop] = React.useState(0)
  const containerRef = React.useRef<HTMLDivElement>(null)
  const ROW_HEIGHT = 40 // px per row
  const BUFFER = 10 // extra rows above/below viewport

  const visibleRange = React.useMemo(() => {
    if (!needsVirtualization) return { start: 0, end: rows.length }
    const containerHeight = containerRef.current?.clientHeight ?? 600
    const start = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - BUFFER)
    const visibleCount = Math.ceil(containerHeight / ROW_HEIGHT) + BUFFER * 2
    return { start, end: Math.min(rows.length, start + visibleCount) }
  }, [needsVirtualization, scrollTop, rows.length])

  const handleScroll = React.useCallback((e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop)
  }, [])

  const visibleRows = rows.slice(visibleRange.start, visibleRange.end)
  const totalHeight = rows.length * ROW_HEIGHT
  const offsetY = visibleRange.start * ROW_HEIGHT

  return (
    <div
      ref={containerRef}
      className={cn(
        'w-full overflow-x-auto rounded-lg border border-[var(--border-subtle)] shadow-sm bg-[var(--bg-surface)]',
        needsVirtualization && 'overflow-y-auto',
        className
      )}
      style={needsVirtualization ? { maxHeight: '70vh' } : undefined}
      onScroll={needsVirtualization ? handleScroll : undefined}
    >
      <table className="w-full border-collapse text-sm text-left table tabular-nums">
        <thead className="sticky top-0 z-10 bg-[var(--bg-muted)] backdrop-blur-sm border-b border-[var(--border-subtle)]">
          <tr>
            {columns.map((col) => (
              <th
                key={col.key}
                style={{ width: col.width }}
                className={cn(
                  'px-4 py-3 font-bold uppercase tracking-wider text-xs text-[var(--text-secondary)]',
                  (col.align === 'right' || ['currency', 'percent', 'number'].includes(col.type)) &&
                    'text-right'
                )}
              >
                {col.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="divide-y divide-[var(--border-subtle)]">
          {needsVirtualization && (
            <tr style={{ height: offsetY }}>
              <td colSpan={columns.length} />
            </tr>
          )}
          {(needsVirtualization ? visibleRows : rows).map((row, idx) => {
            const rowIdx = needsVirtualization ? visibleRange.start + idx : idx
            return (
              <FinancialTableRowComponent
                key={row.id || rowIdx}
                row={row}
                columns={columns}
                showSubtotals={showSubtotals}
                showVariance={showVariance}
              />
            )
          })}
          {needsVirtualization && (
            <tr
              style={{
                height: Math.max(0, totalHeight - offsetY - visibleRows.length * ROW_HEIGHT),
              }}
              aria-hidden="true"
            >
              <td colSpan={columns.length} />
            </tr>
          )}
        </tbody>
      </table>
      {rows.length === 0 && (
        <div className="py-12 text-center text-[var(--text-secondary)]">
          <p>No data available.</p>
        </div>
      )}
      {needsVirtualization && (
        <div
          className="px-3 py-1 text-xs text-[var(--text-secondary)] bg-[var(--bg-muted)] border-t border-[var(--border-subtle)]"
          role="status"
        >
          Showing {visibleRange.start + 1}-{visibleRange.end} of {rows.length.toLocaleString()} rows
        </div>
      )}
    </div>
  )
})

import React, { useState, useRef, useCallback, useMemo, useEffect } from 'react'
import { Check, X, FlaskConical } from 'lucide-react'
import { cn } from '@/utils/cn'
import { FUNCTIONS } from './formulaFunctions'
import type { FormulaFunction } from './formulaFunctions'
import { FormulaAutocomplete } from './FormulaAutocomplete'

export interface FormulaBarProps {
  value?: string
  onChange?: (value: string) => void
  onEvaluate?: (result: number) => void
  activeCell?: string
  disabled?: boolean
  className?: string
}

export function FormulaBar({
  value = '',
  onChange,
  onEvaluate,
  activeCell,
  disabled = false,
  className,
}: FormulaBarProps) {
  const [showAutocomplete, setShowAutocomplete] = useState(false)
  const [autocompleteIndex, setAutocompleteIndex] = useState(0)
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const listRef = useRef<HTMLDivElement>(null)

  const currentToken = useMemo(() => {
    if (!value.startsWith('=')) return ''
    const afterEquals = value.slice(1)
    const match = afterEquals.match(/([A-Z_]+)$/i)
    return match ? match[1].toUpperCase() : ''
  }, [value])

  const filteredFunctions = useMemo(() => {
    if (!currentToken) return []
    return FUNCTIONS.filter(
      (fn) =>
        fn.name.startsWith(currentToken) && (!selectedCategory || fn.category === selectedCategory)
    ).slice(0, 10)
  }, [currentToken, selectedCategory])

  useEffect(() => {
    setShowAutocomplete(currentToken.length >= 2 && filteredFunctions.length > 0)
    setAutocompleteIndex(0)
  }, [currentToken, filteredFunctions.length])

  useEffect(() => {
    if (listRef.current) {
      const selected = listRef.current.children[autocompleteIndex] as HTMLElement
      selected?.scrollIntoView({ block: 'nearest' })
    }
  }, [autocompleteIndex])

  const insertFunction = useCallback(
    (fn: FormulaFunction) => {
      const beforeToken = value.slice(0, value.length - currentToken.length)
      onChange?.(`${beforeToken}${fn.name}(`)
      setShowAutocomplete(false)
      inputRef.current?.focus()
    },
    [value, currentToken, onChange]
  )

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (showAutocomplete) {
        if (e.key === 'ArrowDown') {
          e.preventDefault()
          setAutocompleteIndex((prev) => Math.min(prev + 1, filteredFunctions.length - 1))
        } else if (e.key === 'ArrowUp') {
          e.preventDefault()
          setAutocompleteIndex((prev) => Math.max(prev - 1, 0))
        } else if (e.key === 'Tab' || e.key === 'Enter') {
          if (filteredFunctions[autocompleteIndex]) {
            e.preventDefault()
            insertFunction(filteredFunctions[autocompleteIndex])
          }
        } else if (e.key === 'Escape') {
          setShowAutocomplete(false)
        }
        return
      }

      if (e.key === 'Enter') {
        onEvaluate?.(0)
      } else if (e.key === 'Escape') {
        onChange?.('')
      }
    },
    [showAutocomplete, filteredFunctions, autocompleteIndex, insertFunction, onEvaluate, onChange]
  )

  const categories = useMemo(() => {
    const cats = new Set(FUNCTIONS.map((fn) => fn.category))
    return ['All', ...Array.from(cats)]
  }, [])

  return (
    <div className={cn('relative', className)}>
      <div
        className={cn(
          'flex items-center w-full border border-[var(--border-subtle)] bg-[var(--bg-surface)] rounded-t-lg overflow-hidden shadow-sm h-10',
          disabled && 'opacity-50 pointer-events-none'
        )}
      >
        <div
          className="flex items-center justify-center px-4 border-r border-[var(--border-subtle)] bg-gray-50 dark:bg-gray-900 min-w-[80px]"
          aria-live="polite"
          aria-label={`Active cell: ${activeCell || 'none'}`}
        >
          <span className="text-xs font-bold text-blue-600 uppercase tabular-nums">
            {activeCell || '---'}
          </span>
        </div>

        <div className="flex items-center justify-center px-3 text-[var(--text-secondary)] italic font-serif select-none border-r border-gray-100 dark:border-gray-800">
          <span className="text-sm font-bold opacity-60">fx</span>
        </div>

        <div className="flex-1 relative group">
          <input
            ref={inputRef}
            type="text"
            className="w-full h-full bg-transparent px-3 py-2 text-sm font-mono text-[var(--text-primary)] outline-none placeholder:italic placeholder:opacity-40"
            placeholder="Enter formula (e.g., =SUM(C2:C10) * 1.05)"
            aria-label="Formula input"
            role="combobox"
            aria-expanded={showAutocomplete}
            aria-controls="formula-autocomplete"
            aria-activedescendant={
              showAutocomplete && filteredFunctions[autocompleteIndex]
                ? `fn-${filteredFunctions[autocompleteIndex].name}`
                : undefined
            }
            value={value}
            onChange={(e) => onChange?.(e.target.value)}
            onKeyDown={handleKeyDown}
            onFocus={() => {
              if (currentToken.length >= 2 && filteredFunctions.length > 0) {
                setShowAutocomplete(true)
              }
            }}
            disabled={disabled}
          />
          {!value && (
            <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center space-x-1.5 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
              <FlaskConical className="h-3.5 w-3.5 text-amber-500" />
              <span className="text-[10px] font-medium text-amber-600">Pure Calculation</span>
            </div>
          )}
        </div>

        <div className="flex items-center px-1 border-l border-[var(--border-subtle)] bg-gray-50 dark:bg-gray-900/50">
          <button
            onClick={() => onChange?.('')}
            className="p-1.5 rounded-md hover:bg-red-50 text-red-400 hover:fin-negative transition-colors"
            title="Cancel (Esc)"
          >
            <X className="h-4 w-4" />
          </button>
          <button
            onClick={() => onEvaluate?.(0)}
            className="p-1.5 rounded-md hover:bg-green-50 text-green-400 hover:fin-positive transition-colors"
            title="Evaluate (Enter)"
          >
            <Check className="h-4 w-4" />
          </button>
        </div>
      </div>

      {showAutocomplete && (
        <FormulaAutocomplete
          filteredFunctions={filteredFunctions}
          autocompleteIndex={autocompleteIndex}
          categories={categories}
          selectedCategory={selectedCategory}
          listRef={listRef}
          onSelectCategory={setSelectedCategory}
          onSelectFunction={insertFunction}
          onHoverIndex={setAutocompleteIndex}
        />
      )}
    </div>
  )
}

import { useCallback, useMemo, useState } from 'react'
import { Card, CardHeader, CardTitle, CardContent } from './Card'
import { Button } from './Button'
import { Badge } from './Badge'
import { Select } from './Select'
import { Input } from './Input'
import { DataTable } from './DataTable'
import { cn } from '@/utils/cn'
import {
  ICMatchingEngine,
  type ICTransaction,
  type MatchPair,
  type MatchSummary,
  type ToleranceSettings,
} from '@/engines/ICMatchingEngine'

// =============================================================================
// IC MATCHING DASHBOARD
// =============================================================================

interface ICMatchingDashboardProps {
  sourceTransactions: ICTransaction[]
  targetTransactions: ICTransaction[]
  allTransactions: ICTransaction[]
  entityNames: Record<string, string>
  onMatch?: (match: MatchPair) => void
  onUnmatch?: (matchId: string) => void
  onAutoMatch?: (matches: MatchPair[]) => void
  onGenerateEliminations?: (matches: MatchPair[]) => void
  className?: string
}

export function ICMatchingDashboard({
  sourceTransactions,
  targetTransactions,
  allTransactions,
  entityNames,
  onMatch,
  onUnmatch,
  onAutoMatch,
  onGenerateEliminations,
  className,
}: ICMatchingDashboardProps) {
  const [engine] = useState(() => new ICMatchingEngine())
  const [matches, setMatches] = useState<MatchPair[]>([])
  const [tolerance, setTolerance] = useState<ToleranceSettings>(engine.getTolerance())
  const [filterEntity, setFilterEntity] = useState<string>('all')
  const [filterAccount, setFilterAccount] = useState<string>('all')
  const [filterStatus, setFilterStatus] = useState<string>('all')
  const [isMatching, setIsMatching] = useState(false)
  const [selectedSource, setSelectedSource] = useState<ICTransaction | null>(null)
  const [selectedTarget, setSelectedTarget] = useState<ICTransaction | null>(null)

  // Unique entities and accounts for filters
  const entities = useMemo(() => {
    const set = new Set(allTransactions.map((t) => t.entityId))
    return Array.from(set)
  }, [allTransactions])

  const accounts = useMemo(() => {
    const set = new Set(allTransactions.map((t) => t.accountCode))
    return Array.from(set).sort()
  }, [allTransactions])

  // Summary stats
  const summary = useMemo<MatchSummary>(
    () => engine.getSummary(sourceTransactions, targetTransactions),
    [engine, sourceTransactions, targetTransactions, matches]
  )

  // Unmatched transactions
  const unmatched = useMemo(
    () => engine.getUnmatched(allTransactions),
    [engine, allTransactions, matches]
  )

  // Filtered matches
  const filteredMatches = useMemo(() => {
    let filtered = matches
    if (filterEntity !== 'all') {
      filtered = filtered.filter(
        (m) => m.source.entityId === filterEntity || m.target.entityId === filterEntity
      )
    }
    if (filterAccount !== 'all') {
      filtered = filtered.filter((m) => m.source.accountCode === filterAccount)
    }
    if (filterStatus !== 'all') {
      filtered = filtered.filter((m) => m.status === filterStatus)
    }
    return filtered
  }, [matches, filterEntity, filterAccount, filterStatus])

  // Auto-match handler
  const handleAutoMatch = useCallback(() => {
    setIsMatching(true)
    engine.setTolerance(tolerance)
    const newMatches = engine.autoMatch(sourceTransactions, targetTransactions)
    setMatches([...newMatches])
    onAutoMatch?.(newMatches)
    setIsMatching(false)
  }, [engine, sourceTransactions, targetTransactions, tolerance, onAutoMatch])

  // Manual match handler
  const handleManualMatch = useCallback(() => {
    if (!selectedSource || !selectedTarget) return
    const match = engine.manualMatch(selectedSource, selectedTarget)
    setMatches([...engine.getMatches()])
    onMatch?.(match)
    setSelectedSource(null)
    setSelectedTarget(null)
  }, [engine, selectedSource, selectedTarget, onMatch])

  // Unmatch handler
  const handleUnmatch = useCallback(
    (matchId: string) => {
      engine.unmatch(matchId)
      setMatches([...engine.getMatches()])
      onUnmatch?.(matchId)
    },
    [engine, onUnmatch]
  )

  // Generate eliminations
  const handleGenerateEliminations = useCallback(() => {
    const accountNames: Record<string, string> = {}
    for (const t of allTransactions) {
      accountNames[t.accountCode] = t.accountName
    }
    const eliminations = engine.generateEliminations(matches, accountNames)
    onGenerateEliminations?.(matches)
  }, [engine, matches, allTransactions, onGenerateEliminations])

  return (
    <div className={cn('space-y-6', className)}>
      {/* Summary Cards */}
      <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
        <SummaryCard
          label="Matched"
          count={summary.matchedCount}
          amount={summary.matchedAmount}
          variant="success"
        />
        <SummaryCard
          label="Partial"
          count={summary.partiallyMatchedCount}
          amount={summary.partiallyMatchedAmount}
          variant="warning"
        />
        <SummaryCard
          label="Unmatched"
          count={summary.unmatchedCount}
          amount={summary.unmatchedAmount}
          variant="error"
        />
        <SummaryCard
          label="Match Rate"
          count={null}
          amount={null}
          value={`${summary.matchRate.toFixed(1)}%`}
          variant="info"
        />
      </div>

      {/* Controls */}
      <Card>
        <CardHeader>
          <CardTitle>Matching Controls</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap items-end gap-4">
            {/* Tolerance Settings */}
            <div className="space-y-1">
              <label className="text-sm font-medium">Amount Tolerance</label>
              <Input
                type="number"
                value={tolerance.amountTolerance}
                onChange={(e) =>
                  setTolerance({ ...tolerance, amountTolerance: Number(e.target.value) })
                }
                className="w-32"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium">% Tolerance</label>
              <Input
                type="number"
                value={tolerance.percentageTolerance}
                onChange={(e) =>
                  setTolerance({ ...tolerance, percentageTolerance: Number(e.target.value) })
                }
                className="w-24"
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-medium">Date Tolerance (days)</label>
              <Input
                type="number"
                value={tolerance.dateToleranceDays}
                onChange={(e) =>
                  setTolerance({ ...tolerance, dateToleranceDays: Number(e.target.value) })
                }
                className="w-24"
              />
            </div>

            <Button onClick={handleAutoMatch} disabled={isMatching}>
              {isMatching ? 'Matching...' : 'Auto-Match'}
            </Button>
            <Button
              variant="outline"
              onClick={handleManualMatch}
              disabled={!selectedSource || !selectedTarget}
            >
              Manual Match
            </Button>
            <Button variant="outline" onClick={handleGenerateEliminations}>
              Generate Eliminations
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Filters */}
      <div className="flex flex-wrap gap-4">
        <Select
          value={filterEntity}
          onChange={setFilterEntity}
          options={[
            { value: 'all', label: 'All Entities' },
            ...entities.map((id) => ({ value: id, label: entityNames[id] ?? id })),
          ]}
        />
        <Select
          value={filterAccount}
          onChange={setFilterAccount}
          options={[
            { value: 'all', label: 'All Accounts' },
            ...accounts.map((code) => ({ value: code, label: code })),
          ]}
        />
        <Select
          value={filterStatus}
          onChange={setFilterStatus}
          options={[
            { value: 'all', label: 'All Statuses' },
            { value: 'matched', label: 'Matched' },
            { value: 'partial', label: 'Partial' },
            { value: 'unmatched', label: 'Unmatched' },
          ]}
        />
      </div>

      {/* Matched Pairs Table */}
      <Card>
        <CardHeader>
          <CardTitle>Matched Pairs ({filteredMatches.length})</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b text-left">
                  <th className="p-2">Status</th>
                  <th className="p-2">Source Entity</th>
                  <th className="p-2">Target Entity</th>
                  <th className="p-2">Account</th>
                  <th className="p-2 text-right">Source Amt</th>
                  <th className="p-2 text-right">Target Amt</th>
                  <th className="p-2 text-right">Difference</th>
                  <th className="p-2 text-right">Confidence</th>
                  <th className="p-2">Method</th>
                  <th className="p-2">Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredMatches.map((match) => (
                  <tr
                    key={match.id}
                    className={cn(
                      'border-b hover:bg-muted/50',
                      match.status === 'matched' && 'bg-green-50 dark:bg-green-950/20',
                      match.status === 'partial' && 'bg-yellow-50 dark:bg-yellow-950/20'
                    )}
                  >
                    <td className="p-2">
                      <MatchStatusBadge status={match.status} />
                    </td>
                    <td className="p-2">{match.source.entityName}</td>
                    <td className="p-2">{match.target.entityName}</td>
                    <td className="p-2 font-mono text-xs">{match.source.accountCode}</td>
                    <td className="p-2 text-right font-mono">
                      {formatAmount(match.source.amount)}
                    </td>
                    <td className="p-2 text-right font-mono">
                      {formatAmount(match.target.amount)}
                    </td>
                    <td className="p-2 text-right font-mono">
                      {formatAmount(match.amountDifference)}
                    </td>
                    <td className="p-2 text-right">{(match.confidence * 100).toFixed(0)}%</td>
                    <td className="p-2 text-xs capitalize">{match.method.replace('_', ' ')}</td>
                    <td className="p-2">
                      <Button variant="ghost" size="sm" onClick={() => handleUnmatch(match.id)}>
                        Unmatch
                      </Button>
                    </td>
                  </tr>
                ))}
                {filteredMatches.length === 0 && (
                  <tr>
                    <td colSpan={10} className="p-8 text-center text-muted-foreground">
                      No matches found. Run Auto-Match or select transactions for Manual Match.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* Unmatched Transactions */}
      <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
        <UnmatchedPanel
          title="Source Transactions"
          transactions={sourceTransactions}
          unmatched={unmatched.filter((t) => sourceTransactions.some((s) => s.id === t.id))}
          selected={selectedSource}
          onSelect={setSelectedSource}
          entityNames={entityNames}
        />
        <UnmatchedPanel
          title="Target Transactions"
          transactions={targetTransactions}
          unmatched={unmatched.filter((t) => targetTransactions.some((s) => s.id === t.id))}
          selected={selectedTarget}
          onSelect={setSelectedTarget}
          entityNames={entityNames}
        />
      </div>
    </div>
  )
}

// =============================================================================
// SUB-COMPONENTS
// =============================================================================

function SummaryCard({
  label,
  count,
  amount,
  value,
  variant,
}: {
  label: string
  count: number | null
  amount: number | null
  value?: string
  variant: 'success' | 'warning' | 'error' | 'info'
}) {
  const colors = {
    success: 'border-green-200 bg-green-50 dark:border-green-800 dark:bg-green-950/30',
    warning: 'border-yellow-200 bg-yellow-50 dark:border-yellow-800 dark:bg-yellow-950/30',
    error: 'border-red-200 bg-red-50 dark:border-red-800 dark:bg-red-950/30',
    info: 'border-blue-200 bg-blue-50 dark:border-blue-800 dark:bg-blue-950/30',
  }

  return (
    <Card className={colors[variant]}>
      <CardContent className="p-4">
        <p className="text-sm text-muted-foreground">{label}</p>
        <p className="text-2xl font-bold">{value ?? count ?? 0}</p>
        {amount !== null && <p className="text-sm text-muted-foreground">{formatAmount(amount)}</p>}
      </CardContent>
    </Card>
  )
}

function MatchStatusBadge({ status }: { status: string }) {
  const variants: Record<string, 'default' | 'secondary' | 'destructive' | 'outline'> = {
    matched: 'default',
    partial: 'secondary',
    unmatched: 'destructive',
  }
  return <Badge variant={variants[status] ?? 'outline'}>{status}</Badge>
}

function UnmatchedPanel({
  title,
  transactions,
  unmatched,
  selected,
  onSelect,
  entityNames,
}: {
  title: string
  transactions: ICTransaction[]
  unmatched: ICTransaction[]
  selected: ICTransaction | null
  onSelect: (t: ICTransaction | null) => void
  entityNames: Record<string, string>
}) {
  return (
    <Card>
      <CardHeader>
        <CardTitle>
          {title} — {unmatched.length} unmatched / {transactions.length} total
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="max-h-64 overflow-y-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b text-left">
                <th className="p-2">Entity</th>
                <th className="p-2">Account</th>
                <th className="p-2 text-right">Amount</th>
                <th className="p-2">Date</th>
              </tr>
            </thead>
            <tbody>
              {unmatched.map((t) => (
                <tr
                  key={t.id}
                  className={cn(
                    'cursor-pointer border-b hover:bg-muted/50',
                    selected?.id === t.id && 'bg-blue-50 dark:bg-blue-950/20'
                  )}
                  onClick={() => onSelect(selected?.id === t.id ? null : t)}
                  onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') onSelect(selected?.id === t.id ? null : t) }}
                >
                  <td className="p-2">{entityNames[t.entityId] ?? t.entityId}</td>
                  <td className="p-2 font-mono text-xs">{t.accountCode}</td>
                  <td className="p-2 text-right font-mono">{formatAmount(t.amount)}</td>
                  <td className="p-2 text-xs">{t.date}</td>
                </tr>
              ))}
              {unmatched.length === 0 && (
                <tr>
                  <td colSpan={4} className="p-4 text-center text-muted-foreground">
                    All transactions matched
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </CardContent>
    </Card>
  )
}

// =============================================================================
// HELPERS
