// ─── Main overlay ────────────────────────────────────────────────────

interface KeyboardOverlayProps {
  isOpen: boolean
  onClose: () => void
}

export function KeyboardOverlay({ isOpen, onClose }: KeyboardOverlayProps) {
  const [search, setSearch] = useState('')
  const [showCustom, setShowCustom] = useState(false)
  const [groups, setGroups] = useState<ShortcutGroup[]>([])

  // Load shortcuts on mount and subscribe to changes
  useEffect(() => {
    ExcelKeyboardShortcuts.loadCustom()
    setGroups(ExcelKeyboardShortcuts.getGrouped())
    const unsub = ExcelKeyboardShortcuts.subscribe(() =>
      setGroups(ExcelKeyboardShortcuts.getGrouped())
    )
    return unsub
  }, [])

  // Reset search when overlay opens — render-phase derivation, no effect needed
  const [prevIsOpen, setPrevIsOpen] = useState(isOpen)
  if (isOpen && !prevIsOpen) {
    setPrevIsOpen(isOpen)
    setSearch('')
  } else if (!isOpen && prevIsOpen) {
    setPrevIsOpen(isOpen)
  }

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen && !showCustom) onClose()
    }
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [isOpen, onClose, showCustom])

  if (!isOpen) return null

  const allShortcuts = groups.flatMap((g) => g.shortcuts)
  const filtered = search ? ExcelKeyboardShortcuts.search(search) : allShortcuts
  const filteredGroups = SHORTCUT_CATEGORIES.map((cat) => ({
    category: cat,
    shortcuts: filtered.filter((s) => s.category === cat),
  })).filter((g) => g.shortcuts.length > 0)

  const handleAdd = (def: Omit<ShortcutDef, 'id' | 'isCustom'>) => {
    ExcelKeyboardShortcuts.register(def)
    ExcelKeyboardShortcuts.saveCustom()
    setShowCustom(false)
  }

  const handleRemove = (id: string) => {
    if (!window.confirm('Remove this custom shortcut?')) return
    ExcelKeyboardShortcuts.removeCustom(id)
    ExcelKeyboardShortcuts.saveCustom()
  }

  const customCount = allShortcuts.filter((s) => s.isCustom).length

  return (
    <>
      <div
        className="fixed inset-0 z-50 flex items-center justify-center"
        style={{ background: 'rgba(0,0,0,0.5)' }}
        onClick={onClose}
        onKeyDown={(e) => { if (e.key === 'Escape') onClose() }}
        role="button"
        tabIndex={-1}
        aria-label="Close keyboard shortcuts"
      >
        <div
          className="w-full max-w-3xl max-h-[85vh] rounded-xl shadow-2xl border overflow-hidden flex flex-col"
          style={{ background: 'var(--bg-primary)', borderColor: 'var(--border)' }}
          onClick={(e) => e.stopPropagation()}
          role="presentation"
        >
          {/* Header */}
          <div
            className="flex items-center justify-between px-6 py-4 border-b"
            style={{ borderColor: 'var(--border)' }}
          >
            <div className="flex items-center gap-2">
              <Keyboard className="w-5 h-5" style={{ color: 'var(--accent)' }} />
              <h2 className="text-lg font-semibold" style={{ color: 'var(--text-primary)' }}>
                Keyboard Shortcuts
              </h2>
              <span
                className="text-xs px-2 py-0.5 rounded-full"
                style={{ background: 'var(--bg-secondary)', color: 'var(--text-secondary)' }}
              >
                {allShortcuts.length} shortcuts
              </span>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => setShowCustom(true)}
                className="flex items-center gap-1 px-3 py-1.5 text-xs rounded-lg border hover:opacity-80"
                style={{ borderColor: 'var(--border)', color: 'var(--text-primary)' }}
                title="Add custom shortcut"
              >
                <Plus className="w-3.5 h-3.5" />
                Custom
              </button>
              <button
                onClick={onClose}
                className="p-1 rounded hover:opacity-80"
                style={{ color: 'var(--text-secondary)' }}
              >
                <X className="w-5 h-5" />
              </button>
            </div>
          </div>

          {/* Search */}
          <div className="px-6 py-3 border-b" style={{ borderColor: 'var(--border)' }}>
            <div className="relative">
              <Search
                className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4"
                style={{ color: 'var(--text-secondary)' }}
              />
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search shortcuts by description, key, or action..."
                className="w-full pl-9 pr-3 py-2 text-sm rounded-lg border outline-none"
                style={{
                  background: 'var(--bg-secondary)',
                  borderColor: 'var(--border)',
                  color: 'var(--text-primary)',
                }}
                // eslint-disable-next-line jsx-a11y/no-autofocus -- intentional: modal search field
                autoFocus
              />
            </div>
          </div>

          {/* Shortcuts grid */}
          <div className="flex-1 overflow-y-auto px-6 py-4">
            {filteredGroups.map((group) => (
              <div key={group.category} className="mb-6 last:mb-0">
                <h3
                  className="text-xs font-semibold uppercase tracking-wider mb-3 flex items-center gap-2"
                  style={{ color: 'var(--text-secondary)' }}
                >
                  {group.category}
                  <span className="font-normal opacity-60">({group.shortcuts.length})</span>
                </h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-1">
                  {group.shortcuts.map((shortcut) => (
                    <div
                      key={shortcut.id}
                      className="flex items-center justify-between py-1.5 group"
                    >
                      <span
                        className="text-sm flex items-center gap-2"
                        style={{ color: 'var(--text-primary)' }}
                      >
                        {shortcut.description}
                        {shortcut.isCustom && (
                          <span
                            className="text-[10px] px-1.5 py-0.5 rounded"
                            style={{ background: 'var(--accent)', color: '#fff', opacity: 0.8 }}
                          >
                            custom
                          </span>
                        )}
                      </span>
                      <div className="flex items-center gap-1">
                        <KeyCombo shortcut={shortcut} />
                        {shortcut.isCustom && (
                          <button
                            onClick={() => handleRemove(shortcut.id)}
                            className="ml-1 p-0.5 rounded opacity-0 group-hover:opacity-100 hover:bg-red-500/10 transition-opacity"
                            title="Remove custom shortcut"
                          >
                            <Trash2 className="w-3.5 h-3.5 text-red-500" />
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}

            {filtered.length === 0 && (
              <div className="text-center py-8" style={{ color: 'var(--text-secondary)' }}>
                No shortcuts found for &quot;{search}&quot;
              </div>
            )}
          </div>

          {/* Footer hint */}
          <div
            className="px-6 py-2 border-t text-xs"
            style={{ borderColor: 'var(--border)', color: 'var(--text-secondary)' }}
          >
            Press <KeyBadge keyName="?" /> or <KeyBadge keyName="Ctrl" /> + <KeyBadge keyName="/" />{' '}
            to toggle this overlay
            {customCount > 0 && (
              <span className="ml-3">
                ({customCount} custom shortcut{customCount !== 1 ? 's' : ''})
              </span>
            )}
          </div>
        </div>
      </div>

      {/* Add custom shortcut dialog */}
      {showCustom && <AddShortcutDialog onAdd={handleAdd} onClose={() => setShowCustom(false)} />}
    </>
  )
}

import { useState, useEffect, useCallback, useMemo, useRef } from 'react'
import { useLocation } from 'react-router-dom'
import { X, Keyboard, Search, Printer, ChevronDown, ChevronRight } from 'lucide-react'
import { cn } from '@/utils/cn'
import {
  keyboardShortcuts,
  formatShortcut,
  type ShortcutDefinition,
} from '@/config/keyboardShortcuts'
import {
  ExcelKeyboardShortcuts,
  SHORTCUT_CATEGORIES,
  type ShortcutDef,
  type ShortcutCategory,
} from '@/engines/ExcelKeyboardShortcuts'

// ─── Types ───────────────────────────────────────────────────────────

type PageContext = 'grid' | 'dashboard' | 'reports' | 'general'

interface UnifiedShortcut {
  id: string
  keys: string
  description: string
  category: string
  source: 'app' | 'excel'
  contexts: PageContext[]
}

// ─── Context detection ───────────────────────────────────────────────

function getPageContext(pathname: string): PageContext {
  if (
    pathname.includes('/budgets') ||
    pathname.includes('/forecasts') ||
    pathname.includes('/scenarios') ||
    pathname.includes('/data/') ||
    pathname.includes('/gl-') ||
    pathname.includes('/chart-of-accounts')
  ) {
    return 'grid'
  }
  if (pathname === '/' || pathname.includes('/dashboard')) return 'dashboard'
  if (pathname.includes('/reports')) return 'reports'
  return 'general'
}

function getContextLabel(ctx: PageContext): string {
  switch (ctx) {
    case 'grid':
      return 'Spreadsheet / Grid'
    case 'dashboard':
      return 'Dashboard'
    case 'reports':
      return 'Reports'
    case 'general':
      return 'General'
  }
}

// ─── Shortcut merging ────────────────────────────────────────────────

function buildUnifiedShortcuts(): UnifiedShortcut[] {
  const result: UnifiedShortcut[] = []

  // App-level shortcuts
  for (const s of keyboardShortcuts) {
    result.push({
      id: `app-${s.key}-${s.ctrl ? 'c' : ''}${s.shift ? 's' : ''}${s.alt ? 'a' : ''}`,
      keys: formatShortcut(s),
      description: s.description,
      category: s.category === 'General' ? 'Application' : s.category,
      source: 'app',
      contexts: ['general', 'dashboard', 'reports', 'grid'],
    })
  }

  // Excel-level shortcuts
  const excelAll = ExcelKeyboardShortcuts.getAll()
  for (const s of excelAll) {
    const keys = ExcelKeyboardShortcuts.formatKeys(s)
    // Skip duplicates already in app shortcuts
    const isDuplicate = result.some(
      (r) => r.keys === keys && r.description.toLowerCase() === s.description.toLowerCase()
    )
    if (isDuplicate) continue

    const contexts: PageContext[] = ['grid']
    if (s.category === 'Application') contexts.push('general', 'dashboard', 'reports')

    result.push({
      id: `excel-${s.id}`,
      keys,
      description: s.description,
      category: mapExcelCategory(s.category),
      source: 'excel',
      contexts,
    })
  }

  return result
}

function mapExcelCategory(cat: ShortcutCategory): string {
  const map: Record<ShortcutCategory, string> = {
    Navigation: 'Grid Navigation',
    Selection: 'Grid Selection',
    Editing: 'Grid Editing',
    Clipboard: 'Clipboard',
    Formatting: 'Formatting',
    Formulas: 'Formulas',
    Data: 'Data',
    Sheets: 'Sheets',
    Application: 'Application',
  }
  return map[cat] ?? cat
}

// ─── Key badge ───────────────────────────────────────────────────────

function KeyBadge({ children }: { children: string }) {
  return (
    <kbd
      className={cn(
        'inline-flex items-center justify-center min-w-[1.5rem] h-6 px-1.5',
        'text-[11px] font-mono rounded border',
        'bg-gray-100 border-gray-300 text-gray-700',
        'dark:bg-gray-700 dark:border-gray-600 dark:text-gray-200'
      )}
      style={{ boxShadow: '0 1px 0 rgba(0,0,0,0.1)' }}
    >
      {children}
    </kbd>
  )
}

function KeyCombo({ keys }: { keys: string }) {
  const parts = keys.split(' + ')
  return (
    <div className="flex items-center gap-0.5 shrink-0">
      {parts.map((p, i) => (
        <span key={i} className="flex items-center gap-0.5">
          {i > 0 && <span className="text-[10px] text-gray-400 dark:text-gray-500">+</span>}
          <KeyBadge>{p}</KeyBadge>
        </span>
      ))}
    </div>
  )
}

// ─── Category section ────────────────────────────────────────────────

function CategorySection({
  name,
  shortcuts,
  defaultOpen,
}: {
  name: string
  shortcuts: UnifiedShortcut[]
  defaultOpen: boolean
}) {
  const [open, setOpen] = useState(defaultOpen)

