const PRINT_STYLES = `
  @media print {
    body * { visibility: hidden; }
    #shortcut-print-area, #shortcut-print-area * { visibility: visible; }
    #shortcut-print-area {
      position: absolute;
      left: 0;
      top: 0;
      width: 100%;
      padding: 24px;
      background: white;
      color: black;
    }
