export function KeyboardShortcuts({ isOpen, onClose }: KeyboardShortcutsProps) {
  const [filter, setFilter] = useState('')

  useEffect(() => {
    if (isOpen) {
      setFilter('')
    }
  }, [isOpen])

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) {
        onClose()
      }
    }
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [isOpen, onClose])

  if (!isOpen) return null

  const filteredShortcuts = filter
    ? shortcuts.filter(
        (s) =>
          s.description.toLowerCase().includes(filter.toLowerCase()) ||
          s.category.toLowerCase().includes(filter.toLowerCase()) ||
          s.keys.some((k) => k.toLowerCase().includes(filter.toLowerCase()))
      )
    : shortcuts

  const categories = Array.from(new Set(filteredShortcuts.map((s) => s.category)))

  const handleBackdropKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') onClose()
  }

  return (
      <div
        className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm"
        onClick={onClose}
        onKeyDown={handleBackdropKeyDown}
        role="button"
        tabIndex={-1}
        aria-label="Close keyboard shortcuts"
      >
      <div
        className="w-full max-w-2xl max-h-[80vh] rounded-lg shadow-2xl border overflow-hidden flex flex-col bg-[var(--bg-primary)] border-[var(--border)]"
        onClick={(e) => e.stopPropagation()}
        onKeyDown={(e) => e.stopPropagation()}
        role="presentation"
      >
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-[var(--border)]">
          <div className="flex items-center gap-2">
            <Keyboard className="w-5 h-5 text-[var(--accent)]" />
            <h2 className="font-semibold text-[var(--text-primary)]">Keyboard Shortcuts</h2>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded hover:opacity-80 text-[var(--text-secondary)]"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Search */}
        <div className="p-4 border-b border-[var(--border)]">
          <input
            type="text"
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            placeholder="Search shortcuts..."
            className="w-full px-3 py-2 rounded border text-sm bg-transparent outline-none border-[var(--border)] text-[var(--text-primary)]"
            // eslint-disable-next-line jsx-a11y/no-autofocus -- intentional: modal search field
            autoFocus
          />
        </div>

        {/* Shortcuts List */}
        <div className="flex-1 overflow-y-auto p-4">
          {categories.map((category) => (
            <div key={category} className="mb-6">
              <h3 className="text-xs font-semibold uppercase tracking-wider mb-3 text-[var(--text-secondary)]">
                {category}
              </h3>
              <div className="space-y-1">
                {filteredShortcuts
                  .filter((s) => s.category === category)
                  .map((shortcut, i) => (
                    <div
                      key={i}
                      className="flex items-center justify-between py-1.5 px-2 rounded hover:opacity-80"
                    >
                      <span className="text-sm text-[var(--text-primary)]">
                        {shortcut.description}
                      </span>
                      <div className="flex items-center gap-1">
                        {shortcut.keys.map((key, j) => (
                          <React.Fragment key={j}>
                            {j > 0 && (
                              <span className="text-xs text-[var(--text-secondary)]">+</span>
