// AI Engine — Lazy-loaded to avoid bundling ONNX WASM (23.5MB) in initial load
// Only loaded when the /ai page is visited

import { createLogger } from '@/utils/logger'

const log = createLogger('AIEngine')

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- wraps @huggingface/transformers pipeline which is loosely typed
type PipelineFunction = (...args: any[]) => Promise<any>
type ClassifierResult = Array<{ label: string; score: number }>
type ExtractorResult = Array<{ word: string; score: number; start: number; end: number }>
type PipelineInstance = ((text: string) => Promise<ClassifierResult | ExtractorResult>) & {
  dispose?: () => Promise<void>
}

let pipeline: PipelineFunction | null = null
let env: { allowRemoteModels: boolean; useBrowserCache: boolean } | null = null

async function loadTransformers() {
  if (pipeline) return
  const mod = await import('@huggingface/transformers')
  pipeline = mod.pipeline
  env = mod.env
  env.allowRemoteModels = true
  env.useBrowserCache = true
}

export class AIEngine {
  private static classifier: PipelineInstance | null = null
  private static extractor: PipelineInstance | null = null

  static async init(onProgress?: (progress: number) => void) {
    if (this.classifier) return

    await loadTransformers()

    try {
      this.classifier = (await pipeline!(
        'text-classification',
        'Xenova/distilbert-base-uncased-finetuned-sst-2-english',
        {
          device: 'webgpu',
          progress_callback: (info: { status: string; progress: number }) => {
            if (info.status === 'progress' && onProgress) {
              onProgress(info.progress)
            }
          },
        }
      )) as unknown as PipelineInstance
    } catch (e) {
      log.warn('WebGPU not available, falling back to WASM/CPU', { error: String(e) })
      this.classifier = (await pipeline!(
        'text-classification',
        'Xenova/distilbert-base-uncased-finetuned-sst-2-english',
        {
          device: 'wasm',
        }
      )) as unknown as PipelineInstance
    }
  }

  static async classifyTransaction(description: string) {
    if (!this.classifier) await this.init()
    const result = await this.classifier!(description)
    return result[0]
  }

  static async getEmbeddings(text: string) {
    await loadTransformers()
    if (!this.extractor) {
      this.extractor = (await pipeline!(
        'feature-extraction',
        'onnx-community/all-MiniLM-L6-v2-ONNX',
        {
          device: 'webgpu',
        }
      )) as unknown as PipelineInstance
    }
    const output = await this.extractor(text)
    return output
  }

  static async detectAnomalies(descriptions: string[]) {
    const results = []
    for (const desc of descriptions) {
      const sentiment = await this.classifyTransaction(desc)
      results.push({
        description: desc,
        sentiment: 'label' in sentiment ? sentiment.label : sentiment.word,
        confidence: sentiment.score,
      })
    }
    return results
  }
}

// =============================================================================
// SAFEMATHPARSER — Bulletproof recursive descent math expression parser
// NO eval(), NO new Function(), NO dynamic code execution
// =============================================================================

// --- Security Limits ---
const MAX_INPUT_LENGTH = 10_000
const MAX_RECURSION_DEPTH = 1000
const MAX_TOKENS = 10_000
const MAX_FUNCTION_ARGS = 100

// --- Token Types ---
type TokenType =
  | 'number'
  | 'cellRef'
  | 'string'
  | 'plus'
  | 'minus'
  | 'star'
  | 'slash'
  | 'caret'
  | 'percent'
  | 'lparen'
  | 'rparen'
  | 'comma'
  | 'colon'
  | 'lt'
  | 'gt'
  | 'lte'
  | 'gte'
  | 'eq'
  | 'neq'
  | 'and'
  | 'or'
  | 'not'
  | 'func'
  | 'const'
  | 'eof'

interface Token {
  type: TokenType
  value: string
  pos: number
}

// --- Constants Map ---
const CONSTANTS: Record<string, number> = {
  PI: Math.PI,
  E: Math.E,
  TRUE: 1,
  FALSE: 0,
}

// --- Function Registry ---
type FuncImpl = (args: number[]) => number

const FUNCTIONS: Record<string, FuncImpl> = {
  ABS: (args) => Math.abs(args[0]),
  ROUND: (args) => {
    const val = args[0]
    const decimals = args[1] ?? 0
    const factor = Math.pow(10, decimals)
    return Math.round(val * factor) / factor
  },
  MIN: (args) => Math.min(...args),
  MAX: (args) => Math.max(...args),
  SQRT: (args) => (args[0] < 0 ? NaN : Math.sqrt(args[0])),
  POW: (args) => Math.pow(args[0], args[1]),
  LOG: (args) => (args[0] <= 0 ? NaN : Math.log10(args[0])),
  LN: (args) => (args[0] <= 0 ? NaN : Math.log(args[0])),
  EXP: (args) => Math.exp(args[0]),
  CEIL: (args) => Math.ceil(args[0]),
  FLOOR: (args) => Math.floor(args[0]),
  SIGN: (args) => Math.sign(args[0]),
  TRUNC: (args) => Math.trunc(args[0]),
  MOD: (args) => {
    if (args[1] === 0) return NaN
    return args[0] % args[1]
  },
  INT: (args) => Math.floor(args[0]),
  SUM: (args) => args.reduce((a, b) => a + b, 0),
  AVG: (args) => (args.length === 0 ? 0 : args.reduce((a, b) => a + b, 0) / args.length),
  AVERAGE: (args) => (args.length === 0 ? 0 : args.reduce((a, b) => a + b, 0) / args.length),
  COUNT: (args) => args.length,
  IF: (args) => (args[0] !== 0 ? args[1] : args[2]),
  NOT: (args) => (args[0] === 0 ? 1 : 0),
  AND: (args) => (args.every((a) => a !== 0) ? 1 : 0),
  OR: (args) => (args.some((a) => a !== 0) ? 1 : 0),
  // Financial functions
  NPV: (args) => {
    const rate = args[0]
    const cashflows = args.slice(1)
    return cashflows.reduce((acc, cf, i) => acc + cf / Math.pow(1 + rate, i + 1), 0)
  },
  CAGR: (args) => {
    const ev = args[0]
    const bv = args[1]
    const n = args[2]
    if (bv <= 0 || n <= 0) return 0
    return Math.pow(ev / bv, 1 / n) - 1
  },
  IRR: (args) => {
    // Newton-Raphson IRR
    const cashflows = args
    if (cashflows.length < 2) return 0
    let guess = 0.1
    for (let iter = 0; iter < 100; iter++) {
      let npv = 0
      let dnpv = 0
      for (let i = 0; i < cashflows.length; i++) {
        const d = Math.pow(1 + guess, i)
        npv += cashflows[i] / d
        if (i > 0) dnpv -= (i * cashflows[i]) / (d * (1 + guess))
      }
      if (Math.abs(dnpv) < 1e-12) break
      const newGuess = guess - npv / dnpv
      if (Math.abs(newGuess - guess) < 1e-10) return newGuess
      guess = newGuess
    }
    return guess
  },
  PMT: (args) => {
    const rate = args[0]
    const nper = args[1]
    const pv = args[2]
    if (rate === 0) return -pv / nper
    return (-pv * rate * Math.pow(1 + rate, nper)) / (Math.pow(1 + rate, nper) - 1)
  },
  PV: (args) => {
    const rate = args[0]
    const nper = args[1]
    const pmt = args[2]
    const fv = args[3] ?? 0
    if (rate === 0) return -(fv + pmt * nper)
    return -(fv + pmt * ((Math.pow(1 + rate, nper) - 1) / rate)) / Math.pow(1 + rate, nper)
  },
  FV: (args) => {
    const rate = args[0]
    const nper = args[1]
    const pmt = args[2]
    const pv = args[3] ?? 0
    if (rate === 0) return -(pv + pmt * nper)
    return -(pv * Math.pow(1 + rate, nper) + pmt * ((Math.pow(1 + rate, nper) - 1) / rate))
  },

  // =========================================================================
  // MATH & TRIG (50+)
  // =========================================================================
  ACOS: (args) => Math.acos(args[0]),
  ASIN: (args) => Math.asin(args[0]),
  ATAN: (args) => Math.atan(args[0]),
  ATAN2: (args) => Math.atan2(args[0], args[1]),
  COS: (args) => Math.cos(args[0]),
  SIN: (args) => Math.sin(args[0]),
  TAN: (args) => Math.tan(args[0]),
  ACOSH: (args) => Math.acosh(args[0]),
  ASINH: (args) => Math.asinh(args[0]),
  ATANH: (args) => Math.atanh(args[0]),
