  CEILING_PRECISE: (args) => {
    const val = args[0]
    const significance = args[1] ?? 1
    return Math.ceil(val / significance) * significance
  },
  MROUND: (args) => {
    const multiple = args[1]
    if (multiple === 0) return 0
    return Math.round(args[0] / multiple) * multiple
