    const x = args.slice(half)
    if (x.length !== y.length || x.length < 2) return 0
    const n = x.length
    const xAvg = x.reduce((a, b) => a + b, 0) / n
    const yAvg = y.reduce((a, b) => a + b, 0) / n
    let sumXY = 0,
      sumX2 = 0,
      sumY2 = 0
    for (let i = 0; i < n; i++) {
