      const t = 1 / (1 + 0.2316419 * Math.abs(z))
      const d = 0.3989422804014327 * Math.exp((-z * z) / 2)
      const p =
        d * t * (0.3193815 + t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274))))
      return z > 0 ? 1 - p : p
    }
    return Math.exp((-z * z) / 2) / (std * Math.sqrt(2 * Math.PI))
