    const y = args.slice(0, half)
    const x = args.slice(half)
    const n = y.length
    if (n < 3) return 0
    const xAvg = x.reduce((a, b) => a + b, 0) / n
    const yAvg = y.reduce((a, b) => a + b, 0) / n
    let ssRes = 0
    let num = 0,
      den = 0
    for (let i = 0; i < n; i++) {
      num += (x[i] - xAvg) * (y[i] - yAvg)
      den += (x[i] - xAvg) ** 2
    }
    const slope = den === 0 ? 0 : num / den
    const intercept = yAvg - slope * xAvg
    for (let i = 0; i < n; i++) {
