    category: 'financial',
    description: 'Yield of discounted security',
    minArgs: 4,
    maxArgs: 4,
    impl: impl((_settlement: number, _maturity: number, _pr: number, _redemption: number) => {
      const n = (_maturity - _settlement) / 365.25
      return (_redemption - _pr) / _pr / n
    }),
  })
  r({
    name: 'YIELDMAT',
    category: 'financial',
    description: 'Yield at maturity',
    minArgs: 5,
    maxArgs: 5,
    impl: impl(
      (_settlement: number, _maturity: number, _issue: number, _rate: number, _pr: number) => {
        const ds = (_settlement - _issue) / 365.25
        const dm = (_maturity - _settlement) / 365.25
        return (_rate * ds + 1 - _pr / 100) / ((_pr / 100) * dm)
      }
    ),
  })

  // Growth
  r({
    name: 'GROWTH_RATE',
    category: 'growth',
    description: 'Growth rate between two values',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(GROWTH_RATE),
  })
  r({
    name: 'YOY',
    category: 'growth',
    description: 'Year-over-year growth',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(YOY),
  })
  r({
    name: 'MOM',
    category: 'growth',
    description: 'Month-over-month growth',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(MOM),
  })
  r({
    name: 'YTD',
    category: 'growth',
    description: 'Year-to-date sum',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(YTD),
  })
  r({
    name: 'QTD',
    category: 'growth',
    description: 'Quarter-to-date sum',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(QTD),
  })
  r({
    name: 'ROLLING',
    category: 'growth',
    description: 'Rolling average',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(ROLLING),
  })
  r({
    name: 'TREND',
    category: 'growth',
    description: 'Linear trend values',
    minArgs: 1,
    maxArgs: -1,
    impl: impl(TREND),
  })
  r({
    name: 'MOVING_AVERAGE',
    category: 'growth',
    description: 'Moving average',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(MOVING_AVERAGE),
  })
  r({
    name: 'WEIGHTED_AVERAGE',
    category: 'growth',
    description: 'Weighted average',
    minArgs: 2,
    maxArgs: -1,
    impl: impl(WEIGHTED_AVERAGE),
  })
  r({
    name: 'PERCENTILE',
    category: 'growth',
    description: 'Percentile value',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(PERCENTILE),
  })
  r({
    name: 'MTD',
    category: 'growth',
    description: 'Month-to-date sum',
    minArgs: 2,
    maxArgs: 2,
    impl: impl((v: unknown, m: number) => {
      const vals = Array.isArray(v) ? v : [v as number]
      const monthStart = m - (m % 30)
      let s = 0
      for (let i = monthStart; i <= Math.min(m, vals.length - 1); i++) s += vals[i]
      return s
    }),
  })
  r({
    name: 'ITD',
    category: 'growth',
    description: 'Inception-to-date sum',
    minArgs: 2,
    maxArgs: 2,
    impl: impl((v: unknown, m: number) => {
      const vals = Array.isArray(v) ? v : [v as number]
      let s = 0
      for (let i = 0; i <= Math.min(m, vals.length - 1); i++) s += vals[i]
      return s
    }),
  })
  r({
    name: 'PARALLEL_PERIOD',
    category: 'growth',
    description: 'Value from parallel period',
    minArgs: 3,
    maxArgs: 3,
    impl: impl((v: unknown, current: number, offset: number) => {
      const vals = Array.isArray(v) ? v : [v as number]
      const idx = current - offset
      return idx >= 0 && idx < vals.length ? vals[idx] : 0
    }),
  })
  r({
    name: 'SAME_PERIOD_LAST_YEAR',
    category: 'growth',
    description: 'Value from same period last year',
    minArgs: 2,
    maxArgs: 2,
    impl: impl((v: unknown, current: number) => {
      const vals = Array.isArray(v) ? v : [v as number]
      const idx = current - 12
      return idx >= 0 && idx < vals.length ? vals[idx] : 0
    }),
  })
  r({
    name: 'OPENINGBALANCE',
    category: 'growth',
    description: 'Opening balance for period',
    minArgs: 2,
    maxArgs: 2,
    impl: impl((v: unknown, period: number) => {
      const vals = Array.isArray(v) ? v : [v as number]
      return period > 0 && period <= vals.length ? vals[period - 1] : 0
    }),
  })
  r({
    name: 'CLOSINGBALANCE',
    category: 'growth',
    description: 'Closing balance for period',
    minArgs: 2,
    maxArgs: 2,
    impl: impl((v: unknown, period: number) => {
      const vals = Array.isArray(v) ? v : [v as number]
      return period >= 0 && period < vals.length ? vals[period] : 0
    }),
  })
  r({
    name: 'PERIOD_TO_DATE',
    category: 'growth',
    description: 'Sum from period start to given period',
    minArgs: 3,
    maxArgs: 3,
    impl: impl((v: unknown, start: number, end: number) => {
      const vals = Array.isArray(v) ? v : [v as number]
      let s = 0
      for (let i = Math.max(0, start); i <= Math.min(end, vals.length - 1); i++) s += vals[i]
      return s
    }),
  })
  r({
    name: 'LAG',
    category: 'growth',
    description: 'Lagged value',
    minArgs: 2,
    maxArgs: 3,
    impl: impl((v: unknown, current: number, lag = 1) => {
      const vals = Array.isArray(v) ? v : [v as number]
      const idx = current - lag
      return idx >= 0 && idx < vals.length ? vals[idx] : 0
    }),
  })
  r({
    name: 'LEAD',
    category: 'growth',
    description: 'Leading value',
    minArgs: 2,
    maxArgs: 3,
    impl: impl((v: unknown, current: number, lead = 1) => {
      const vals = Array.isArray(v) ? v : [v as number]
      const idx = current + lead
      return idx >= 0 && idx < vals.length ? vals[idx] : 0
    }),
  })
  r({
    name: 'CUMULATIVE',
    category: 'growth',
    description: 'Cumulative sum array',
    minArgs: 1,
    maxArgs: 1,
    impl: impl((v: unknown) => {
      const vals = Array.isArray(v) ? v : [v as number]
      const result: number[] = []
      let s = 0
      for (const x of vals) {
        s += x
        result.push(s)
      }
      return result
    }),
  })
  r({
    name: 'GROWTH_RATE_SERIES',
    category: 'growth',
    description: 'Period-over-period growth rate series',
    minArgs: 1,
    maxArgs: 1,
    impl: impl((v: unknown) => {
      const vals = Array.isArray(v) ? v : [v as number]
      const result: number[] = [0]
      for (let i = 1; i < vals.length; i++)
        result.push(vals[i - 1] === 0 ? 0 : (vals[i] - vals[i - 1]) / Math.abs(vals[i - 1]))
      return result
    }),
  })

  // Allocation
  r({
    name: 'ALLOCATE',
    category: 'allocation',
    description: 'Allocate amount by weights',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(ALLOCATE),
  })
  r({
    name: 'SPREAD',
    category: 'allocation',
    description: 'Spread amount evenly',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(SPREAD),
  })
  r({
    name: 'DISTRIBUTE',
    category: 'allocation',
    description: 'Distribute amount',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(DISTRIBUTE),
  })
  r({
    name: 'SPLIT',
    category: 'allocation',
    description: 'Split amount by ratios',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(SPLIT),
  })
  r({
    name: 'PRO_RATA',
    category: 'allocation',
    description: 'Pro-rata allocation',
    minArgs: 3,
    maxArgs: 3,
    impl: impl(PRO_RATA),
  })

  // Currency
  r({
    name: 'CONVERT_CURRENCY',
    category: 'currency',
    description: 'Convert amount by exchange rate',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(CONVERT_CURRENCY),
  })
  r({
    name: 'TRANSLATE',
    category: 'currency',
    description: 'Translate amount for consolidation',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(TRANSLATE),
  })
  r({
    name: 'ELIMINATE',
    category: 'currency',
    description: 'Eliminate intercompany percentage',
    minArgs: 2,
    maxArgs: 2,
    impl: impl(ELIMINATE),
  })
  r({
    name: 'FX_GAIN_LOSS',
    category: 'currency',
    description: 'Foreign exchange gain or loss',
    minArgs: 3,
    maxArgs: 3,
    impl: impl(FX_GAIN_LOSS),
  })
  r({
    name: 'HYPERINFLATION_ADJUST',
    category: 'currency',
    description: 'Hyperinflation adjustment',
    minArgs: 3,
    maxArgs: 3,
    impl: impl(HYPERINFLATION_ADJUST),
  })
}

// =============================================================================
// FORMULA FUNCTION REGISTRY — Shared Types & Helpers
// =============================================================================

export type FunctionCategory =
  | 'financial'
  | 'growth'
  | 'allocation'
  | 'currency'
  | 'statistical'
  | 'logical'
  | 'lookup'
  | 'math'
  | 'text'
  | 'date'
  | 'information'
  | 'engineering'
  | 'array'
  | 'database'
  | 'cube'

export interface FormulaFunction {
  name: string
  category: FunctionCategory
  description: string
  minArgs: number
  maxArgs: number // -1 = variadic
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- variadic formula args are heterogeneous (numbers, strings, arrays)
  impl: (...args: any[]) => number | number[]
}

// =============================================================================
// NUMERIC HELPERS
// =============================================================================

/** Coerce a value to a number. Strings are parsed; non-numeric values return NaN. */
export const toNum = (v: unknown): number => {
  if (typeof v === 'number') return v
  if (typeof v === 'string') {
    const n = parseFloat(v)
    return isNaN(n) ? NaN : n
  }
  return NaN
}

/** Flatten nested arrays and filter to valid numbers (skip NaN, null, undefined). */
export const flattenNums = (args: unknown[]): number[] => {
  const flat = args.flat(Infinity)
  return flat.map((v) => toNum(v)).filter((n) => !isNaN(n))
}

export const safeNum = (v: number): number => {
  return v // NaN propagates naturally -- callers must handle it
}

// =============================================================================
// MATH HELPERS
// =============================================================================

export const fact = (n: number): number => {
  let r = 1
  for (let i = 2; i <= n; i++) r *= i
  return r
}
export const comb = (n: number, k: number): number =>
  k > n ? 0 : fact(n) / (fact(k) * fact(n - k))
export const perm = (n: number, k: number): number => (k > n ? 0 : fact(n) / fact(n - k))

// =============================================================================
// STATISTICAL DISTRIBUTION HELPERS
// =============================================================================

export const gammln = (x: number): number => {
  const c = [
    76.1800917294714, -86.5053203294167, 24.0140982408309, -1.23173957245015, 0.120865097386617e-2,
    -0.539523938495e-5,
  ]
  let y = x,
    tmp = x + 5.5
  tmp -= (x + 0.5) * Math.log(tmp)
  let ser = 1.000000000190015
  for (let j = 0; j < 6; j++) ser += c[j] / ++y
  return -tmp + Math.log((2.506628274631 * ser) / x)
}

export const betacf = (a: number, b: number, x: number): number => {
  const maxIter = 100,
    eps = 3e-12
  const qab = a + b,
    qap = a + 1,
    qam = a - 1
  let c = 1,
    d = 1 - (qab * x) / qap
  if (Math.abs(d) < 1e-30) d = 1e-30
  d = 1 / d
  let h = d
  for (let m = 1; m <= maxIter; m++) {
    const m2 = 2 * m
    let aa = (m * (b - m) * x) / ((qam + m2) * (a + m2))
    d = 1 + aa * d
    if (Math.abs(d) < 1e-30) d = 1e-30
    c = 1 + aa / c
    if (Math.abs(c) < 1e-30) c = 1e-30
    d = 1 / d
    h *= d * c
    aa = (-(a + m) * (qab + m) * x) / ((a + m2) * (qap + m2))
    d = 1 + aa * d
    if (Math.abs(d) < 1e-30) d = 1e-30
    c = 1 + aa / c
    if (Math.abs(c) < 1e-30) c = 1e-30
    d = 1 / d
    const del = d * c
    h *= del
    if (Math.abs(del - 1) < eps) break
  }
  return h
}

export const betai = (a: number, b: number, x: number): number => {
  if (x < 0 || x > 1) return 0
  if (x === 0 || x === 1) return x
  const bt = Math.exp(gammln(a + b) - gammln(a) - gammln(b) + a * Math.log(x) + b * Math.log(1 - x))
  return x < (a + 1) / (a + b + 2) ? (bt * betacf(a, b, x)) / a : 1 - (bt * betacf(b, a, 1 - x)) / b
}

export const gammDist = (x: number, alpha: number, beta: number): number => {
  if (x <= 0) return 0
  return Math.exp((alpha - 1) * Math.log(x) - x / beta - gammln(alpha) - alpha * Math.log(beta))
}

export const normCDF = (x: number): number => {
  const a1 = 0.254829592,
    a2 = -0.284496736,
    a3 = 1.421413741,
    a4 = -1.453152027,
    a5 = 1.061405429,
    p = 0.3275911
  const sign = x < 0 ? -1 : 1
  x = Math.abs(x) / Math.SQRT2
  const t = 1 / (1 + p * x)
  const y = 1 - ((((a5 * t + a4) * t + a3) * t + a2) * t + a1) * t * Math.exp(-x * x)
  return 0.5 * (1 + sign * y)
}

export const normInv = (p: number): number => {
  if (p <= 0 || p >= 1) return 0
  const a = [
    -3.969683028665376e1, 2.209460984245205e2, -2.759285104469687e2, 1.38357751867269e2,
    -3.066479806614716e1, 2.506628277459239,
  ]
  const b = [
    -5.447609879822406e1, 1.615858368580409e2, -1.556989798598866e2, 6.680131188771972e1,
    -1.328068155288572e1,
  ]
  const c = [
    -7.784894002430293e-3, -3.223964580411365e-1, -2.400758277161838, -2.549732539343734,
    4.374664141464968, 2.938163982698783,
  ]
  const d = [7.784695709041462e-3, 3.224671290700398e-1, 2.445134137142996, 3.754408661907416]
  const pLow = 0.02425,
    pHigh = 1 - pLow
  let q: number, r: number
  if (p < pLow) {
    q = Math.sqrt(-2 * Math.log(p))
    return (
      (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
      ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
    )
  }
  if (p <= pHigh) {
    q = p - 0.5
    r = q * q
    return (
      ((((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q) /
      (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1)
    )
  }
  q = Math.sqrt(-2 * Math.log(1 - p))
  return (
    -(((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
    ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
  )
}

export const tDistCDF = (t: number, df: number): number => {
  const x = df / (df + t * t)
  return 1 - 0.5 * betai(df / 2, 0.5, x)
}

export const tDistInv = (p: number, df: number): number => {
  // Approximation using normInv for large df, bisection for small
  if (df > 30) return normInv(p)
  let lo = -10,
    hi = 10
  for (let i = 0; i < 50; i++) {
    const mid = (lo + hi) / 2
    if (tDistCDF(mid, df) < p) {
      lo = mid
    } else {
      hi = mid
    }
  }
  return (lo + hi) / 2
}

import { useCallback, useEffect, useRef, useState } from 'react'

export interface UseIntersectionObserverOptions {
  /** Margin around the root element (default: '200px' for pre-loading) */
  rootMargin?: string
  /** Visibility threshold to trigger (default: 0) */
  threshold?: number
  /** Whether to stop observing after first intersection (default: true) */
  triggerOnce?: boolean
}

/**
 * Observes when an element enters the viewport using IntersectionObserver.
 * Used for lazy-loading charts and heavy components.
 */
export function useIntersectionObserver({
  rootMargin = '200px',
  threshold = 0,
  triggerOnce = true,
}: UseIntersectionObserverOptions = {}) {
  const [isVisible, setIsVisible] = useState(false)
  const elementRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const element = elementRef.current
    if (!element) return

    // If IntersectionObserver is not supported, show immediately
    if (typeof IntersectionObserver === 'undefined') {
      // eslint-disable-next-line react-compiler
      setIsVisible(true)
      return
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
          if (triggerOnce) {
            observer.unobserve(element)
          }
        } else if (!triggerOnce) {
          setIsVisible(false)
        }
      },
      { rootMargin, threshold }
    )

    observer.observe(element)

    return () => {
      observer.unobserve(element)
    }
  }, [rootMargin, threshold, triggerOnce])

  return { ref: elementRef, isVisible }
}

/**
 * Hook for measuring element dimensions and updating on resize.
 */
export function useElementSize() {
  const ref = useRef<HTMLDivElement>(null)
  const [size, setSize] = useState({ width: 0, height: 0 })

  const updateSize = useCallback(() => {
    if (ref.current) {
      const { width, height } = ref.current.getBoundingClientRect()
      setSize({ width, height })
    }
  }, [])

  useEffect(() => {
    // eslint-disable-next-line react-compiler
    updateSize()

    const element = ref.current
    if (!element || typeof ResizeObserver === 'undefined') return

    const observer = new ResizeObserver(updateSize)
    observer.observe(element)

    return () => {
      observer.unobserve(element)
    }
  }, [updateSize])

  return { ref, ...size }
}

import { useEffect, useRef } from 'react'
import { createLogger } from '@/utils/logger'

export function useRenderCount(componentName: string) {
  const count = useRef(0)
  const log = createLogger(componentName)

  useEffect(() => {
    count.current += 1
    if (process.env.NODE_ENV === 'development') {
      log.debug(`renders: ${count.current}`)
    }
  })

  return count.current
}

// =============================================================================
// Tauri Menu Hook — Listen for native menu events and dispatch actions
// =============================================================================

import { useCallback, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'

type MenuAction = (id: string) => void

export function useTauriMenu(onAction?: MenuAction) {
  const navigate = useNavigate()

  const handleMenuEvent = useCallback(
    (event: { payload: string }) => {
      const id = event.payload

      // Default actions
      switch (id) {
        case 'new_file':
          window.dispatchEvent(new CustomEvent('app:new-file'))
          break
        case 'open_file':
          window.dispatchEvent(new CustomEvent('app:open-file'))
          break
        case 'save_file':
          window.dispatchEvent(new CustomEvent('app:save-file'))
          break
        case 'save_as':
          window.dispatchEvent(new CustomEvent('app:save-as'))
          break
        case 'import_data':
          window.dispatchEvent(new CustomEvent('app:import'))
          break
        case 'export_data':
          window.dispatchEvent(new CustomEvent('app:export'))
          break
        case 'print':
          window.print()
          break
        case 'quit':
          window.dispatchEvent(new CustomEvent('app:quit'))
          break
        case 'undo':
          window.dispatchEvent(new CustomEvent('app:undo'))
          break
        case 'redo':
          window.dispatchEvent(new CustomEvent('app:redo'))
          break
        case 'toggle_sidebar':
          window.dispatchEvent(new CustomEvent('app:toggle-sidebar'))
          break
        case 'toggle_formula_bar':
          window.dispatchEvent(new CustomEvent('app:toggle-formula-bar'))
          break
        case 'toggle_status_bar':
          window.dispatchEvent(new CustomEvent('app:toggle-status-bar'))
          break
        case 'consolidate':
          navigate('/consolidation')
          break
        case 'scenarios':
          navigate('/scenarios')
          break
        case 'reports':
          navigate('/reports')
          break
        case 'validate_data':
          window.dispatchEvent(new CustomEvent('app:validate-data'))
          break
        case 'options':
          navigate('/settings')
          break
        case 'documentation':
          navigate('/help')
          break
        case 'keyboard_shortcuts':
          window.dispatchEvent(new CustomEvent('app:show-shortcuts'))
          break
        case 'about':
          window.dispatchEvent(new CustomEvent('app:show-about'))
          break
        default:
          break
      }

      // Forward to custom handler
      onAction?.(id)
    },
    [navigate, onAction]
  )

  useEffect(() => {
    // Dynamic import to avoid breaking web builds
    let unlisten: (() => void) | undefined

    const setup = async () => {
      try {
        const { listen } = await import('@tauri-apps/api/event')
        unlisten = await listen<string>('menu-event', handleMenuEvent)
      } catch {
        // Not running in Tauri — ignore
      }
    }

    setup()

    return () => {
      unlisten?.()
    }
  }, [handleMenuEvent])
}

// =============================================================================
// Global Shortcuts Hook — System-wide keyboard shortcuts
// =============================================================================

export function useGlobalShortcuts() {
  useEffect(() => {
    let unlisten: (() => void) | undefined

    const setup = async () => {
      try {
        // @ts-ignore - module may not be installed
        const { register } = await import('@tauri-apps/plugin-global-shortcut')
        // Register global shortcuts
        await register('CommandOrControl+Shift+F', () => {
          window.dispatchEvent(new CustomEvent('app:quick-add'))
        })
        await register('CommandOrControl+Shift+B', () => {
          window.dispatchEvent(new CustomEvent('app:toggle-window'))
        })
      } catch {
        // Not running in Tauri or plugin not available
      }
    }

    setup()

    return () => {
      unlisten?.()
    }
  }, [])
}

