  const [showForgotPw, setShowForgotPw] = useState(false)
  const [forgotEmail, setForgotEmail] = useState('')
  const [forgotSent, setForgotSent] = useState(false)

  useEffect(() => {
    document.title = 'FinPlan Pro — Login'
  }, [])

  // Redirect if already authenticated
  useEffect(() => {
    if (isAuthenticated) {
      navigate('/', { replace: true })
    }
  }, [isAuthenticated, navigate])

  const validate = (): boolean => {
    const result = loginSchema.safeParse({ email, password })
    if (!result.success) {
      const errors: Record<string, string> = {}
      for (const issue of result.error.issues) {
        const field = issue.path[0] as string
        errors[field] = issue.message
      }
      setFieldErrors(errors)
      return false
    }
    setFieldErrors({})
    return true
  }

  const handleLogin = async () => {
    if (!validate()) return
    clearError()
    try {
      await login(email, password)
      if (rememberMe) {
        localStorage.setItem('finplan_remembered_email', email)
      } else {
        localStorage.removeItem('finplan_remembered_email')
      }
      navigate('/', { replace: true })
    } catch {
      // Error is handled by authStore
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !isLoading) {
      handleLogin()
    }
  }

  const handleForgotPassword = () => {
    if (!forgotEmail) return
    // Simulate sending reset email (no backend)
    setForgotSent(true)
  }

  // Load remembered email
  useEffect(() => {
    const remembered = localStorage.getItem('finplan_remembered_email')
    if (remembered) {
      setEmail(remembered)
      setRememberMe(true)
    }
  }, [])

  // Forgot password UI
  if (showForgotPw) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4">
        <Card className="w-full max-w-sm">
          <CardContent className="p-6 space-y-6">
            <div className="text-center">
              <Mail className="h-10 w-10 text-blue-400 mx-auto mb-2" />
              <h1 className="text-xl font-bold">Reset Password</h1>
              <p className="text-sm text-slate-400 mt-1">
                Enter your email to receive a reset link.
              </p>
            </div>

            {forgotSent ? (
              <div className="text-center space-y-4">
                <div className="p-3 bg-green-900/30 text-green-400 rounded-lg text-sm">
                  If an account exists for <strong>{forgotEmail}</strong>, a reset link has been
                  sent.
                </div>
                <Button
                  variant="outline"
                  className="w-full"
                  onClick={() => {
                    setShowForgotPw(false)
                    setForgotSent(false)
                  }}
                >
                  Back to Login
                </Button>
              </div>
            ) : (
              <div className="space-y-4">
                <div>
                  <label className="block text-xs text-slate-400 mb-1">Email</label>
                  <Input
                    type="email"
                    value={forgotEmail}
                    onChange={(e) => setForgotEmail(e.target.value)}
                    placeholder="you@company.com"
                    onKeyDown={(e) => e.key === 'Enter' && handleForgotPassword()}
                  />
                </div>
                <Button className="w-full" onClick={handleForgotPassword}>
                  Send Reset Link
                </Button>
                <Button variant="outline" className="w-full" onClick={() => setShowForgotPw(false)}>
                  Back to Login
                </Button>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    )
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4">
      <Card className="w-full max-w-sm">
        <CardContent className="p-6 space-y-6">
          <div className="text-center">
            <LogIn className="h-10 w-10 text-blue-400 mx-auto mb-2" />
            <h1 className="text-xl font-bold">FinPlan Pro</h1>
            <p className="text-sm text-slate-400 mt-1">Sign in to your workspace</p>
          </div>

          {/* Global error */}
          {error && (
            <div
              className="flex items-start gap-2 p-3 bg-red-900/30 text-red-400 rounded-lg text-sm"
              role="alert"
            >
              <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />
              <span>{error}</span>
            </div>
          )}

          <div className="space-y-4" onKeyDown={handleKeyDown}>
            {/* Email */}
            <div>
              <label htmlFor="login-email" className="block text-xs text-slate-400 mb-1">
                Email
              </label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-500" />
                <Input
                  id="login-email"
                  type="email"
                  value={email}
                  onChange={(e) => {
                    setEmail(e.target.value)
                    setFieldErrors((p) => ({ ...p, email: '' }))
                  }}
                  placeholder="you@company.com"
                  className="pl-10"
                  autoComplete="email"
                  aria-invalid={!!fieldErrors.email}
                  aria-describedby={fieldErrors.email ? 'email-error' : undefined}
                />
              </div>
              {fieldErrors.email && (
                <p id="email-error" className="text-xs text-red-400 mt-1">
                  {fieldErrors.email}
                </p>
              )}
            </div>

            {/* Password */}
            <div>
              <div className="flex items-center justify-between mb-1">
                <label htmlFor="login-password" className="block text-xs text-slate-400">
                  Password
                </label>
                <button
                  type="button"
                  onClick={() => {
                    setShowForgotPw(true)
                    setForgotEmail(email)
                  }}
                  className="text-xs text-blue-400 hover:text-blue-300 transition-colors"
                >
                  Forgot password?
                </button>
              </div>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-500" />
                <Input
                  id="login-password"
                  type={showPw ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => {
                    setPassword(e.target.value)
                    setFieldErrors((p) => ({ ...p, password: '' }))
                  }}
                  placeholder="Enter password"
                  className="pl-10 pr-10"
                  autoComplete="current-password"
                  aria-invalid={!!fieldErrors.password}
                  aria-describedby={fieldErrors.password ? 'password-error' : undefined}
                />
                <button
                  type="button"
                  onClick={() => setShowPw(!showPw)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 hover:text-slate-300"
                  aria-label={showPw ? 'Hide password' : 'Show password'}
                >
                  {showPw ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                </button>
              </div>
              {fieldErrors.password && (
                <p id="password-error" className="text-xs text-red-400 mt-1">
                  {fieldErrors.password}
                </p>
              )}
            </div>

            {/* Remember me */}
            <div className="flex items-center gap-2">
              <input
                id="remember-me"
                type="checkbox"
                checked={rememberMe}
                onChange={(e) => setRememberMe(e.target.checked)}
                className="h-4 w-4 rounded border-slate-600 bg-slate-800 text-blue-500 focus:ring-blue-500"
              />
              <label htmlFor="remember-me" className="text-xs text-slate-400 cursor-pointer">
                Remember my email
              </label>
            </div>

            {/* Submit */}
            <Button className="w-full" onClick={handleLogin} disabled={isLoading}>
              {isLoading ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Signing in...
                </>
              ) : (
                'Sign In'
              )}
            </Button>
          </div>

          {/* Demo hint */}
          <div className="p-3 bg-slate-800/50 rounded-lg text-xs text-slate-400 space-y-1">
            <p className="font-medium text-slate-300">Offline Demo Accounts:</p>
            <p>
              <code className="text-blue-400">admin@finplan.com</code> — Admin (full access)
            </p>
            <p>
              <code className="text-blue-400">analyst@finplan.com</code> — Analyst
            </p>
            <p>
              <code className="text-blue-400">viewer@finplan.com</code> — Viewer (read-only)
            </p>
            <p className="text-slate-500">Any password works in offline mode.</p>
          </div>

          <p className="text-xs text-center text-slate-500">
            Don&apos;t have an account?{' '}
            <Link to="/register" className="text-blue-400 hover:text-blue-300">
              Register
            </Link>
          </p>
        </CardContent>
      </Card>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuthStore } from '@/store/authStore'
import { Button } from '@/components/ui/Button'
import { Input } from '@/components/ui/Input'
import { Card, CardContent } from '@/components/ui/Card'
import { UserPlus, AlertCircle, Loader2 } from 'lucide-react'

export function RegisterPage() {
  const navigate = useNavigate()
  const { register, isLoading, error, isAuthenticated } = useAuthStore()
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [localError, setLocalError] = useState('')

  useEffect(() => {
    if (isAuthenticated) navigate('/')
  }, [isAuthenticated, navigate])

  useEffect(() => {
    document.title = 'FinPlan Pro — Create Account'
  }, [])

  const handleRegister = async () => {
    setLocalError('')

    if (!name || !email || !password || !confirmPassword) {
      setLocalError('All fields are required.')
      return
    }

    if (password !== confirmPassword) {
      setLocalError('Passwords do not match.')
      return
    }

    if (password.length < 8) {
      setLocalError('Password must be at least 8 characters.')
      return
    }

    try {
      await register(name, email, password)
    } catch {
      // error is set in store
    }
  }

  const displayError = localError || error

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4">
      <Card className="w-full max-w-sm">
        <CardContent className="p-6 space-y-6">
          <div className="text-center">
            <UserPlus className="h-10 w-10 text-blue-400 mx-auto mb-2" />
            <h1 className="text-xl font-bold">Create Account</h1>
            <p className="text-sm text-slate-400">Set up your FinPlan Pro workspace</p>
          </div>

          {displayError && (
            <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/20 rounded-md text-red-400 text-sm">
              <AlertCircle className="h-4 w-4 flex-shrink-0" />
              {displayError}
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label className="block text-xs text-slate-400 mb-1">Full Name</label>
              <Input
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="John Doe"
                disabled={isLoading}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Email</label>
              <Input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="you@company.com"
                disabled={isLoading}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Password</label>
              <Input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Min 8 characters"
                disabled={isLoading}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Confirm Password</label>
              <Input
                type="password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="Repeat password"
                disabled={isLoading}
                onKeyDown={(e) => e.key === 'Enter' && handleRegister()}
              />
            </div>
            <Button className="w-full" onClick={handleRegister} disabled={isLoading}>
              {isLoading ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" /> Creating Account...
                </>
              ) : (
                'Create Account'
              )}
            </Button>
          </div>

          <p className="text-xs text-center text-slate-500">
            Already have an account?{' '}
            <button onClick={() => navigate('/login')} className="text-blue-400 hover:underline">
              Sign in
            </button>
          </p>
        </CardContent>
      </Card>
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { useUndoRedo } from '@/hooks/useUndoRedo'
import { useLocation } from 'react-router-dom'
import { useNavigate } from 'react-router-dom'
import { useBudgetStore } from '@/store/budgetStore'
import { useGLStore } from '@/store/glStore'
import { ProgressStepper } from '@/components/ui/ProgressStepper'
import { Input } from '@/components/ui/Input'
import { Select } from '@/components/ui/Select'
import { Button } from '@/components/ui/Button'
import { Card, CardContent } from '@/components/ui/Card'
import { Alert } from '@/components/ui/Alert'
import { ArrowLeft, ArrowRight, Check, DollarSign } from 'lucide-react'

export function BudgetCreatePage() {
  const [helpOpen, setHelpOpen] = useState(false)

  useEffect(() => {
    document.title = 'FinPlan Pro — Budget Create'
  }, [])

  const navigate = useNavigate()
  const { createBudget, budgets } = useBudgetStore()
  const { accounts } = useGLStore()
  const [step, setStep] = useState(0)
  const [form, setForm] = useState({
    name: '',
    fiscalYear: new Date().getFullYear(),
    baseCurrency: 'USD',
    description: '',
    budgetMethod: 'incremental' as 'incremental' | 'zero-based',
  })
  const [selectedAccountIds, setSelectedAccountIds] = useState<string[]>([])
  const [amounts, setAmounts] = useState<Record<string, number>>({})
  const [formErrors, setFormErrors] = useState<Record<string, string>>({})

  const totalAmount = useMemo(() => {
    let total = 0
    for (const key of Object.keys(amounts)) {
      total += amounts[key] || 0
    }
    return total
  }, [amounts])

  const accountOptions = useMemo(
    () => [...accounts.map((a) => ({ value: a.id, label: a.code + ' — ' + a.name }))],
    [accounts]
  )

  const steps: { label: string; status: 'done' | 'current' | 'pending'; description: string }[] =
    useMemo(
      () => [
        {
          label: 'Details',
          status: step > 0 ? 'done' : step === 0 ? 'current' : 'pending',
          description: 'Budget info',
        },
        {
          label: 'Accounts',
          status: step > 1 ? 'done' : step === 1 ? 'current' : 'pending',
          description: 'Select accounts',
        },
        {
          label: 'Amounts',
          status: step > 2 ? 'done' : step === 2 ? 'current' : 'pending',
          description: 'Set amounts',
        },
        {
          label: 'Review',
          status: step > 3 ? 'done' : step === 3 ? 'current' : 'pending',
          description: 'Confirm & create',
        },
      ],
      [step]
    )

  const validateStep = (s: number): boolean => {
    const errors: Record<string, string> = {}
    if (s === 0) {
      if (!form.name || form.name.length < 2) errors.name = 'Name must be at least 2 characters'
    }
    if (s === 1) {
      if (selectedAccountIds.length === 0) errors.accounts = 'Select at least one account'
    }
    setFormErrors(errors)
    return Object.keys(errors).length === 0
  }

  const handleNext = () => {
    if (validateStep(step)) setStep((s) => s + 1)
  }

  const handleCreate = (status: 'Draft' | 'InReview') => {
    if (totalAmount === 0 && !window.confirm('Total amount is $0. Create budget anyway?')) return
    const budgetId = createBudget({
      name: form.name,
      fiscalYear: form.fiscalYear,
      baseCurrency: form.baseCurrency,
      description: form.description,
      template: 'default',
      totalAmount,
      departments: [],
      entities: ['default'],
      status,
      createdByName: 'Current User',
      submittedAt: status === 'InReview' ? new Date().toISOString() : null,
      approvedAt: null,
      approvedBy: null,
      version: 1,
      progress: 0,
    })

    const lineItems = selectedAccountIds.flatMap((id) => {
      const account = accounts.find((a) => a.id === id)
      return Array.from({ length: 12 }, (_, m) => ({
        id: `bli-${id}-${m}-${Date.now()}`,
        budgetId,
        accountId: id,
        accountName: account?.name ?? '',
        accountCode: account?.code ?? '',
        accountType: (account?.type ?? 'Expense') as import('@/types').AccountType,
        periodId: `p-${m}`,
        month: m + 1,
        amount: amounts[id + '-' + m] ?? 0,
        formula: null,
        isCalculated: false,
        isLocked: false,
        isReadOnly: false,
        notes: null,
        driverId: null,
        assumptions: null,
        version: 1,
        createdBy: 'usr-001',
        updatedBy: 'usr-001',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      }))
    })
    useBudgetStore.getState().setLineItems(lineItems)

    navigate('/budgets/' + budgetId)
  }

  if (accounts.length === 0) {
    return (
      <div className="p-12 text-center max-w-md mx-auto">
        <h2 className="text-xl font-semibold mb-2">No Accounts Defined</h2>
        <p className="text-slate-400 mb-6">
          Create your Chart of Accounts first before creating budgets.
        </p>
        <Button onClick={() => navigate('/data/chart-of-accounts')}>Set Up Accounts</Button>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center justify-between mb-6">
            <h1 className="text-2xl font-bold">Create Budget</h1>
            <button
              onClick={() => setHelpOpen(true)}
              className="p-2 hover:bg-slate-800 rounded-full text-slate-500 hover:text-white transition-colors"
              aria-label="Help"
            ></button>
          </div>
          <p className="text-sm text-slate-400 mt-1">
            Set up a new budget for planning and tracking
          </p>
        </div>
        <Button variant="ghost" onClick={() => navigate('/budgets')}>
          Cancel
        </Button>
      </div>

      <ProgressStepper steps={steps} currentStep={step} />

      {step === 0 && (
        <Card>
          <CardContent className="p-6 space-y-4">
            <h3 className="font-semibold">Budget Details</h3>
            <div>
              <label htmlFor="budget-name" className="block text-xs font-medium text-slate-400 mb-1">Budget Name</label>
              <Input
                id="budget-name"
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                placeholder="e.g. FY2025 Annual Operating Budget"
                className={formErrors.name ? 'border-red-500' : ''}
              />
              {formErrors.name && <p className="text-xs text-red-400 mt-1">{formErrors.name}</p>}
            </div>
            <div>
              <label htmlFor="budget-year" className="block text-xs font-medium text-slate-400 mb-1">Fiscal Year</label>
              <Input
                id="budget-year"
                type="number"
                value={form.fiscalYear}
                onChange={(e) =>
                  setForm({
                    ...form,
                    fiscalYear: parseInt(e.target.value) || new Date().getFullYear(),
                  })
                }
              />
            </div>
            <div>
              <label htmlFor="budget-currency" className="block text-xs font-medium text-slate-400 mb-1">Base Currency</label>
              <Select
                options={[{ value: 'USD', label: 'USD — US Dollar' }]}
                value={form.baseCurrency}
                onChange={(v) => setForm({ ...form, baseCurrency: v })}
              />
            </div>
            <div>
              <label htmlFor="budget-method" className="block text-xs font-medium text-slate-400 mb-1">Budget Method</label>
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={() => setForm({ ...form, budgetMethod: 'incremental' })}
                  className={`flex-1 px-3 py-2 rounded-lg text-sm border transition-colors ${
                    form.budgetMethod === 'incremental'
                      ? 'bg-blue-900/30 border-blue-600 text-blue-300'
                      : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-600'
                  }`}
                >
                  <div className="font-medium">Incremental</div>
                  <div className="text-xs opacity-70">Build on prior year actuals</div>
                </button>
                <button
                  type="button"
                  onClick={() => setForm({ ...form, budgetMethod: 'zero-based' })}
                  className={`flex-1 px-3 py-2 rounded-lg text-sm border transition-colors ${
                    form.budgetMethod === 'zero-based'
                      ? 'bg-emerald-900/30 border-emerald-600 text-emerald-300'
                      : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-600'
                  }`}
                >
                  <div className="font-medium">Zero-Based</div>
                  <div className="text-xs opacity-70">Justify every dollar from $0</div>
                </button>
              </div>
            </div>
            <div>
              <label htmlFor="budget-desc" className="block text-xs font-medium text-slate-400 mb-1">
                Description (optional)
              </label>
              <textarea
                id="budget-desc"
                className="w-full bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-200 min-h-[80px] focus:outline-none focus:ring-2 focus:ring-blue-500"
                value={form.description}
                onChange={(e) => setForm({ ...form, description: e.target.value })}
                placeholder="Brief description of this budget..."
              />
            </div>
            <div className="flex justify-end">
              <Button onClick={handleNext}>
                Next
                <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {step === 1 && (
        <Card>
          <CardContent className="p-6 space-y-4">
            <h3 className="font-semibold">Select Accounts</h3>
            <p className="text-sm text-slate-400">Choose the accounts to include in this budget.</p>
            {formErrors.accounts && (
              <Alert type="error" title="Validation Error" message={formErrors.accounts} />
            )}
            <div className="max-h-64 overflow-y-auto space-y-1">
              {accounts.map((a) => {
                const selected = selectedAccountIds.includes(a.id)
                return (
                  <label
                    key={a.id}
                    className={
                      'flex items-center gap-3 p-2 rounded-lg cursor-pointer transition-colors ' +
                      (selected
                        ? 'bg-blue-900/30 border border-blue-800/50'
                        : 'hover:bg-slate-800/50 border border-transparent')
                    }
                  >
                    <input
                      type="checkbox"
                      checked={selected}
                      onChange={() =>
                        setSelectedAccountIds((prev) =>
                          prev.includes(a.id) ? prev.filter((id) => id !== a.id) : [...prev, a.id]
                        )
                      }
                      className="rounded"
                    />
                    <div>
                      <div className="text-sm font-medium">
                        {a.code} — {a.name}
                      </div>
                      <div className="text-xs text-slate-500">
                        {a.type} · {a.category}
                      </div>
                    </div>
                  </label>
                )
              })}
            </div>
            <div className="flex justify-between">
              <Button variant="ghost" onClick={() => setStep(0)}>
                <ArrowLeft className="h-4 w-4 mr-2" />
                Back
              </Button>
              <Button onClick={handleNext} disabled={selectedAccountIds.length === 0}>
                Next
                <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {step === 2 && (
        <Card>
          <CardContent className="p-6 space-y-4">
            <h3 className="font-semibold">Set Amounts</h3>
            <p className="text-sm text-slate-400">
              Enter monthly amounts for each selected account.
            </p>
            <div className="space-y-4 max-h-96 overflow-y-auto">
              {selectedAccountIds.map((id) => {
