import { useEffect, useMemo, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useGLStore } from '@/store/glStore'
import { Button } from '@/components/ui/Button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { KPIValue } from '@/components/ui/KPIValue'
import { DataTable, type Column } from '@/components/ui/DataTable'
import {
  Store,
  TrendingUp,
  Download,
  FileText,
  Table as TableIcon,
  ShoppingCart,
  DollarSign,
} from 'lucide-react'
import { ExportEngine } from '@/engines/ExportEngine'
import { ManufacturingEngine } from '@/engines/ManufacturingEngine'
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts'

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n)
}

interface StoreRow {
  store: string
  revenue: number
  transactions: number
  avgBasket: number
  yoyGrowth: number
}

export function StoreDashboardPage() {
  const { entries } = useGLStore()
  const navigate = useNavigate()

  useEffect(() => {
    document.title = 'FinPlan Pro — Store Dashboard'
  }, [])

  const randomRef = useRef<null | { rev: number[]; txn: number[]; growth: number[] }>(null)
  if (!randomRef.current) {
    const rev = Array.from({ length: 5 }, () => Math.random())
    const txn = Array.from({ length: 5 }, () => Math.random())
    const growth = Array.from({ length: 5 }, () => Math.random())
    randomRef.current = { rev, txn, growth }
  }

  const data = useMemo(() => {
    if (entries.length === 0) return null
    const revenueEntries = entries.filter((e) => (e.accountCode || '').startsWith('4'))
    const cogsEntries = entries.filter((e) => (e.accountCode || '').startsWith('5'))
    const totalRevenue = revenueEntries.reduce((s, e) => s + (e.debit - e.credit), 0)
    const totalCOGS = cogsEntries.reduce((s, e) => s + Math.abs(e.debit - e.credit), 0)
    const grossMargin = totalRevenue > 0 ? ((totalRevenue - totalCOGS) / totalRevenue) * 100 : 0
    const storeNames = ['Downtown', 'Mall', 'Airport', 'Online', 'Suburban']
    const { rev, txn, growth } = randomRef.current!
    const storeData: StoreRow[] = storeNames.map((name, i) => {
      const storeRev = totalRevenue * (0.15 + rev[i] * 0.2)
      const storeTxn = Math.floor(storeRev / (40 + txn[i] * 30))
      return {
        store: name,
        revenue: storeRev,
        transactions: storeTxn,
        avgBasket: storeTxn > 0 ? storeRev / storeTxn : 0,
        yoyGrowth: 5 + growth[i] * 20,
      }
    })
    return {
      totalRevenue,
      totalCOGS,
      grossMargin,
      storeData,
      chartData: storeData.map((s) => ({
        name: s.store,
        revenue: Math.round(s.revenue),
        transactions: s.transactions,
      })),
    }
  }, [entries])

  const handleExportPDF = () => {
    if (!data) return
    ExportEngine.exportToPDF(
      {
        headers: ['Store', 'Revenue', 'Transactions', 'Avg Basket', 'YoY Growth'],
        rows: data.storeData.map((s) => [
          s.store,
          formatCurrency(s.revenue),
          s.transactions.toString(),
          formatCurrency(s.avgBasket),
          s.yoyGrowth.toFixed(1) + '%',
        ]),
      },
      { title: 'Store Dashboard Report', companyName: 'FinPlan Pro' }
    )
  }

  const handleExportExcel = () => {
    if (!data) return
    ExportEngine.exportToExcel(
      {
        headers: ['Store', 'Revenue', 'Transactions', 'Avg Basket', 'YoY Growth'],
        rows: data.storeData.map((s) => [
          s.store,
          formatCurrency(s.revenue),
          s.transactions.toString(),
          formatCurrency(s.avgBasket),
          s.yoyGrowth.toFixed(1) + '%',
        ]),
      },
      { title: 'Store_Dashboard_Report' }
    )
  }

  const columns: Column[] = [
    { key: 'store', header: 'Store', sortable: true },
    {
      key: 'revenue',
      header: 'Revenue',
      align: 'right',
      render: (_, r) => formatCurrency(Number(r.revenue)),
      sortable: true,
    },
    {
      key: 'transactions',
      header: 'Transactions',
      align: 'right',
      render: (_, r) => Number(r.transactions).toLocaleString(),
      sortable: true,
    },
    {
      key: 'avgBasket',
      header: 'Avg Basket',
      align: 'right',
      render: (_, r) => formatCurrency(Number(r.avgBasket)),
      sortable: true,
    },
    {
      key: 'yoyGrowth',
      header: 'YoY Growth',
      align: 'right',
      render: (_, r) => (
        <span className={Number(r.yoyGrowth) >= 0 ? 'text-green-400' : 'text-red-400'}>
          {Number(r.yoyGrowth).toFixed(1)}%
        </span>
      ),
      sortable: true,
    },
  ]

  if (entries.length === 0)
    return (
      <div className="p-12 text-center">
        <Store className="h-10 w-10 text-slate-400 mx-auto mb-4" />
        <h2 className="text-xl font-semibold mb-2">No Retail Data</h2>
        <p className="text-slate-400 mb-6">Import GL data to view store performance.</p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    )

  return (
    <div className="p-6 space-y-6 animate-fade-in">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">Store Dashboard</h1>
        <div className="flex gap-2">
          <Button size="sm" variant="ghost" onClick={handleExportPDF} aria-label="Export PDF">
            <FileText className="h-3.5 w-3.5 mr-1.5" />
            PDF
          </Button>
          <Button size="sm" variant="ghost" onClick={handleExportExcel} aria-label="Export Excel">
            <TableIcon className="h-3.5 w-3.5 mr-1.5" />
            Excel
          </Button>
        </div>
      </div>
      {data && (
        <>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <KPIValue
              label="Total Revenue"
              value={formatCurrency(data.totalRevenue)}
              icon={<DollarSign className="h-4 w-4" />}
            />
            <KPIValue
              label="Total COGS"
              value={formatCurrency(data.totalCOGS)}
              icon={<ShoppingCart className="h-4 w-4" />}
            />
            <KPIValue
              label="Gross Margin"
              value={`${data.grossMargin.toFixed(1)}%`}
              icon={<TrendingUp className="h-4 w-4" />}
            />
            <KPIValue
              label="Store Count"
              value={data.storeData.length.toString()}
              icon={<Store className="h-4 w-4" />}
            />
          </div>
          <Card>
            <CardHeader>
              <CardTitle>Revenue by Store</CardTitle>
            </CardHeader>
            <CardContent>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={data.chartData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                  <XAxis dataKey="name" stroke="#94a3b8" fontSize={12} />
                  <YAxis
                    stroke="#94a3b8"
                    fontSize={12}
                    tickFormatter={(v) => `$${(v / 1000).toFixed(0)}k`}
                  />
                  <Tooltip
                    formatter={(v: any) => formatCurrency(v)}
                    contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155' }}
                  />
                  <Legend />
                  <Bar dataKey="revenue" fill="#3b82f6" name="Revenue" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </CardContent>
          </Card>
          <DataTable columns={columns} data={data.storeData} />
        </>
      )}
    </div>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

/**
 * Shallow equality check for store selectors
 * Prevents unnecessary re-renders when selecting objects
 */
export function shallowEqual<T>(a: T, b: T): boolean {
  if (a === b) return true
  if (a == null || b == null) return false
  if (typeof a !== 'object' || typeof b !== 'object') return false

  const keysA = Object.keys(a as object)
  const keysB = Object.keys(b as object)

  if (keysA.length !== keysB.length) return false

  for (const key of keysA) {
    if ((a as Record<string, unknown>)[key] !== (b as Record<string, unknown>)[key]) {
      return false
    }
  }

  return true
}

/**
 * Stable selector factory for Zustand stores
 * Returns a memoized selector that uses shallow equality
 */
export function createSelector<T, R>(
  selector: (state: T) => R,
  isEqual: (a: R, b: R) => boolean = shallowEqual as (a: R, b: R) => boolean
): (state: T) => R {
  let lastResult: R
  let lastState: T

  return (state: T): R => {
    if (state === lastState) return lastResult
    const result = selector(state)
    if (isEqual(result, lastResult)) {
      lastState = state
      return lastResult
    }
    lastState = state
    lastResult = result
    return result
  }
}

/**
 * Debounced value hook
 * Returns a value that only updates after `delay` ms of no changes
 */
export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value)

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedValue(value), delay)
    return () => clearTimeout(handler)
  }, [value, delay])

  return debouncedValue
}

/**
 * Throttled callback hook
 * Ensures callback is called at most once per `delay` ms
 */
export function useThrottle<T extends (...args: unknown[]) => unknown>(fn: T, delay: number): T {
  const lastCall = useRef(0)
  const lastCallTimer = useRef<ReturnType<typeof setTimeout>>(undefined)

  return useCallback(
    ((...args: unknown[]) => {
      const now = Date.now()
      if (now - lastCall.current >= delay) {
        lastCall.current = now
        fn(...args)
      } else {
        clearTimeout(lastCallTimer.current)
        lastCallTimer.current = setTimeout(
          () => {
            lastCall.current = Date.now()
            fn(...args)
          },
          delay - (now - lastCall.current)
        )
      }
    }) as T,
    [fn, delay]
  )
}

/**
 * Memoized computation hook
 * Only recomputes when dependencies change
 */
export function useMemoizedComputation<T>(
  compute: () => T,
  deps: unknown[],
  isEqual: (a: T, b: T) => boolean = shallowEqual as (a: T, b: T) => boolean
): T {
  const ref = useRef<{ value: T } | null>(null)

  return useMemo(() => {
    const newValue = compute()
    if (ref.current && isEqual(ref.current.value, newValue)) {
      return ref.current.value
    }
    ref.current = { value: newValue }
    return newValue
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)
}
